head.b:skin:
/* =========================
   CENTRALIZED TYPOGRAPHY SYSTEM
   (variables only - not applied to any element yet)
========================= */

:root{
--font-logo:'Orbitron',sans-serif;
--font-heading:'Space Grotesk',sans-serif;
--font-body:'Inter',sans-serif;
}

/* =========================
   LIVE STATS
========================= */

.stats-section{
padding:28px 16px;
}

.stats-grid{

display:grid;
grid-template-columns:
repeat(auto-fit,minmax(180px,1fr));

gap:14px;

}

.stats-card{

padding:20px;

border-radius:20px;

background:rgba(255,255,255,.04);

border:1px solid rgba(255,255,255,.08);

text-align:center;

transition:.3s ease;

}

.stats-card:hover{

transform:translateY(-6px);

border-color:rgba(0,234,255,.28);

box-shadow:
0 10px 30px rgba(0,234,255,.12);

}

.stats-number{

font-size:34px;
font-weight:900;

color:#00eaff;

margin-bottom:8px;

}

.stats-label{

font-size:14px;

color:rgba(255,255,255,.72);

font-weight:600;

}

@media(max-width:768px){

.stats-number{
font-size:28px;
}

}

html,
body{

margin:0;
padding:0;
overflow-wrap:break-word;
width:100%;
max-width:100%;

overflow-x:hidden;

font-family:Arial;

background:#000;
color:#fff;
padding-top:50px;

touch-action:pan-y;

scroll-behavior:auto;

}

.header{

position:fixed;

top:0;
left:0;
right:0;

width:100%;

z-index:99999;

display:flex;
align-items:center;
justify-content:space-between;
gap:14px;

padding:5px 16px;

background:rgba(8,8,8,.78);

backdrop-filter:blur(16px);
-webkit-backdrop-filter:blur(16px);

border-bottom:1px solid rgba(255,255,255,.06);

box-shadow:
0 8px 24px rgba(0,0,0,.18);

transition:
transform .35s ease,
background .35s ease,
box-shadow .35s ease;

will-change:transform;

}

.header.scrolled{

background:rgba(5,5,5,.94);

backdrop-filter:blur(22px);
-webkit-backdrop-filter:blur(22px);

box-shadow:
0 10px 35px rgba(0,0,0,.35);

}

.logo a img:hover{
transform:scale(1.05);
transition:.3s;
}

.menu{

display:flex;

align-items:center;

gap:6px;

flex-wrap:nowrap;

white-space:nowrap;

min-width:0;

}

.menu a{
display:flex;
align-items:center;
white-space:nowrap;
flex-shrink:0;
padding:10px 14px;
border-radius:12px;
color:#fff;
text-decoration:none;
font-weight:500;
font-size:13px;
transition:.3s ease;
font-family:'Manrope',sans-serif;
letter-spacing:.3px;
}

.logo{
display:flex;
justify-content:center;
align-items:center;
font-family:var(--font-logo);
}

.logo img{
height:48px;
width:auto;
max-width:220px;
object-fit:contain;
}

/* =========================
   SAVED PROMPTS HEADER BUTTON
========================= */

.saved-prompts-btn{

display:flex;
align-items:center;
gap:8px;

padding:10px 16px;

border-radius:999px;

background:rgba(255,255,255,.06);

border:1px solid rgba(255,255,255,.08);

backdrop-filter:blur(12px);
-webkit-backdrop-filter:blur(12px);

color:#fff !important;

font-size:13px;
font-weight:500;
font-family:'Manrope',sans-serif;
letter-spacing:.3px;

text-decoration:none;

transition:.3s ease;

margin-left:12px;

white-space:nowrap;

}

.saved-prompts-btn:hover{

transform:translateY(-2px);

background:rgba(0,234,255,.10);

border-color:rgba(0,234,255,.28);

color:#00eaff !important;

box-shadow:
0 0 18px rgba(0,234,255,.18);

}

.saved-prompts-btn svg{

width:18px;
height:18px;

stroke:currentColor;

}

@media(max-width:768px){

.saved-prompts-btn{
display:none;
}

}

.menu a:hover,
.menu a.active,
.dropdown.active-child > a,
.sub-drop.active-child > a {
color:#00eaff;
background:rgba(0,234,255,.08);
}

.menu a.active {
border: 1px solid rgba(0,234,255,.2);
}

/* Ensure Sub-Menu Text is visible on hover */
.sub-menu a:hover,
.small-drop a:hover {
color: #fff !important;
background: #3b82f6 !important;
}

    .category h2 {
  font-size: 32px;        
  font-family: Arial;  
  font-weight: bold;      
  color: #ffffff;         
  text-transform: uppercase; 
  padding:40px;
}

    .one-click {
      text-align:center;
      padding:32px 8px;
    }

    .one-click h2 {
      font-family: var(--font-heading);
    }


    .oc-fan-wrap {
      display:flex;
      align-items:flex-end;
      justify-content:center;
      gap:0;
      padding:40px 10px 80px;
      overflow:visible;
      position:relative;
      width:100%;
      max-width:1200px;
      margin:0 auto;
      box-sizing:border-box;
    }

    .oc-card {
      position:relative;
      border-radius:18px;
      overflow:hidden;
      flex-shrink:0;
      cursor:pointer;
      transition:transform 0.35s cubic-bezier(.22,1,.36,1),
                 z-index 0s,
                 box-shadow 0.35s ease;
      background:#111;
      box-shadow:0 8px 32px rgba(0,0,0,0.55);
      border: 1px solid rgba(255,255,255,0.05);
    }

    /* DESKTOP SIZES - PROFESSIONALLY SCALED */
    .oc-card-1 { width:110px; aspect-ratio:2/3; z-index:1;  margin-right:-35px; transform:rotate(-14deg) translateY(50px); }
    .oc-card-2 { width:135px; aspect-ratio:2/3; z-index:2;  margin-right:-30px; transform:rotate(-10deg) translateY(34px); }
    .oc-card-3 { width:165px; aspect-ratio:2/3; z-index:3;  margin-right:-25px; transform:rotate(-6deg)  translateY(18px); }
    .oc-card-4 { width:200px; aspect-ratio:2/3; z-index:4;  margin-right:-20px; transform:rotate(-3deg)  translateY(7px);  }
    .oc-card-5 { width:250px; aspect-ratio:2/3; z-index:5;  margin:0 4px;       transform:rotate(0deg)   translateY(0px);  }
    .oc-card-6 { width:200px; aspect-ratio:2/3; z-index:4;  margin-left:-20px;  transform:rotate(3deg)   translateY(7px);  }
    .oc-card-7 { width:165px; aspect-ratio:2/3; z-index:3;  margin-left:-25px;  transform:rotate(6deg)   translateY(18px); }
    .oc-card-8 { width:135px; aspect-ratio:2/3; z-index:2;  margin-left:-30px;  transform:rotate(10deg)  translateY(34px); }
    .oc-card-9 { width:110px; aspect-ratio:2/3; z-index:1;  margin-left:-35px;  transform:rotate(14deg)  translateY(50px); }

    .oc-card img {
      width:100%;
      height:100%;
      object-fit:cover;
      display:block;
      pointer-events:none;
    }

    .oc-card:hover {
      z-index:99 !important;
      transform:rotate(0deg) translateY(-24px) scale(1.08) !important;
      box-shadow: 0 0 30px rgba(0,234,255,0.8), 0 15px 50px rgba(0,0,0,0.7);
      border: 2px solid #00eaff;
    }

    @media (max-width:1100px) {
      .oc-card-1, .oc-card-9 { display:none; }
      .oc-card-5 { width:220px; }
      .oc-card-4, .oc-card-6 { width:170px; }
      .oc-card-3, .oc-card-7 { width:140px; }
      .oc-card-2, .oc-card-8 { width:110px; }
    }

    @media (max-width:768px) {
      .oc-fan-wrap { padding:30px 6px 60px; }
      .oc-card-2 { width:80px;  margin-right:-20px; transform:rotate(-12deg) translateY(26px); }
      .oc-card-3 { width:100px; margin-right:-18px; transform:rotate(-8deg)  translateY(16px); }
      .oc-card-4 { width:125px; margin-right:-15px; transform:rotate(-4deg)  translateY(7px);  }
      .oc-card-5 { width:160px; margin:0 3px;       transform:rotate(0deg)   translateY(0px);  }
      .oc-card-6 { width:125px; margin-left:-15px;  transform:rotate(4deg)   translateY(7px);  }
      .oc-card-7 { width:100px; margin-left:-18px;  transform:rotate(8deg)   translateY(16px); }
      .oc-card-8 { width:80px;  margin-left:-20px;  transform:rotate(12deg)  translateY(26px); }
    }

    @media (max-width:480px) {
      .oc-fan-wrap { padding:20px 4px 50px; }
      .oc-card-2 { width:60px;  margin-right:-18px; transform:rotate(-12deg) translateY(22px); }
      .oc-card-3 { width:75px;  margin-right:-16px; transform:rotate(-8deg)  translateY(14px); }
      .oc-card-4 { width:95px;  margin-right:-14px; transform:rotate(-4deg)  translateY(6px);  }
      .oc-card-5 { width:125px; margin:0 2px;       transform:rotate(0deg)   translateY(0px);  }
      .oc-card-6 { width:95px;  margin-left:-14px;  transform:rotate(4deg)   translateY(6px);  }
      .oc-card-7 { width:75px;  margin-left:-16px;  transform:rotate(8deg)   translateY(14px); }
      .oc-card-8 { width:60px;  margin-left:-18px;  transform:rotate(12deg)  translateY(22px); }
    }


    @media (hover:none) {
      .oc-card:active {
        z-index:99 !important;
        transform:rotate(0deg) translateY(-14px) scale(1.08) !important;
        box-shadow:0 20px 50px rgba(0,0,0,0.65), 0 0 0 3px rgba(255,255,255,0.15) !important;
      }
    }

    .prompts {
      padding:24px;
    }

.sub-drop{
position:relative;
min-width:0;
padding:12px;
border-radius:18px;
background:linear-gradient(135deg,rgba(255,255,255,.07),rgba(255,255,255,.025));
border:1px solid rgba(255,255,255,.08);
box-shadow:
0 16px 36px rgba(0,0,0,.22),
inset 0 1px 0 rgba(255,255,255,.06);
transition:transform .35s cubic-bezier(.2,.8,.2,1),border-color .35s ease,box-shadow .35s ease;
}

.sub-drop:hover{
transform:translateY(-4px);
border-color:rgba(0,234,255,.32);
box-shadow:
0 20px 42px rgba(0,0,0,.32),
0 0 20px rgba(0,234,255,.10),
inset 0 1px 0 rgba(255,255,255,.08);
}

.menu .dropdown-content .sub-drop{
padding:0 !important;
margin:0 !important;
border:none !important;
border-radius:0 !important;
background:none !important;
box-shadow:none !important;
transform:none !important;
}
.menu .dropdown-content .sub-drop:hover{
transform:none !important;
border:none !important;
box-shadow:none !important;
background:none !important;
}

.ai-image-box{
  flex:0 0 auto;   
}

.compare-container > img,
.img-after img{

width:100%;

height:auto;

display:block;

object-fit:contain;

image-rendering:auto;

image-rendering:-webkit-optimize-contrast;

backface-visibility:hidden;

-webkit-backface-visibility:hidden;

transform:translateZ(0);

filter:contrast(1.02) saturate(1.03);

}

.img-before{
  display:block;
}

.img-after{

position:absolute;

top:0;
left:0;

width:100%;
height:100%;

overflow:hidden;

clip-path: inset(0 100% 0 0);

}

.img-after img{
  width:100%;
  height:100%;
  object-fit:cover;
}

.ba-label-wrap{

position:absolute;

top:0;
bottom:0;

width:50%;

overflow:hidden;

z-index:6;

pointer-events:none;

display:flex;
align-items:flex-end;

padding-bottom:14px;

}

.ba-before-wrap{
left:0;
}

.ba-after-wrap{
right:0;
justify-content:flex-end;
}

.ba-label{

font-family:'Orbitron',sans-serif;

font-size:20px;
font-weight:900;

letter-spacing:3px;

text-transform:uppercase;

color:#fff;

line-height:1;

white-space:nowrap;

user-select:none;

}

.ba-label-before{

margin-left:14px;

text-shadow:
0 0 6px #00eaff,
0 0 14px #00eaff,
0 0 28px rgba(0,234,255,.85),
0 0 55px rgba(0,234,255,.45);

}

.ba-label-after{

margin-right:14px;

text-align:right;

text-shadow:
0 0 6px #ff6ef7,
0 0 14px #ff6ef7,
0 0 28px rgba(255,110,247,.85),
0 0 55px rgba(255,110,247,.45);

}

@media(max-width:768px){

.ba-label{

font-size:14px;

letter-spacing:2px;

}

.ba-label-wrap{
padding-bottom:10px;
}

}

.slider{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  opacity:0;
  cursor:pointer;
  z-index:5;
}

.copy-btn img{
width:160px;
height:auto;
filter: drop-shadow(0 0 6px rgba(0,234,255,.25));
}

.copy-btn img:hover{
transform:translateY(-4px) scale(1.06);
filter:
drop-shadow(0 0 10px #00eaff)
drop-shadow(0 0 18px rgba(0,234,255,.6));
}

.copy-msg{
  position:absolute;
  bottom:110%;
  left:50%;
  transform:translateX(-50%);
  background:#00eaff;
  color:#000;
  padding:5px 10px;
  border-radius:6px;
  font-size:12px;
  opacity:0;
  pointer-events:none;
  transition:0.3s;
}

.premium-hero{
position:relative;
overflow:hidden;
padding:56px 16px;
text-align:left;
border-bottom:1px solid rgba(255,255,255,.06);
background-color:#080808;

background-image:
linear-gradient(
90deg,
rgba(8,8,8,.96) 0%,
rgba(8,8,8,.92) 40%,
rgba(8,8,8,.65) 60%,
rgba(8,8,8,.12) 78%,
rgba(8,8,8,.03) 100%
),
url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEj4GaIOkyjSst9PEqq9JuRzRAVlvKA5Rg67FmdWBZzHPvlhg2G-pcr_9SoFje4Olta4joEEJbHqt2CgXYpmL9GkhDsbuJKMfYUciFNnLOL7VnTWnd330i4dlK1mCsxU1nWdN69hgN6HCviT_4csMw7hgemJArITwrXlTLpADzgSWwOU57NWhTUv0eX1FAU/w800/MGStudio_Hero.webp');

background-repeat:no-repeat;
background-size:cover;
background-position:center right;
background-attachment:scroll;
}

.premium-hero-inner{
max-width:1050px;
margin:auto;
position:relative;
z-index:2;
}

.hero-badge{
display:inline-block;
padding:10px 18px;
border:1px solid rgba(0,234,255,.25);
border-radius:50px;
font-size:14px;
color:#00eaff;
background:rgba(0,234,255,.08);
margin-bottom:28px;
letter-spacing:.5px;
}

.premium-hero h1{
font-size:62px;
line-height:1.15;
font-weight:900;
color:#fff;
margin:0 0 20px;
letter-spacing:-1px;
content-visibility:auto;
contain-intrinsic-size:1px 500px;
font-family:var(--font-heading);
}

.premium-hero h1 span{
color:#00eaff;
text-shadow:0 0 18px rgba(0,234,255,.45);
}

.premium-hero p{
max-width:620px;
margin:auto auto 25px;
font-size:18px;
line-height:1.6;
color:#a8a8a8;
}

.hero-btns{
display:flex;
justify-content:center;
gap:16px;
flex-wrap:wrap;
margin-bottom:45px;
}

.hero-btns a{
padding:15px 30px;
border-radius:14px;
font-weight:800;
text-decoration:none;
transition:.35s ease;
font-size:16px;
}

.btn-primary{
background:#00eaff;
color:#000;
box-shadow:0 0 20px rgba(0,234,255,.28);
}

.btn-primary:hover{
transform:translateY(-4px);
box-shadow:0 0 30px rgba(0,234,255,.45);
}

.btn-outline{
border:1px solid #00eaff;
color:#00eaff;
background:transparent;
}

.btn-outline:hover{
transform:translateY(-4px);
background:rgba(0,234,255,.08);
}

.hero-stats{
display:flex;
justify-content:center;
gap:35px;
flex-wrap:wrap;

content-visibility:auto;
contain-intrinsic-size:1px 300px;
}

.hero-stats div{
min-width:130px;
padding:18px 20px;
background:#161616;
border-radius:16px;
border:1px solid rgba(255,255,255,.05);
}

.hero-stats strong{
display:block;
font-size:26px;
color:#fff;
margin-bottom:5px;
}

.hero-stats span{
font-size:14px;
color:#aaaaaa;
}

.hero-bg-glow{
display:none;
}

.hero-grid{
display:none;
}

@media(max-width:768px){

.premium-hero{
padding:40px 14px;
text-align:center;
background-position:center center;
}

.premium-hero h1{
font-size:32px;
line-height:1.2;
}

.premium-hero p{
font-size:15px;
}

.hero-btns a{
width:100%;
max-width:280px;
}

.hero-stats{
gap:15px;
}

.hero-stats div{
width:100%;
max-width:250px;
}
}

.glass-search-wrap{

flex:1;

max-width:420px;

width:100%;

margin-left:auto;

min-width:220px;

overflow:hidden;

}

.glass-search-wrap form{
display:flex;
align-items:center;
gap:12px;
padding:3px 10px;
width:100%;
max-width:100%;
box-sizing:border-box;
min-width:0;

background:rgba(255,255,255,0.06);
border:1px solid rgba(255,255,255,0.10);
border-radius:14px;

backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);

box-shadow:
0 8px 24px rgba(0,0,0,0.30),
inset 0 1px 0 rgba(255,255,255,0.05);

transition:0.35s ease;
}

.glass-search-wrap form:hover{
transform:translateY(-2px);
border-color:#00eaff;
box-shadow:0 0 20px rgba(0,234,255,0.18);
}

.glass-search-wrap input{
flex:1;
min-width:0;
border:none;
outline:none;
background:transparent;
color:#fff;
font-size:15px;
font-weight:500;
padding:8px;
font-family:var(--font-body);
}

.glass-search-wrap input:-webkit-autofill,
.glass-search-wrap input:-webkit-autofill:hover,
.glass-search-wrap input:-webkit-autofill:focus,
.glass-search-wrap input:-webkit-autofill:active{

-webkit-box-shadow:
0 0 0 1000px transparent inset !important;

box-shadow:
0 0 0 1000px transparent inset !important;

-webkit-text-fill-color:#ffffff !important;

caret-color:#ffffff !important;

transition:
background-color 9999s ease-in-out 0s;

background:transparent !important;

}

.glass-search-wrap input::placeholder{
color:#9c9c9c;
}

.search-icon-btn{

display:flex;
align-items:center;
justify-content:center;

width:40px;
height:40px;

flex-shrink:0;

border:none;

border-radius:14px;

background:rgba(0,234,255,.10);

color:#00eaff;

cursor:pointer;

transition:.3s ease;

font-family:var(--font-body);

}

.search-icon-btn:hover{

background:#00eaff;

color:#000;

transform:scale(1.06);

box-shadow:
0 0 18px rgba(0,234,255,.35);

}

.search-icon-btn svg{

width:22px;
height:22px;

display:block;

}

@media(max-width:1100px){

.header{

flex-wrap:wrap;

align-items:center;

}

.glass-search-wrap{

width:100%;

max-width:100%;

margin-top:14px;

margin-left:0;

order:3;

}

.glass-search-wrap form{

width:100%;

}

}

@media (min-width:1024px) and (max-width:1366px) {
.glass-search-wrap{
max-width:380px;
}
}

@media (min-width:1024px) and (max-width:1280px) {
.glass-search-wrap{
max-width:360px;
}
}

@media(max-width:768px){

.glass-search-wrap{
max-width:100%;
margin:0;
}

.glass-search-wrap form{
width:100%;
padding:10px;
border-radius:16px;
}

.glass-search-wrap button{
padding:10px 14px;
font-size:13px;
}

}

/* ===========================
   ULTRA PREMIUM CARD DESIGN
=========================== */

.ai-card{
position:relative;
overflow:hidden;
padding:20px;
margin-bottom:24px;

border-radius:20px;

background:linear-gradient(
135deg,
rgba(255,255,255,.08),
rgba(255,255,255,.03)
);

border:1px solid rgba(255,255,255,.10);

backdrop-filter:blur(18px);
-webkit-backdrop-filter:blur(18px);

box-shadow:
0 16px 36px rgba(0,0,0,.28),
inset 0 1px 0 rgba(255,255,255,.08);

transition:all .45s cubic-bezier(.2,.8,.2,1);
transform-style:preserve-3d;
will-change:transform;

backface-visibility:hidden;
}

.ai-card:before{
content:"";
position:absolute;
inset:0;
padding:1px;
border-radius:20px;

background:linear-gradient(
135deg,
rgba(0,234,255,.8),
rgba(255,255,255,.08),
rgba(0,234,255,.2)
);

-webkit-mask:
linear-gradient(#fff 0 0) content-box,
linear-gradient(#fff 0 0);

-webkit-mask-composite:xor;
mask-composite:exclude;

pointer-events:none;
opacity:.55;
}

.ai-card:after{
content:"";
position:absolute;
top:-120%;
left:-40%;
width:60%;
height:250%;

background:linear-gradient(
90deg,
transparent,
rgba(255,255,255,.18),
transparent
);

transform:rotate(18deg);
transition:.8s ease;
pointer-events:none;
}

.ai-card:hover{
transform:
translateY(-8px)
scale(1.01);

box-shadow:
0 24px 50px rgba(0,0,0,.36),
0 0 20px rgba(0,234,255,.12);

border-color:rgba(0,234,255,.35);
}

.ai-card:hover:after{
left:130%;
}

.compare-container:before{
content:"";
position:absolute;
inset:0;
background:linear-gradient(
180deg,
transparent,
rgba(0,0,0,.18)
);
z-index:1;
pointer-events:none;
}

.ai-card .premium-badge{
position:absolute;
top:16px;
