grid-template-columns:repeat(4,1fr);
gap:14px;
}

.subcat-card{
position:relative;
display:block;
text-decoration:none;
padding:14px 12px;
border-radius:20px;
text-align:center;
color:#ffffff;
font-weight:800;
font-size:15px;
letter-spacing:.3px;
overflow:hidden;

background:linear-gradient(
135deg,
rgba(255,255,255,.08),
rgba(255,255,255,.03)
);

border:1px solid rgba(255,255,255,.08);

backdrop-filter:blur(12px);
-webkit-backdrop-filter:blur(12px);

box-shadow:
0 8px 20px rgba(0,0,0,.18),
inset 0 1px 0 rgba(255,255,255,.06);

transition:all .35s ease;
transform:translateY(0);
}

.subcat-card:before{
content:'';
position:absolute;
inset:0;
border-radius:20px;
padding:1px;

background:linear-gradient(
135deg,
rgba(0,234,255,.9),
rgba(255,255,255,.05),
rgba(0,234,255,.15)
);

-webkit-mask:
linear-gradient(#fff 0 0) content-box,
linear-gradient(#fff 0 0);

-webkit-mask-composite:xor;
mask-composite:exclude;

opacity:.7;
pointer-events:none;
}

.subcat-card:after{
content:'';
position:absolute;
top:-120%;
left:-40%;
width:60%;
height:260%;

background:linear-gradient(
90deg,
transparent,
rgba(255,255,255,.18),
transparent
);

transform:rotate(20deg);
transition:.8s;
}

.subcat-card:hover{
transform:translateY(-8px) scale(1.03);
color:#00eaff;

box-shadow:
0 18px 35px rgba(0,0,0,.32),
0 0 24px rgba(0,234,255,.18);
}

.subcat-card:hover:after{
left:130%;
}

.subcat-card:active{
transform:scale(.96);
}

.subcat-card{
}

.subcat-card:nth-child(2){
animation-delay:.3s;
}

.subcat-card:nth-child(3){
animation-delay:.6s;
}

.subcat-card:nth-child(4){
animation-delay:.9s;
}

@keyframes floatCard{
0%{transform:translateY(0);}
50%{transform:translateY(-4px);}
100%{transform:translateY(0);}
}

@media(max-width:768px){

