}

}

.dropdown{
position:relative;
}

.dropdown-content{
display:none;
position:absolute;
top:100%;
left:0;
width:248px;
max-width:calc(100vw - 24px);
padding:6px;
border-radius:12px;
box-sizing:border-box;
background:rgba(8,14,28,.96);
