-webkit-backdrop-filter:blur(22px);
border:1px solid rgba(255,255,255,.12);
box-shadow:0 18px 40px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.08);
z-index:9999;
flex-direction:column;
gap:2px;
opacity:0;
visibility:hidden;
transform:none;
transition:opacity .15s ease, visibility .15s ease;
}

.m-ico{
flex:0 0 auto;
width:18px;
height:18px;
stroke:currentColor;
}

.m-lab{
flex:1 1 auto;
text-align:left;
}

