width:248px;
padding:6px;
border-radius:12px;
background:rgba(8,14,28,.96);
backdrop-filter:blur(22px);
-webkit-backdrop-filter:blur(22px);
border:1px solid rgba(255,255,255,.12);
box-shadow:0 16px 36px rgba(0,0,0,.4);
z-index:10000;
