linear-gradient(#fff 0 0) content-box,
linear-gradient(#fff 0 0);

-webkit-mask-composite:xor;
mask-composite:exclude;

opacity:.55;
pointer-events:none;
}

.retouch-card:after{
content:"";
position:absolute;
top:-120%;
left:-40%;
width:60%;
height:250%;

background:linear-gradient(
90deg,
transparent,
rgba(255,255,255,.18),
