.uc2-category-container{
margin-bottom:6px;
}
.uc2-category-badge{
font-size:12px;
}
}

.universal-card:before{

content:"";
position:absolute;
inset:0;
padding:1px;
border-radius:20px;

background:linear-gradient(
135deg,
rgba(0,234,255,.8),
rgba(255,255,255,.08),
rgba(0,234,255,.2)
);

-webkit-mask:
linear-gradient(#fff 0 0) content-box,
linear-gradient(#fff 0 0);

-webkit-mask-composite:xor;
mask-composite:exclude;

opacity:.55;
pointer-events:none;

}

.universal-card:after{

content:"";
position:absolute;
top:-120%;
left:-40%;
width:60%;
height:250%;

background:linear-gradient(
90deg,
transparent,
rgba(255,255,255,.18),
transparent
);

transform:rotate(18deg);
transition:.8s ease;
pointer-events:none;

}

.universal-card:hover:after{
left:130%;
}

.universal-card:hover{

transform:none;

box-shadow:
0 4px 16px rgba(0,0,0,0.10);

border-color:rgba(255,255,255,.10);

}

/* MGS FIX 2026-07-11: Disable card hover when dropdown is open */
.universal-card.has-open-dropdown:hover{
transform:none !important;
box-shadow:0 16px 36px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.08) !important;
border-color:rgba(255,255,255,.10) !important;
}

.universal-image-box{
width:100%;
}

.universal-title{
text-align:center;
margin:7px 0 2px;
font-weight:800;
font-family:var(--font-heading);

white-space:normal;
overflow:visible;
overflow-wrap:break-word;
word-wrap:break-word;
word-break:break-word;
hyphens:auto;
max-width:100%;

font-size:clamp(15px,1.8vw,22px);
line-height:1.25;
}

.universal-title a{

display:block;

color:#00eaff !important;

text-decoration:none !important;

/* ROUND 25: titles are REAL LINKS again — the old pointer-events:none
   made every Universal Card title click fall through to the card. */
pointer-events:auto !important;

cursor:pointer !important;

transition:color .2s ease;

}

.universal-title a:hover{

color:var(--uc2c1,#00eaff) !important;

text-decoration:underline !important;

text-underline-offset:3px;

}

.universal-title a:focus-visible{

outline:2px solid var(--uc2c1,#00eaff);

outline-offset:3px;

border-radius:4px;

}

/* =========================
   PROMPT TEXT BOX SYSTEM
========================= */

.prompttextbox{

position:relative;

padding:18px;

padding-top:8px !important;

margin-top:12px;

border-radius:18px;

background:rgba(0,0,0,.28);

border:1px solid rgba(255,255,255,.07);

box-shadow:
inset 0 1px 0 rgba(255,255,255,.04);

color:#f5f5f5;

font-family:var(--font-body);

line-height:1.7;

font-size:15px;

max-height:80px;

overflow-y:auto;

overflow-x:hidden;

word-break:break-word;

white-space:pre-wrap;

scrollbar-width:thin;

scrollbar-color:#00c7de #111;

}

.prompttextbox *{

margin:0 !important;
padding-top:0 !important;

}

.prompttextbox img,
.prompttextbox figure,
.prompttextbox br{

display:none !important;

}

.prompttextbox p,
.prompttextbox div,
.prompttextbox span{

margin:0 !important;
padding:0 !important;

}

.prompttextbox > *:first-child{

margin-top:0 !important;
padding-top:0 !important;

}

.prompttextbox::-webkit-scrollbar{
width:8px;
}

.prompttextbox::-webkit-scrollbar-track{

background:#111;

border-radius:20px;

}

.prompttextbox::-webkit-scrollbar-thumb{

background:linear-gradient(
180deg,
#00c7de,
#0094ff
);

border-radius:20px;

border:1px solid rgba(255,255,255,.08);

}

.prompttextbox::-webkit-scrollbar-thumb:hover{

background:linear-gradient(
180deg,
#00e0ff,
#00a2ff
);

}

@media(max-width:768px){

.prompttextbox{

font-size:14px;

padding:14px;

}

}

/* =========================
   UNIVERSAL CARD STEP 3
   Safe Prompt Expand / Collapse
========================= */

.prompttextbox.uc2-collapsible:not(.uc2-expanded){
overflow-y:auto !important;
overflow-x:hidden !important;
}

.prompttextbox.uc2-expanded{
max-height:none !important;
overflow-y:visible !important;
}

.universal-card.uc2-expanded .prompttextbox{
max-height:none !important;
overflow-y:visible !important;
}

.uc2-expand-toggle{
display:none;
align-items:center;
justify-content:center;
gap:7px;
width:auto;
max-width:100%;
margin:-2px auto 4px;
padding:9px 14px;
border-radius:999px;
border:1px solid rgba(0,234,255,.28);
background:linear-gradient(135deg,rgba(0,234,255,.14),rgba(255,255,255,.045));
box-shadow:0 8px 20px rgba(0,234,255,.10), inset 0 1px 0 rgba(255,255,255,.08);
color:#00eaff;
font-family:var(--font-body);
font-size:12px;
font-weight:900;
line-height:1;
letter-spacing:.2px;
cursor:pointer;
white-space:nowrap;
transition:background .25s ease,border-color .25s ease,transform .25s ease,box-shadow .25s ease;
}

.uc2-expand-toggle.is-visible{
display:inline-flex;
}

.uc2-expand-toggle:hover{
border-color:rgba(0,234,255,.55);
background:linear-gradient(135deg,rgba(0,234,255,.22),rgba(255,255,255,.07));
box-shadow:0 10px 24px rgba(0,234,255,.15), inset 0 1px 0 rgba(255,255,255,.12);
transform:translateY(-1px);
}

@media(max-width:768px){
.uc2-expand-toggle{
padding:8px 12px;
font-size:11px;
margin-top:-1px;
}
}

@media(min-width:769px){
.uc2-expand-toggle{
font-size:12px;
}
}

/* =========================
   UNIVERSAL CARD STEP 4
   Isolated UC2 Prompt Modal
========================= */

[data-uc2-view-prompt]{
display:inline-flex;
align-items:center;
justify-content:center;
gap:7px;
width:auto;
max-width:100%;
margin:-2px auto 6px;
padding:9px 14px;
border-radius:999px;
border:1px solid rgba(255,200,0,.30);
background:linear-gradient(135deg,rgba(255,200,0,.14),rgba(255,255,255,.045));
box-shadow:0 8px 20px rgba(255,200,0,.10), inset 0 1px 0 rgba(255,255,255,.08);
color:#ffc800;
font-family:var(--font-body);
font-size:12px;
font-weight:900;
line-height:1;
letter-spacing:.2px;
cursor:pointer;
white-space:nowrap;
transition:background .25s ease,border-color .25s ease,transform .25s ease,box-shadow .25s ease;
}

[data-uc2-view-prompt]:hover{
border-color:rgba(255,200,0,.58);
background:linear-gradient(135deg,rgba(255,200,0,.22),rgba(255,255,255,.07));
box-shadow:0 10px 24px rgba(255,200,0,.15), inset 0 1px 0 rgba(255,255,255,.12);
transform:translateY(-1px);
}

.uc2-modal{
display:none;
position:fixed;
inset:0;
z-index:100003;
font-family:var(--font-body);
}

.uc2-modal[data-open="true"]{
display:block;
}

.uc2-modal-overlay{
position:absolute;
inset:0;
background:rgba(0,0,0,.72);
backdrop-filter:blur(10px);
-webkit-backdrop-filter:blur(10px);
}

.uc2-modal-content{
position:absolute;
left:50%;
top:50%;
transform:translate(-50%,-50%);
width:min(720px,calc(100vw - 28px));
max-height:min(82vh,760px);
display:flex;
flex-direction:column;
overflow:hidden;
border-radius:22px;
border:1px solid rgba(0,234,255,.25);
background:linear-gradient(145deg,rgba(18,18,22,.98),rgba(8,10,16,.98));
box-shadow:0 28px 80px rgba(0,0,0,.65),0 0 38px rgba(0,234,255,.12),inset 0 1px 0 rgba(255,255,255,.08);
color:#fff;
}

.uc2-modal-header{
display:flex;
align-items:center;
justify-content:space-between;
gap:14px;
padding:16px 18px;
border-bottom:1px solid rgba(255,255,255,.08);
color:#00eaff;
font-size:15px;
font-weight:900;
letter-spacing:.25px;
}

.uc2-modal-body{
padding:18px;
overflow:auto;
max-height:calc(82vh - 70px);
font-size:15px;
line-height:1.75;
white-space:pre-wrap;
word-break:break-word;
color:#f5f5f5;
scrollbar-width:thin;
scrollbar-color:#00c7de #111;
-webkit-user-select:none;
-moz-user-select:none;
-ms-user-select:none;
user-select:none;
-webkit-touch-callout:none;
}

.uc2-modal-thumb-wrap{
display:none;
flex:0 0 auto;
padding:14px 18px 0;
}

.uc2-modal[data-has-thumb="true"] .uc2-modal-thumb-wrap{
display:flex;
align-items:center;
justify-content:center;
}

.uc2-modal-thumb{
display:block;
width:auto;
max-width:100%;
height:auto;
max-height:min(280px,32vh);
object-fit:contain;
object-position:center;
border-radius:14px;
border:1px solid rgba(0,234,255,.22);
background:#07090f;
box-shadow:0 10px 28px rgba(0,0,0,.35);
}

.uc2-modal-body{
white-space:normal;
-webkit-user-select:none;
-moz-user-select:none;
-ms-user-select:none;
user-select:none;
-webkit-touch-callout:none;
}

.uc2-modal-title{
display:none;
flex:0 0 auto;
margin:0;
padding:12px 18px 4px;
font-size:18px;
font-weight:900;
line-height:1.35;
letter-spacing:.2px;
color:#ffffff;
text-align:center;
}
.uc2-modal-title.is-on{
display:block;
}

.uc2-modal-intro{
margin:0 0 16px;
padding:12px 14px;
border-radius:12px;
border:1px solid rgba(255,255,255,.08);
background:rgba(255,255,255,.04);
color:#c8cdd6;
font-size:14px;
line-height:1.65;
}

.uc2-modal-prompt{
white-space:pre-wrap;
word-break:break-word;
font-size:15px;
line-height:1.75;
color:#f5f5f5;
}

.uc2-modal-sec{
margin-top:16px;
padding-top:14px;
border-top:1px solid rgba(255,255,255,.08);
}

.uc2-modal-sec-label{
display:block;
margin:0 0 8px;
color:#00eaff;
font-size:12px;
font-weight:900;
letter-spacing:.6px;
text-transform:uppercase;
}

.uc2-modal-sec-text{
margin:0;
color:#e8eaee;
font-size:14px;
