}

.uc2-modal-tools{
display:flex;
flex-wrap:wrap;
gap:8px;
}

.uc2-modal-tool{
display:inline-flex;
align-items:center;
padding:6px 10px;
border-radius:999px;
border:1px solid rgba(168,85,247,.35);
background:rgba(124,58,237,.16);
color:#e9d5ff;
