transition:background .25s ease,border-color .25s ease,color .25s ease;
}

.uc2-modal-close:hover{
background:rgba(255,200,0,.16);
border-color:rgba(255,200,0,.42);
color:#ffc800;
}

@media(max-width:768px){
[data-uc2-view-prompt]{
