/* =========================
   UNIVERSAL CARD STEP 9
   Smart Home Feed & Carousels (Marketplace Redesign)
========================= */

.uc2-feed-section{
width:100%;
margin:0;
padding:0;
max-width:none;
position:relative;
}

/* =========================
   HOMEPAGE FEED GRID (2-col desktop / 1-col mobile)
========================= */
.homepage-feed-grid-container{
width:100%;
max-width:1300px;
margin:28px auto;
padding:0 20px;
}

@media(min-width:768px){
.homepage-feed-grid-container{
display:grid;
grid-template-columns:repeat(2,1fr);
gap:32px 24px;
align-items:start;
}
.homepage-feed-grid-container .uc2-feed-section--full{
grid-column:1 / -1;
}
}

@media(max-width:767px){
.homepage-feed-grid-container{
display:flex;
flex-direction:column;
gap:24px;
margin:24px auto;
padding:0 15px;
}
}
/* Root-cause fix: grid cells must be allowed to shrink & clip overflow */
.homepage-feed-grid-container .uc2-feed-section{
min-width:0 !important;
overflow:hidden !important;
width:100%;
box-sizing:border-box;
}

/* PHASE 3A CLS FIX: pending feed sections reserve their final layout height
   invisibly, so populating them never pushes content down.
   States: false=pending(reserved), true=populated(visible), empty=collapsed */
.uc2-feed-section[data-uc2-feed="false"]{
visibility:hidden;
height:276px;
overflow:hidden;
}
.uc2-feed-section[data-uc2-feed="empty"]{
display:none;
}

/* ---- Header row: title LEFT + "View All" RIGHT ---- */
.uc2-feed-head{
display:flex;
align-items:flex-end;
justify-content:space-between;
gap:16px;
}
.uc2-feed-title{
margin:0;
color:#fff;
font-family:var(--font-heading);
font-size:20px;
font-weight:800;
line-height:1.25;
letter-spacing:.3px;
display:flex;
align-items:center;
gap:10px;
}
.uc2-feed-title svg{flex:0 0 auto;}
.uc2-feed-viewall{
flex:0 0 auto;
display:inline-flex;
align-items:center;
gap:6px;
color:var(--uc2c1,#FF6B35);
font-family:var(--font-body);
font-size:13px;
font-weight:800;
letter-spacing:.3px;
text-decoration:none !important;
white-space:nowrap;
padding-bottom:2px;
transition:gap .25s ease,color .25s ease;
}
.uc2-feed-viewall:hover{gap:10px;color:var(--uc2c2,#FF2E63);}

/* ---- Thin colored accent line under the title ---- */
.uc2-feed-accent{
height:4px;
border-radius:999px;
margin:8px 0 14px;
background:linear-gradient(90deg,var(--uc2c1,#FF6B35),var(--uc2c2,#FF2E63));
opacity:.92;
}

/* ---- Section theme colors ---- */
[data-uc2-feed-type="trending"]{--uc2c1:#FF6B35;--uc2c2:#FF2E63;}
[data-uc2-feed-type="copied"]{--uc2c1:#2196F3;--uc2c2:#1565C0;}
[data-uc2-feed-type="viral"]{--uc2c1:#9C27B0;--uc2c2:#E040FB;}
[data-uc2-feed-type="recommended"]{--uc2c1:#00BFA5;--uc2c2:#1DE9B6;}
[data-uc2-feed-type="saved"]{--uc2c1:#FFB300;--uc2c2:#FF6D00;}
[data-uc2-feed-type="trending"] .uc2-feed-title{color:#FF6B35;}
[data-uc2-feed-type="copied"] .uc2-feed-title{color:#2196F3;}
[data-uc2-feed-type="viral"] .uc2-feed-title{color:#9C27B0;}
[data-uc2-feed-type="recommended"] .uc2-feed-title{color:#00BFA5;}
[data-uc2-feed-type="saved"] .uc2-feed-title{color:#FFB300;}

/* ---- Prev / Next slide buttons ---- */
.uc2-feed-nav{
position:absolute;
top:50%;
transform:translateY(-50%);
width:32px;
height:32px;
margin:0;
padding:0;
border-radius:50%;
background:rgba(26,30,41,.9);
border:1px solid rgba(255,255,255,.15);
color:#e2e8f0;
font-size:16px;
line-height:1;
cursor:pointer;
z-index:10;
display:flex;
align-items:center;
justify-content:center;
transition:all .2s ease;
-webkit-appearance:none;
appearance:none;
}
.uc2-feed-nav:hover{
background:rgba(0,234,255,.2);
border-color:rgba(0,234,255,.5);
color:#00eaff;
}
.uc2-feed-nav--prev{left:4px;}
.uc2-feed-nav--next{right:4px;}
.uc2-feed-nav[disabled]{
opacity:.2;
cursor:default;
pointer-events:none;
}
@media(max-width:768px){
.uc2-feed-nav{width:28px;height:28px;font-size:14px;}
}

/* ---- Horizontal slide carousel (outer: overflow hidden) ---- */
.uc2-feed-carousel{
display:flex;
overflow:hidden;
width:100%;
position:relative;
gap:12px;
}
/* ---- Inner sliding track (translateX target) ---- */
.uc2-feed-track{
display:flex;
gap:12px;
transition:transform .4s cubic-bezier(.25,.8,.25,1);
will-change:transform;
width:100%;
min-width:0;
flex-shrink:0;
}

.uc2-feed-item{
flex:0 0 calc(50% - 6px) !important;
min-width:0 !important;
max-width:calc(50% - 6px) !important;
box-sizing:border-box;
display:flex;
flex-direction:column;
background:#1a1e29;
border:1px solid rgba(255,255,255,.08);
border-radius:12px;
overflow:hidden;
box-shadow:0 2px 10px rgba(0,0,0,.35);
text-decoration:none !important;
transition:transform .28s cubic-bezier(.2,.7,.3,1),box-shadow .28s ease,border-color .28s ease;
position:relative;
-webkit-tap-highlight-color:transparent;
}

.uc2-feed-item:hover{
transform:scale(1.03);
border-color:rgba(255,255,255,.20);
box-shadow:0 14px 32px rgba(0,0,0,.50);
z-index:2;
}
.uc2-feed-item:hover .uc2-feed-item-title{color:var(--uc2c1,#00eaff);}

/* Thumbnail (16:9) — image comes from the EXISTING cover/thumb parser.
   object-fit:contain shows the FULL image; #161922 fills any letterbox. */
.uc2-feed-thumb{
position:relative;
display:block;
width:100%;
aspect-ratio:16/9;
flex:0 0 auto;
background:#161922;
overflow:hidden;
}
.uc2-feed-thumb img{
display:block;
width:100%;
height:100%;
object-fit:contain !important;
object-position:center;
}
.uc2-feed-thumb:after{
content:'';
position:absolute;
left:0;right:0;bottom:0;
height:46%;
background:linear-gradient(180deg,rgba(0,0,0,0) 40%,rgba(26,30,41,.95) 100%);
pointer-events:none;
}
.uc2-feed-thumb--empty{
display:flex;
align-items:center;
justify-content:center;
font-size:30px;
background:linear-gradient(135deg,#232a3b,#161922);
}

/* Small badge pinned to the thumbnail corner */
.uc2-feed-badge{
position:absolute;
top:8px;
left:8px;
z-index:3;
display:inline-flex;
align-items:center;
gap:4px;
padding:4px 9px;
border-radius:999px;
font-family:var(--font-body);
font-size:10.5px;
font-weight:800;
letter-spacing:.2px;
line-height:1;
color:#fff;
background:linear-gradient(135deg,var(--uc2c1,#FF6B35),var(--uc2c2,#FF2E63));
box-shadow:0 2px 8px rgba(0,0,0,.28);
}

/* Post title below thumbnail (2 lines max + ellipsis) */
.uc2-feed-item-title{
display:-webkit-box;
-webkit-line-clamp:2;
-webkit-box-orient:vertical;
overflow:hidden;
min-height:2.8em;
padding:10px 12px 12px;
color:#e2e8f0;
font-family:var(--font-body);
font-size:14px;
font-weight:700;
line-height:1.4;
word-break:break-word;
}

/* ---- Responsive ---- */
@media(max-width:768px){
.uc2-feed-title{font-size:18px;}
.uc2-feed-accent{height:3px;margin:7px 0 12px;}
.uc2-feed-item-title{font-size:13px;padding:8px 10px 10px;}
.uc2-feed-section[data-uc2-feed="false"]{height:224px;}
}

/* =========================
   UNIVERSAL CARD STEP 10
   Advanced Search & Filter Engine
========================= */

.uc2-search-panel{
width:100%;
margin:18px 0 10px;
padding:14px;
border-radius:18px;
border:1px solid rgba(255,255,255,.08);
background:rgba(18,18,18,.72);
box-shadow:0 10px 24px rgba(0,0,0,.20), inset 0 1px 0 rgba(255,255,255,.05);
}

.uc2-search-row{
display:flex;
flex-wrap:wrap;
gap:10px;
align-items:center;
margin:0 0 10px;
}

.uc2-filter-select{
min-width:150px;
flex:1 1 150px;
padding:10px 12px;
border-radius:12px;
border:1px solid rgba(255,255,255,.10);
background:rgba(0,0,0,.26);
color:#fff;
font-family:var(--font-body);
font-size:13px;
font-weight:700;
outline:none;
}

.uc2-filter-chip{
display:inline-flex;
align-items:center;
justify-content:center;
padding:9px 12px;
border-radius:999px;
border:1px solid rgba(0,234,255,.26);
background:rgba(0,234,255,.08);
color:#00eaff;
font-family:var(--font-body);
font-size:12px;
font-weight:900;
line-height:1;
cursor:pointer;
}

.uc2-search-results{
display:inline-flex;
align-items:center;
color:rgba(255,255,255,.68);
font-family:var(--font-body);
font-size:12px;
font-weight:800;
line-height:1.3;
}

.uc2-search-empty{
display:none;
width:100%;
padding:14px;
border-radius:14px;
border:1px solid rgba(255,200,0,.24);
background:rgba(255,200,0,.08);
color:#ffc800;
font-family:var(--font-body);
font-size:13px;
font-weight:900;
text-align:center;
}

.uc2-search-empty[data-uc2-empty="true"]{
display:block;
}

@media(max-width:768px){
.uc2-search-panel{
margin:14px 0 8px;
padding:12px;
}
.uc2-search-row{
gap:8px;
margin-bottom:8px;
}
.uc2-filter-select{
flex:1 1 100%;
min-width:0;
font-size:12px;
padding:9px 10px;
}
.uc2-filter-chip{
font-size:11px;
padding:8px 10px;
}
.uc2-search-results{
font-size:11px;
}
.uc2-search-empty{
font-size:12px;
padding:12px;
}
}

@media(min-width:769px){
.uc2-filter-select{
max-width:260px;
}
}

/* =========================
   UNIVERSAL CARD STEP 11
   Prompt Collections & Playlists
========================= */

.uc2-collection-btn{
display:inline-flex;
align-items:center;
justify-content:center;
gap:7px;
padding:10px 14px;
border-radius:14px;
border:1px solid rgba(255,255,255,.12);
background:rgba(255,255,255,.04);
color:#fff;
font-family:var(--font-body);
font-size:13px;
font-weight:800;
line-height:1;
cursor:pointer;
white-space:nowrap;
transition:.3s ease;
}

.uc2-collection-btn:hover{
border-color:rgba(0,234,255,.34);
background:rgba(0,234,255,.08);
color:#00eaff;
}

.uc2-collection-badge{
display:inline-flex;
align-items:center;
justify-content:center;
gap:4px;
color:#ffc800;
font-weight:900;
}

.uc2-collection-count{
display:inline-flex;
align-items:center;
justify-content:center;
min-width:20px;
padding:3px 6px;
border-radius:999px;
background:rgba(255,200,0,.15);
color:#ffc800;
font-size:11px;
font-weight:900;
line-height:1;
}

/* =========================
   PROMPT COLLECTIONS POPUP (YouTube Playlist Style)
========================= */

.uc2-collection-modal {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 100005;
  font-family: var(--font-body);
  color: #e5e5e5;
}
.uc2-collection-modal[data-uc2-open="true"] {
  display: block;
}

.uc2-collection-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  opacity: 0;
  transition: opacity 0.2s ease;
}
.uc2-collection-modal[data-uc2-open="true"] .uc2-collection-overlay {
  opacity: 1;
}

.uc2-collection-content {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, calc(-50% + 20px));
  width: min(320px, calc(100vw - 24px));
  max-height: 70vh;
  display: flex;
  flex-direction: column;
  background: #282828;
  border: 1px solid #404040;
  border-radius: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  overflow: hidden;
  opacity: 0;
  transition: opacity 0.25s ease, transform 0.25s ease;
  outline: none;
}
.uc2-collection-modal[data-uc2-open="true"] .uc2-collection-content {
  opacity: 1;
  transform: translate(-50%, -50%);
}

.uc2-collection-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid #404040;
  font-size: 16px;
  font-weight: 600;
  color: #fff;
  flex-shrink: 0;
}
.uc2-collection-header-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: #e5e5e5;
}
.uc2-collection-close-btn {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  color: #999;
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
  border-radius: 50%;
  transition: color 0.15s ease, background 0.15s ease;
  padding: 0;
}
.uc2-collection-close-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
}

.uc2-collection-body {
  overflow-y: auto;
  max-height: calc(70vh - 125px);
  padding: 8px 0;
  flex: 1 1 auto;
}
.uc2-collection-body::-webkit-scrollbar {
  width: 6px;
}
.uc2-collection-body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 4px;
}

.uc2-collection-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 20px;
  cursor: pointer;
  transition: background 0.15s ease;
  user-select: none;
  min-height: 44px;
}
.uc2-collection-item:hover,
.uc2-collection-item:focus {
  background: #383838;
  outline: none;
}
.uc2-collection-item-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1;
}
.uc2-collection-checkbox {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid #666;
  border-radius: 4px;
  background: transparent;
  cursor: pointer;
  position: relative;
  flex-shrink: 0;
  transition: all 0.15s ease;
}
.uc2-collection-checkbox:checked {
  background: #1a73e8;
  border-color: #1a73e8;
}
.uc2-collection-checkbox:checked::after {
  content: '';
  position: absolute;
  left: 5px;
  top: 2px;
  width: 5px;
  height: 9px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.uc2-collection-name {
  font-size: 14px;
  color: #e5e5e5;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.uc2-collection-count {
  font-size: 12px;
  color: #999;
  white-space: nowrap;
  flex-shrink: 0;
}

.uc2-collection-empty {
  padding: 24px 20px;
  text-align: center;
  color: #999;
  font-size: 13px;
}

.uc2-collection-create-wrap {
  border-top: 1px solid #333;
  margin-top: 4px;
  padding-top: 4px;
}
.uc2-create-toggle-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px 20px;
  background: transparent;
  border: none;
  color: #4ba0ff;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  transition: background 0.15s ease;
  min-height: 44px;
}
.uc2-create-toggle-btn:hover {
  background: #383838;
}
.uc2-create-toggle-btn svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.uc2-create-form {
  display: none;
  padding: 12px 20px;
  flex-direction: column;
  gap: 10px;
}
.uc2-create-form[data-active="true"] {
  display: flex;
}
.uc2-create-input {
  width: 100%;
  height: 36px;
  padding: 0 12px;
  font-size: 13px;
  color: #fff;
  background: #383838;
  border: 1px solid #555;
  border-radius: 6px;
  outline: none;
  transition: border-color 0.15s ease;
}
.uc2-create-input:focus {
  border-color: #4ba0ff;
}
.uc2-create-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
.uc2-btn-cancel {
  background: transparent;
  border: none;
  color: #bbb;
  font-size: 13px;
  font-weight: 500;
  padding: 6px 12px;
  cursor: pointer;
  border-radius: 6px;
}
.uc2-btn-cancel:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.05);
}
.uc2-btn-create {
  background: #1a73e8;
  border: none;
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s ease;
}
.uc2-btn-create:hover {
  background: #1557b0;
}
.uc2-btn-create:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.uc2-collection-footer {
  padding: 12px 20px;
  border-top: 1px solid #404040;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: #282828;
}
.uc2-collection-done-btn {
  width: 100%;
  height: 40px;
  background: #1a73e8;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}
.uc2-collection-done-btn:hover {
  background: #1557b0;
}

@media (max-width: 600px) {
  .uc2-collection-content {
    width: 100%;
    max-width: 100%;
    left: 0;
    right: 0;
    bottom: 0;
    top: auto;
    border-radius: 16px 16px 0 0;
    max-height: 80vh;
    transform: translateY(100%);
  }
  .uc2-collection-modal[data-uc2-open="true"] .uc2-collection-content {
    transform: translateY(0);
  }
  .uc2-collection-header {
    padding: 18px 20px;
  }
  .uc2-collection-item {
    padding: 14px 20px;
  }
}

@media(max-width:768px){
.uc2-collection-btn{
font-size:12px;
padding:9px 12px;
}
.uc2-collection-content{
width:calc(100vw - 18px);
max-height:88vh;
border-radius:18px;
}
.uc2-collection-header{
padding:14px;
font-size:14px;
}
.uc2-collection-body{
padding:12px;
max-height:calc(88vh - 64px);
}
.uc2-collection-create{
flex-direction:column;
}
.uc2-collection-item button{
margin:3px 3px 0 0;
}
}

@media(min-width:769px){
.uc2-collection-btn{
font-size:13px;
}
}

/* =========================
   UNIVERSAL CARD STEP 12
   Prompt Version Control
========================= */

.uc2-version-badge{
display:inline-flex;
align-items:center;
justify-content:center;
gap:7px;
width:max-content;
max-width:100%;
margin:0 auto 6px;
padding:8px 13px;
border-radius:999px;
border:1px solid rgba(0,234,255,.30);
background:linear-gradient(135deg,rgba(0,234,255,.13),rgba(255,255,255,.045));
box-shadow:0 8px 20px rgba(0,234,255,.10), inset 0 1px 0 rgba(255,255,255,.08);
color:#dffbff;
font-family:var(--font-body);
font-size:12px;
font-weight:900;
line-height:1;
white-space:nowrap;
cursor:pointer;
}

.uc2-version-label{
display:inline-flex;
align-items:center;
justify-content:center;
min-width:36px;
padding:5px 8px;
border-radius:999px;
background:rgba(0,234,255,.13);
color:#00eaff;
font-size:11px;
font-weight:900;
line-height:1;
}

.uc2-version-modal{
display:none;
position:fixed;
inset:0;
z-index:100005;
font-family:var(--font-body);
}

.uc2-version-modal[data-uc2-open="true"]{
display:none !important; /* version history shell hidden until real data */
}
.uc2-version-badge,
.uc2-version-top-row .uc2-version-badge{
pointer-events:none !important;
cursor:default !important;
}

.uc2-version-overlay{
position:absolute;
inset:0;
background:rgba(0,0,0,.72);
backdrop-filter:blur(10px);
-webkit-backdrop-filter:blur(10px);
}

.uc2-version-content{
position:absolute;
left:50%;
top:50%;
transform:translate(-50%,-50%);
width:min(860px,calc(100vw - 28px));
max-height:min(86vh,820px);
display:flex;
flex-direction:column;
overflow:hidden;
border-radius:22px;
border:1px solid rgba(0,234,255,.25);
background:linear-gradient(145deg,rgba(18,18,22,.98),rgba(8,10,16,.98));
box-shadow:0 28px 80px rgba(0,0,0,.65),0 0 38px rgba(0,234,255,.10),inset 0 1px 0 rgba(255,255,255,.08);
color:#fff;
}

.uc2-version-header{
display:flex;
align-items:center;
justify-content:space-between;
gap:14px;
padding:16px 18px;
border-bottom:1px solid rgba(255,255,255,.08);
color:#00eaff;
font-size:15px;
font-weight:900;
letter-spacing:.25px;
}

.uc2-version-header button{
width:34px;
height:34px;
display:inline-flex;
align-items:center;
justify-content:center;
border-radius:50%;
border:1px solid rgba(255,255,255,.12);
background:rgba(255,255,255,.06);
color:#fff;
font-size:22px;
font-weight:900;
line-height:1;
cursor:pointer;
}

.uc2-version-body{
padding:16px;
overflow:auto;
max-height:calc(86vh - 68px);
}

.uc2-version-timeline{
display:flex;
gap:10px;
overflow:auto;
scroll-snap-type:x mandatory;
-webkit-overflow-scrolling:touch;
padding:2px 0 12px;
margin:0 0 12px;
}

.uc2-version-timeline span{
flex:0 0 auto;
scroll-snap-align:start;
color:#00eaff;
font-weight:900;
}

.uc2-version-list{
display:flex;
flex-direction:column;
gap:10px;
}

.uc2-version-item{
padding:12px;
border-radius:14px;
border:1px solid rgba(255,255,255,.08);
background:rgba(255,255,255,.035);
color:#fff;
}

.uc2-version-item strong{
color:#00eaff;
}

.uc2-version-item button,
.uc2-version-compare button,
.uc2-version-restore{
padding:8px 10px;
margin:6px 4px 0 0;
border-radius:10px;
border:1px solid rgba(255,255,255,.10);
background:rgba(255,255,255,.06);
color:#fff;
font-family:var(--font-body);
font-size:12px;
font-weight:800;
cursor:pointer;
}

.uc2-version-compare{
margin:14px 0 0;
padding:12px;
border-radius:14px;
border:1px solid rgba(0,234,255,.14);
background:rgba(0,234,255,.05);
white-space:pre-wrap;
word-break:break-word;
font-size:13px;
line-height:1.6;
}

.uc2-version-restore{
border-color:rgba(255,200,0,.28) !important;
color:#ffc800 !important;
}

.uc2-version-empty{
display:none;
padding:14px;
border-radius:14px;
border:1px solid rgba(255,200,0,.24);
background:rgba(255,200,0,.08);
color:#ffc800;
font-size:13px;
font-weight:900;
text-align:center;
}

