}

/* MGS FIX 2026-07-11: Keep status row badges visible when dropdown is open
   so the card layout does NOT change when mouse leaves card toward dropdown.
   This prevents layout-triggered scroll events from closing the dropdown. */
.universal-card.has-open-dropdown .uc2-status-row {
flex-wrap: wrap !important;
justify-content: center !important;
gap: 8px 5px !important;
}
.universal-card.has-open-dropdown .uc2-status-row .uc2-completeness-badge,
.universal-card.has-open-dropdown .uc2-status-row .uc2-version-badge {
display: inline-flex !important;
