min-width: 0;
}
.universal-card.has-open-dropdown .uc2-status-row .uc2-quality-badge,
.universal-card.has-open-dropdown .uc2-status-row .uc2-popularity-badge {
flex: 1 1 calc(50% - 10px);
min-width: 0;
}

.universal-card:hover .uc2-status-row {
flex-wrap: wrap !important;
justify-content: center !important;
gap: 8px 5px !important;
}

.universal-card:hover .uc2-status-row .uc2-completeness-badge,
.universal-card:hover .uc2-status-row .uc2-version-badge {
display: inline-flex !important;
opacity: 1;
