/* ============ UNIVERSAL CARD: 3-DOTS ACTION MENU (YouTube style) ============ */
.uc2-copy-row.uc2-action-row{
order:10;
display:flex;
align-items:stretch;
gap:6px;
width:100%;
margin:0;
}
.uc2-copy-row.uc2-action-row .copy-action-group{
width:auto;
flex:1 1 auto;
min-width:0;
}
.uc2-more-wrap{
position:relative;
flex:0 0 auto;
display:flex;
align-items:stretch;
}
.uc2-more-btn{
  background: transparent;
  border: none;
  cursor: pointer;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: inherit;
  transition: background 0.15s ease;
  padding: 0;
}
.uc2-more-btn:hover { background: rgba(255,255,255,0.08); }

.uc2-more-menu{
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  background: #181818;
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(0,0,0,0.35);
  padding: 6px 0;
  min-width: 180px;
  max-width: 220px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.06);
  display: none;
  flex-direction: column;
  gap: 0;
  z-index: 100001;
  transition: opacity 0.15s ease, transform 0.15s ease;
}
.uc2-more-menu.open{display:flex;animation:uc2MoreMenuFadeIn .18s ease;}
@keyframes uc2MoreMenuFadeIn{from{opacity:0;transform:translateY(-6px);}to{opacity:1;transform:translateY(0);}}

.uc2-more-menu .uc2-menu-item{
  display: flex;
  align-items: center;
  justify-content: flex-start;
  text-align: left;
  background: transparent;
  border: none;
  color: #ffffff;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  padding: 10px 16px;
  margin: 0;
  width: 100%;
  box-sizing: border-box;
  gap: 8px;
  transition: background 0.15s ease;
  white-space: nowrap;
}
.uc2-more-menu .uc2-menu-item:hover{ background: rgba(255,255,255,0.08); color: #ffffff; }
.uc2-more-menu .uc2-menu-item:active{ background: rgba(255,255,255,0.12); }
.uc2-more-menu .uc2-menu-item svg{flex:0 0 auto;width:15px;height:15px;}

/* Neutralize button-specific styles inside 3-dots menu for uniform look */
.uc2-more-menu .save-btn,
.uc2-more-menu .share-btn,
.uc2-more-menu .uc2-collection-btn,
.uc2-more-menu .use-btn {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  text-align: left;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #ffffff !important;
  font-size: 14px !important;
  font-weight: 400 !important;
  cursor: pointer;
  padding: 10px 16px !important;
  margin: 0;
  width: 100%;
  box-sizing: border-box;
  gap: 8px;
  transition: background 0.15s ease;
  white-space: nowrap;
  flex-shrink: 0;
}

.uc2-more-menu .save-btn:hover,
.uc2-more-menu .share-btn:hover,
.uc2-more-menu .uc2-collection-btn:hover,
.uc2-more-menu .use-btn:hover {
  background: rgba(255,255,255,0.08) !important;
  color: #ffffff !important;
  border-color: transparent !important;
  transform: none !important;
  box-shadow: none !important;
}

.uc2-more-menu .save-btn:active,
.uc2-more-menu .share-btn:active,
.uc2-more-menu .uc2-collection-btn:active,
.uc2-more-menu .use-btn:active {
  background: rgba(255,255,255,0.12) !important;
}

.uc2-more-menu .save-btn svg,
.uc2-more-menu .share-btn svg,
.uc2-more-menu .uc2-collection-btn svg,
.uc2-more-menu .use-btn svg {
  width: 15px !important;
  height: 15px !important;
  flex-shrink: 0;
  fill: none !important;
  stroke: currentColor !important;
}

/* Neutralize View button specific styling inside 3-dots menu */
.uc2-more-menu [data-uc2-view-prompt] {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  text-align: left !important;
  width: 100% !important;
  padding: 10px 16px !important;
  margin: 0 !important;
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #ffffff !important;
  font-size: 14px !important;
  font-weight: 400 !important;
  font-family: inherit !important;
  cursor: pointer !important;
  white-space: nowrap !important;
  gap: 8px !important;
  box-sizing: border-box !important;
  transition: background 0.15s ease !important;
  letter-spacing: normal !important;
  line-height: normal !important;
}

.uc2-more-menu [data-uc2-view-prompt]:hover {
  background: rgba(255,255,255,0.08) !important;
  color: #ffffff !important;
  border-color: transparent !important;
  box-shadow: none !important;
  transform: none !important;
  background-image: none !important;
}

.uc2-more-menu [data-uc2-view-prompt]:active {
  background: rgba(255,255,255,0.12) !important;
}

/* Share submenu nested wrapper (no extra padding) */
.uc2-more-menu .uc2-share-menu{ position: relative; padding: 0; }
.uc2-more-menu .share-wrap .share-btn{ padding: 8px 16px; width: 100%; }

.uc2-more-menu .uc2-share-menu .share-btn{
  background: transparent;
  border: none;
  color: #fff;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  transition: background 0.1s ease;
  white-space: nowrap;
}
.uc2-more-menu .uc2-share-menu .share-btn:hover{ background: #2a2a2a; color: #fff; }

.uc2-more-menu .share-dropdown{
  position: absolute;
  top: 100%;
  left: 0;
  right: auto;
  bottom: auto;
  margin: 0;
  min-width: 160px;
  z-index: 100002;
  background: #181818;
  border: none;
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.12);
  padding: 8px 0;
  display: none;
}
.uc2-more-menu .share-dropdown .share-option{
  display: flex;
  align-items: center;
  justify-content: flex-start;
  text-align: left;
  padding: 8px 16px;
  margin: 0;
  width: 100%;
  box-sizing: border-box;
  gap: 8px;
  background: transparent;
  border: none;
  color: #fff;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  white-space: nowrap;
}
.uc2-more-menu .share-dropdown .share-option:hover{ background: #2a2a2a; }

@media(max-width:768px){
