/* =========================
   PROMPT SECTION HEADINGS
========================= */

.prompt-heading{
color:#6DA2FF;
font-weight:700;
font-size:12px;
letter-spacing:.8px;
text-transform:uppercase;
display:block;
margin-bottom:3px;
}

.negative-heading{
color:#FF554C;
font-weight:700;
font-size:12px;
letter-spacing:.8px;
text-transform:uppercase;
display:block;
margin-top:10px;
margin-bottom:3px;
}

.negative-text{
color:#9AA7B8;
font-size:14px;
line-height:1.6;
font-family:var(--font-body);
}

.prompttextbox .prompt-heading,
.prompttextbox .negative-heading{
display:block !important;
width:100%;
clear:both;
line-height:1.25 !important;
padding:0 !important;
box-sizing:border-box;
}

.prompttextbox .prompt-heading{
margin:0 0 5px 0 !important;
}

.prompttextbox .negative-heading{
margin:12px 0 5px 0 !important;
}

.prompttextbox .negative-text{
display:block !important;
width:100%;
clear:both;
margin:0 !important;
padding:0 !important;
line-height:1.65 !important;
white-space:pre-wrap;
word-break:break-word;
box-sizing:border-box;
}

.prompttextbox .negative-text br{
display:block !important;
content:"";
margin:0 0 4px 0 !important;
}

/* =========================
   BODY FONT (font-family only)
   Blog Post Content + Labels + Search Description
========================= */

.post-body,
.entry-content,
.post-labels,
.status-msg-body{
font-family:var(--font-body);
}

/* =========================
   USE BUTTON SYSTEM
========================= */

.universal-actions{
display:none !important;
}

.use-btn{

display:flex;
align-items:center;
justify-content:center;

flex-shrink:0;

padding:12px 18px;

min-width:90px;
max-width:140px;

width:auto;

border-radius:14px;

background:linear-gradient(
135deg,
#00eaff,
#009dff
);

color:#000;

font-weight:800;
font-size:15px;

white-space:nowrap;

cursor:pointer;
border:none;

transition:.35s ease;

box-shadow:
0 0 16px rgba(0,234,255,.25);

font-family:var(--font-body);

}

@media(max-width:768px){

.use-btn{

padding:8px 10px;

min-width:60px;
max-width:90px;

font-size:12px;

border-radius:12px;

flex-shrink:1;

}

}

@media(max-width:900px) and (orientation:landscape){

.use-btn{

padding:9px 12px;

font-size:12px;

min-width:68px;
max-width:100px;

}

}

.use-btn:hover{

transform:translateY(-4px);

box-shadow:
0 0 24px rgba(0,234,255,.45);

}

/* =========================
   USE GUIDE POPUP
========================= */

.use-popup{

position:fixed;
inset:0;

background:rgba(8,8,8,.96);

display:none;

align-items:center;
justify-content:center;

padding:20px;

z-index:100004;

backdrop-filter:blur(20px);
-webkit-backdrop-filter:blur(20px);

}

.use-popup.active{
display:flex;
}

.use-popup.active .use-popup-box{

animation:popupZoom .45s cubic-bezier(.2,.8,.2,1);

}

@keyframes popupZoom{

0%{
opacity:0;
transform:
scale(.82)
translateY(40px);
}

100%{
opacity:1;
transform:
scale(1)
translateY(0);
}

}

.use-popup-box{

position:relative;

display:flex;
flex-direction:column;

width:100%;
max-width:650px;

max-height:calc(100vh - 40px);
max-height:calc(100dvh - 40px);

padding:22px;

border-radius:22px;

background:rgba(18,18,18,.72);

backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);

border:1px solid rgba(255,255,255,.08);

box-shadow:
0 25px 60px rgba(0,0,0,.45),
0 0 24px rgba(0,234,255,.12);

overflow:hidden;

}

.use-popup-title{

font-size:28px;
font-weight:900;
margin-bottom:24px;

color:#00eaff;

font-family:var(--font-heading);

}

.use-popup-content{

display:flex;
flex-direction:column;
gap:16px;

overflow-y:auto;
overflow-x:hidden;
flex:1 1 auto;
min-height:0;
padding-right:6px;

-webkit-overflow-scrolling:touch;
overscroll-behavior:contain;

font-family:var(--font-body);

scrollbar-width:thin;
scrollbar-color:#00c7de #111;

}
.use-popup-content::-webkit-scrollbar{ width:8px; }
.use-popup-content::-webkit-scrollbar-track{
background:#111;
border-radius:20px;
}
.use-popup-content::-webkit-scrollbar-thumb{
background:linear-gradient(180deg, #00c7de, #0094ff);
border-radius:20px;
border:1px solid rgba(255,255,255,.08);
}
.use-popup-content::-webkit-scrollbar-thumb:hover{
background:linear-gradient(180deg, #00e0ff, #00a2ff);
}
.use-sec-head{
display:flex;
align-items:center;
gap:10px;
color:#00eaff;
font-size:15px;
font-weight:800;
margin-bottom:8px;
letter-spacing:.2px;
}
.use-sec-head svg{
flex:0 0 auto;
width:18px;
height:18px;
stroke:currentColor;
}
.use-sub{
display:block;
font-weight:700;
color:#c4b5fd;
font-size:13.5px;
margin:10px 0 4px;
letter-spacing:.15px;
}
.use-line{ margin:0 0 4px; color:#e8eaee; }

.use-item{

padding:16px 18px;

border-radius:18px;

background:rgba(255,255,255,.04);

border:1px solid rgba(255,255,255,.06);

line-height:1.7;

font-size:15px;

}

.use-item strong{
color:#00eaff;
display:block;
margin-bottom:5px;
}

.use-popup-close{

position:absolute;

top:16px;
right:16px;

width:42px;
height:42px;

border:none;
border-radius:50%;

background:#1f1f1f;

color:#fff;

font-size:22px;

cursor:pointer;

transition:.3s ease;

}

.use-popup-close:hover{

background:#00eaff;
color:#000;

}

.use-guide-data{
display:none;
}

@media(max-width:768px){

.use-popup-box{
padding:22px;
border-radius:20px;
}

.use-popup-title{
font-size:22px;
}

.use-item{
font-size:14px;
padding:14px;
}

}

.universal-copy{
display:contents;
margin:0;
width:auto;
flex-basis:auto;
}

@media(max-width:900px){
.universal-copy{
display:contents;
}
}

@media(max-width:768px){
.universal-copy{
display:contents;
}
}

.copy-prompt-btn{

display:flex;
align-items:center;
justify-content:center;

flex-shrink:0;

padding:12px 18px;

min-width:90px;
max-width:160px;

width:auto;

border-radius:14px;

background:linear-gradient(
135deg,
#ff6ef7,
#c44dff
);

color:#fff;

font-weight:800;
font-size:15px;

white-space:nowrap;

cursor:pointer;
border:none;

position:relative;

transition:.35s ease;

box-shadow:
0 0 16px rgba(196,77,255,.30);

font-family:var(--font-body);

}

.copy-prompt-btn:hover{

transform:translateY(-4px);

box-shadow:
0 0 26px rgba(196,77,255,.55);

}

.copy-prompt-btn:active{

transform:scale(.94);

transition:.08s;

}

@media(max-width:900px){

.copy-prompt-btn{

min-width:unset;
max-width:unset;
width:auto;

}

}

@media(max-width:768px){

.copy-prompt-btn{

padding:10px 14px;

min-width:unset;
max-width:unset;
width:auto;

font-size:13px;

border-radius:12px;

}

}

@media(max-width:900px) and (orientation:landscape){

.copy-prompt-btn{

padding:9px 12px;

font-size:12px;

min-width:68px;
max-width:120px;

}

}

/* =========================
   COPY DROPDOWN SYSTEM
========================= */

.copy-action-group{
position:relative;
display:flex;
align-items:stretch;
flex-shrink:0;
}

.copy-dropdown-toggle{
display:flex;
align-items:center;
justify-content:center;

padding:12px 10px;

border-radius:0 14px 14px 0;

background:linear-gradient(
135deg,
#c44dff,
#a030e0
);

color:#fff;

font-size:11px;
font-weight:800;

cursor:pointer;
border:none;

transition:.35s ease;

box-shadow:
0 0 10px rgba(196,77,255,.25);

flex-shrink:0;

margin-left:1px;
font-family:var(--font-body);
}

.copy-dropdown-toggle:hover{
transform:translateY(-4px);
box-shadow:
0 0 18px rgba(196,77,255,.45);
}

.copy-dropdown-toggle:active{
transform:scale(.94);
transition:.08s;
}

.copy-action-group .copy-prompt-btn{
width:auto;
flex:1 1 auto;
border-radius:14px 0 0 14px;
margin-right:0;
}

.copy-dropdown{
position:absolute;
top:calc(100% + 6px);
right:0;
background:rgba(18,18,18,.98);
border:1px solid rgba(196,77,255,.18);
border-radius:14px;
padding:8px;
display:none;
flex-direction:column;
gap:4px;
z-index:101;
min-width:200px;
box-shadow:
0 12px 32px rgba(0,0,0,.45),
0 0 18px rgba(196,77,255,.08);
backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);
}

.copy-dropdown.open{
display:flex;
right:auto;
transform:none;
animation:copyDropdownFadeIn .2s ease;
}

@keyframes copyDropdownFadeIn{
from{opacity:0;transform:translateY(-6px);}
to{opacity:1;transform:translateY(0);}
}

.copy-option{
display:flex;
align-items:center;
gap:8px;
padding:10px 14px;
border-radius:10px;
font-size:13px;
font-weight:700;
color:#fff;
text-decoration:none;
transition:.25s ease;
cursor:pointer;
border:none;
background:transparent;
width:100%;
font-family:var(--font-body);
text-align:left;
white-space:nowrap;
}

.copy-option:hover{
background:rgba(196,77,255,.14);
color:#d68fff;
}

@media(max-width:768px){
.copy-dropdown-toggle{
padding:10px 9px;
font-size:10px;
border-radius:0 12px 12px 0;
}
.copy-action-group .copy-prompt-btn{
width:auto;
flex:1 1 auto;
border-radius:12px 0 0 12px;
}
.copy-dropdown{
right:50%;
transform:translateX(50%);
min-width:180px;
border-radius:12px;
}
.copy-option{
font-size:12px;
padding:9px 12px;
}
}

/* EXPERIMENT CSS-DEDUPE: removed leftover 768px card padding/title that overrode compact layout */

.ai-card h2 a,
.ai-card h3 a{
  display:block;
  color:#00eaff !important;
  text-decoration:none !important;   
}

.ai-card h2 a:hover,
.ai-card h3 a:hover{
  color:#81ECFE !important;
  text-decoration:none !important;
}

*{
box-sizing:border-box;
}

img{
max-width:100%;
height:auto;
}

iframe{
max-width:100%;
}

/* Universal-card before/after: smooth reset only when another card becomes active. */
.universal-image-box .compare-container{
  cursor:ew-resize;
}

.universal-image-box .compare-container.ba-resetting .img-after,
.universal-image-box .compare-container.ba-resetting .slider-handle,
.universal-image-box .compare-container.ba-resetting .ba-label-wrap{
  transition:clip-path .3s ease, left .3s ease, width .3s ease;
}

/* =========================
   LIVE TRENDING BAR
========================= */

.trending-bar{

margin-top:-37px;

position:relative;

overflow:hidden;

display:flex;
align-items:center;

gap:18px;

padding:14px 0;

background:linear-gradient(
90deg,
#00eaff,
#009dff
);

border-top:1px solid rgba(255,255,255,.08);
border-bottom:1px solid rgba(255,255,255,.08);

}

.trending-label{

flex:0 0 auto;

padding:0 22px;

font-size:15px;
font-weight:900;

color:#000;

z-index:2;

}

.trending-track{

display:flex;
align-items:center;
gap:55px;

white-space:nowrap;

animation:trendMove 24s linear infinite;

}

.trending-item{

font-size:15px;
font-weight:700;
color:#fff;

text-shadow:0 0 10px rgba(0,0,0,.18);

}

@keyframes trendMove{

0%{
transform:translateX(0);
}

100%{
transform:translateX(-50%);
}

}

@media(max-width:768px){

.trending-bar{
padding:12px 0;
}

.trending-label{
font-size:13px;
padding:0 14px;
}

.trending-item{
font-size:13px;
}

.trending-track{
gap:32px;
}

}

/* =========================
   PREMIUM MOBILE MENU
========================= */

.mobile-menu-btn{

display:none;

position:absolute;
top:18px;
right:18px;

width:52px;
height:52px;

border:none;
outline:none;

border-radius:16px;

background:rgba(255,255,255,.06);

backdrop-filter:blur(12px);
-webkit-backdrop-filter:blur(12px);

border:1px solid rgba(255,255,255,.08);

z-index:100001;

cursor:pointer;

transition:.35s ease;

}

.mobile-menu-btn span{

display:block !important;

position:relative;

width:24px !important;
min-width:24px !important;
max-width:24px !important;

height:2px !important;
min-height:2px !important;

background:#00eaff !important;

border-radius:20px;

margin:4px 0;

opacity:1 !important;
visibility:visible !important;

flex-shrink:0;

content:'';

}

.mobile-menu-btn.active span:nth-child(1),
.mobile-menu-btn.active span:nth-child(2),
.mobile-menu-btn.active span:nth-child(3){

opacity:0 !important;
height:0 !important;
min-height:0 !important;
margin:0 !important;

}

.mobile-menu-btn.active{

display:flex;
align-items:center;
justify-content:center;
font-size:28px;
color:#00eaff;
line-height:1;

}

.mobile-menu-btn.active::before{

content:'\00D7';

}

.mobile-overlay{

position:fixed;
inset:0;

background:rgba(0,0,0,.72);

backdrop-filter:blur(4px);
-webkit-backdrop-filter:blur(4px);

opacity:0;
visibility:hidden;

transition:
opacity .3s ease,
visibility .3s ease;

pointer-events:none;

z-index:1090;

will-change:opacity;

}

.mobile-overlay.active{

opacity:1;
visibility:visible;

pointer-events:auto;

}

