background:rgba(255,255,255,.04);

border:1px solid rgba(255,255,255,.04);

}

.saved-prompts-btn{
display:none !important;
}

.menu a:hover{

background:rgba(0,234,255,.12);

transform:translateX(5px);

}

.dropdown{
width:100%;
position:relative;
contain:layout;
}

.dropdown > a{

display:flex;
align-items:center;
justify-content:space-between;

gap:12px;

width:100%;

cursor:pointer;

user-select:none;
-webkit-tap-highlight-color:transparent;

touch-action:manipulation;

}

.dropdown-content{

position:static !important;

display:none;

width:100% !important;

opacity:1 !important;
visibility:visible !important;

transform:none !important;

padding:12px !important;

margin-top:8px;

border-radius:18px;

background:rgba(255,255,255,.03);

grid-template-columns:1fr !important;

box-shadow:none !important;

}

.dropdown.active .dropdown-content{

display:flex !important;
flex-direction:column;

opacity:1 !important;
visibility:visible !important;

max-height:2000px;

padding-top:10px;

}

@media(max-width:768px){

.dropdown .dropdown-content{
display:none !important;
}

.dropdown.active .dropdown-content{
display:flex !important;
flex-direction:column;
}

}

.dropdown-content{

overflow:hidden;

transition:.3s ease;

}

.sub-menu{

display:flex;
flex-direction:column;

gap:8px;

width:100%;

overflow:hidden;

}

@media(max-width:768px){

.sub-menu{
display:none !important;
}

.sub-drop.active .sub-menu{
display:flex !important;
flex-direction:column;
}

.sub-drop > a{
position:relative;
}

}

.sub-menu a{

display:flex;

align-items:center;

width:100%;

padding:12px 14px;

font-size:13px;

border-radius:12px;

line-height:1.4;

touch-action:manipulation;

-webkit-tap-highlight-color:transparent;

font-family:'Manrope',sans-serif;
font-weight:500;
}

.glass-search-wrap{
display:none;
}

.logo img{
height:40px;
}

}

/* =========================
   PREMIUM MOBILE ACCORDION
========================= */

.mobile-arrow{

margin-left:6px;

font-size:10px;

color:#00eaff;

flex-shrink:0;

transition:transform .3s ease;

will-change:transform;

pointer-events:none;

}

@media(max-width:768px){
.mobile-arrow{
margin-left:auto;
font-size:16px;
}
}

.mobile-arrow::before{
content:'\25BC';
}

@media(min-width:769px){
.dropdown:hover .mobile-arrow{
transform:rotate(180deg);
}
}

.dropdown.active .mobile-arrow{

transform:rotate(180deg) translateZ(0);

}

body.menu-open{

overflow:hidden;

touch-action:none;

overscroll-behavior:none;

}

.menu a:active{

transform:scale(.985);

transition:transform .08s linear;

}

.menu a:hover,
.dropdown.active > a{

border-color:rgba(0,234,255,.18);

box-shadow:
0 0 12px rgba(0,234,255,.10);

}

body{

-webkit-overflow-scrolling:touch;

-webkit-font-smoothing:antialiased;

-moz-osx-font-smoothing:grayscale;

overflow-x:hidden;

}

/* =========================
   MOBILE BOTTOM BAR
========================= */

.mobile-bottom-bar{

display:none;

}

@media(max-width:768px){

.mobile-bottom-bar{

position:fixed;

left:50%;
bottom:14px;

transform:translateX(-50%);

width:94%;

display:flex;
align-items:center;
justify-content:space-around;

padding:12px 10px;

border-radius:22px;

background:
rgba(15,15,15,.75);

backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);

border:
1px solid rgba(255,255,255,.08);

box-shadow:
0 10px 40px rgba(0,0,0,.35);

z-index:99999;

}

.bottom-nav-item{

display:flex;
flex-direction:column;
align-items:center;
justify-content:center;

gap:4px;

text-decoration:none;

color:#cfcfcf;

font-size:12px;
font-weight:600;

padding:10px 14px;

border-radius:18px;

transition:.35s ease;

font-family:var(--font-body);

min-width:62px;

}

.bottom-nav-item span{

font-size:22px;

transition:.35s ease;

}

.bottom-nav-item p{

margin:0;

font-size:11px;

}

.bottom-nav-item.active{

background:
rgba(0,234,255,.12);

color:#00eaff;

box-shadow:
0 0 20px rgba(0,234,255,.14);

}

.saved-nav-icon{

display:flex;
align-items:center;
justify-content:center;

width:22px;
height:22px;

margin:auto;

}

.saved-nav-icon svg{

width:20px;
height:20px;

display:block;

}

.bottom-nav-item:hover{

transform:translateY(-3px);

color:#00eaff;

}

.bottom-nav-item.active span{

transform:scale(1.15);

}

body{

padding-top:25px;

}

.trending-bar{

margin-top:0;
position:relative;
top:-1px;

}

}

/* =========================
   SMART MOBILE NAVBAR
========================= */

@media(max-width:768px){

.header{

transition:
background .35s ease,
box-shadow .35s ease;

will-change:transform;

}

.header.scrolled{

background:
rgba(10,10,10,.78);

backdrop-filter:blur(20px);
-webkit-backdrop-filter:blur(20px);

box-shadow:
0 10px 30px rgba(0,0,0,.25);

}

}

@media(max-width:768px){

.mobile-bottom-bar{

transition:
transform .32s cubic-bezier(.2,.8,.2,1),
opacity .22s ease;

will-change:transform,opacity;

}

.mobile-bottom-bar.hide-bottom-bar{

transform:
translateX(-50%)
translateY(140px);

opacity:0;

}

}

/* =========================
   DIFFICULTY BADGE
========================= */

.diff-badge{
