align-items:center;
gap:5px;
padding:5px 12px;
border-radius:30px;
font-size:12px;
font-weight:800;
letter-spacing:.4px;
margin-bottom:4px;
}

.diff-easy{
background:rgba(0,255,150,.12);
color:#00ff96;
border:1px solid rgba(0,255,150,.25);
}

.diff-medium{
background:rgba(255,190,0,.12);
color:#ffbe00;
border:1px solid rgba(255,190,0,.25);
}

.diff-pro{
