}

/* =========================
   SHARE BUTTON
========================= */

.share-btn{
display:flex;
align-items:center;
gap:6px;
padding:10px 16px;
border-radius:14px;
border:1px solid rgba(255,255,255,.12);
background:rgba(255,255,255,.04);
color:#fff;
font-size:13px;
font-weight:700;
cursor:pointer;
transition:.3s ease;
white-space:nowrap;
flex-shrink:0;
