}

.share-dropdown{
position:absolute;
bottom:calc(100% + 8px);
right:0;
background:rgba(18,18,18,.96);
border:1px solid rgba(255,255,255,.10);
border-radius:16px;
padding:10px;
display:none;
flex-direction:column;
gap:6px;
z-index:100;
min-width:160px;
box-shadow:0 10px 30px rgba(0,0,0,.4);
backdrop-filter:blur(14px);
}

.share-dropdown.open{
