transition:.25s ease;
cursor:pointer;
border:none;
font-family:var(--font-body);
background:transparent;
width:100%;
text-align:left;
}

.share-option:hover{
background:rgba(0,234,255,.12);
color:#00eaff;
}

.share-wrap{
