(function(){
  var LEGACY_KEY = 'uc2Collections';
  var PRIMARY_KEY = 'promptCollections';
  var FLAG_KEY = 'collectionsMigrated_v1';

  function migTimestamp(col){
    try{
      var v = col && (col.createdAt || col.updatedAt || col.created || col.date);
      if(!v) return 0;
      var t = new Date(v).getTime();
      return isNaN(t) ? 0 : t;
    }catch(e){ return 0; }
  }

  function migrateCollections(){
    try{
      if(localStorage.getItem(FLAG_KEY) === 'true') return;

      var legacyRaw = localStorage.getItem(LEGACY_KEY);
      if(!legacyRaw){
        localStorage.setItem(FLAG_KEY, 'true');
        return;
      }

      var legacy = JSON.parse(legacyRaw);
      if(!legacy || !Array.isArray(legacy.collections) || legacy.collections.length === 0){
        localStorage.removeItem(LEGACY_KEY);
        localStorage.setItem(FLAG_KEY, 'true');
        return;
      }

      var primary = { collections: [] };
      var primaryRaw = localStorage.getItem(PRIMARY_KEY);
      if(primaryRaw){
        try{
          var parsedPrimary = JSON.parse(primaryRaw);
          if(parsedPrimary && Array.isArray(parsedPrimary.collections)){
            primary = parsedPrimary;
          }
        }catch(e2){ primary = { collections: [] }; }
      }

      var indexById = {};
      primary.collections.forEach(function(c, i){
        if(c && c.id != null && c.id !== ''){ indexById[String(c.id)] = i; }
      });

      var mergedCount = 0;
      legacy.collections.forEach(function(legacyCol){
        if(!legacyCol || legacyCol.id == null || legacyCol.id === '') return;
        var key = String(legacyCol.id);
        if(!(key in indexById)){
          primary.collections.push(legacyCol);
          indexById[key] = primary.collections.length - 1;
          mergedCount++;
        }else{
          var existing = primary.collections[indexById[key]];
          if(migTimestamp(legacyCol) > migTimestamp(existing)){
            primary.collections[indexById[key]] = legacyCol;
          }
        }
      });

      localStorage.setItem(PRIMARY_KEY, JSON.stringify(primary));
      localStorage.removeItem(LEGACY_KEY);
      localStorage.setItem(FLAG_KEY, 'true');
      try{ console.log('Collections migration v1 complete:', legacy.collections.length, 'legacy collections inspected,', mergedCount, 'merged'); }catch(e3){}
    }catch(err){
      try{ console.warn('Collections migration failed (legacy data preserved for retry):', err); }catch(e4){}
    }
  }

  try{ migrateCollections(); }catch(e){}
})();
