(function(){
  var path = window.location.pathname.replace(/\/$/, '');
  var searchParams = new URLSearchParams(window.location.search);

  /* MGS FIX: label pages should show 21 prompt cards per page.
     Add the native Blogger max-results parameter only when absent;
     existing pagination URLs with their own page size are preserved. */
  if(path.indexOf('/search/label/') === 0 && !searchParams.get('max-results')){
    searchParams.set('max-results','21');
    window.location.replace(path + '?' + searchParams.toString() + window.location.hash);
    return;
  }

})();
