b:if.script:
//
(function(){
  function heroReady(fn){ if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',fn);} else {fn();} }
  heroReady(function(){
    try{
      var hero=document.querySelector('.mgs-prompt-hero');
      if(!hero){return;}
      var uc=document.querySelector('.ai-wrap .universal-card')||document.querySelector('.universal-card');
      if(!uc){return;}
      if(window.mgsInitCardCore){ window.mgsInitCardCore(uc); }
      var data=window.getCopyData?window.getCopyData(uc):{prompt:uc._parsedPrompt||'',negative:uc._parsedNegativePrompt||'',hasNegative:!!uc._parsedHasNegative};
      var promptText=data.prompt||uc._parsedPrompt||'';
      var negativeText=(data.hasNegative&&data.negative)?data.negative:(uc._parsedHasNegative?uc._parsedNegativePrompt:'');
      var promptEl=hero.querySelector('[data-mgs-hero="prompt"]');
      if(promptEl){ promptEl.textContent=promptText||'No prompt text found for this post.'; }
      var negEl=hero.querySelector('[data-mgs-hero="negative"]');
      var negBox=hero.querySelector('[data-mgs-hero="neg-box"]');
      var copyAll=hero.querySelector('[data-mgs-hero="copy-all"]');
      if(negativeText){
        if(negEl){negEl.textContent=negativeText;}
        if(negBox){negBox.style.display='';}
        if(copyAll){copyAll.style.display='';}
      }
      var media=uc.querySelector('.universal-media');
      var img=hero.querySelector('.mgs-hero-img');
      if(img){
        var cover=uc._parsedCover||'';
        var src=cover;
        if(!src){ var mi=media?media.querySelector('img'):null; if(mi&&mi.getAttribute('src')){src=mi.getAttribute('src');} }
        if(src&&src.indexOf('data:')!==0){
          src=String(src).replace(/\/s\d+(-[a-z0-9-]+)?\//gi,'/s1600/').replace(/\/w\d+-h\d+(-[a-z0-9-]+)?\//gi,'/s1600/').replace(/=s\d+(-[a-z0-9-]+)?/gi,'=s1600').replace(/=w\d+-h\d+(-[a-z0-9-]+)?/gi,'=s1600').replace(/-c-rw/gi,'').replace(/-c(?=[/?]|$)/gi,'');
          img.src=src;
        }
      }
      var compareBox=hero.querySelector('.mgs-hero-compare');
      if(compareBox&&window.uc2Public&&window.uc2Public.initCompareSlider){
        var built=false;
        try{ built=window.uc2Public.initCompareSlider(uc,compareBox); }catch(e){ built=false; }
        if(built){ compareBox.style.display=''; }
        else{ compareBox.style.display='none'; }
      }else if(compareBox){ compareBox.style.display='none'; }
      var pid=hero.getAttribute('data-post-id')||'';
      if(window.uc2Public&&window.uc2Public.registerPromptSnapshot){
        window.uc2Public.registerPromptSnapshot(pid,{id:pid,title:hero.getAttribute('data-title')||'',url:hero.getAttribute('data-url')||'',promptText:promptText,negative:negativeText,hasNegative:!!negativeText,thumb:''});
      }
      if(!uc.getAttribute('data-title')){ uc.setAttribute('data-title', hero.getAttribute('data-title')||document.title); }
      function heroFallbackCopy(text){
        try{ var ta=document.createElement('textarea'); ta.value=text; ta.setAttribute('readonly',''); ta.style.position='fixed'; ta.style.left='-9999px'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); }catch(e){}
      }
      function heroCopy(text, btn){
        if(!text){ return; }
        function finish(){ if(window.updateCopyCounter){ window.updateCopyCounter(uc); } if(window.uc2TrackCopy){ window.uc2TrackCopy(uc); } if(window.doCopyFeedback){ window.doCopyFeedback(btn); } }
        if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(text).then(finish,function(){ heroFallbackCopy(text); finish(); }); }
        else { heroFallbackCopy(text); finish(); }
      }
      function bothText(){ var all=promptText||''; if(negativeText){ all+=(all?'\n\n':'')+'Negative Prompt:\n'+negativeText; } return all; }
      function bind(sel, fn){ var el=hero.querySelector('[data-mgs-hero="'+sel+'"]'); if(el){ el.addEventListener('click', fn); } return el; }
      bind('copy-main', function(){ heroCopy(promptText, this); });
      bind('copy-neg', function(){ heroCopy(negativeText, this); });
      bind('copy-all', function(){ heroCopy(bothText(), this); });
      bind('save', function(){
        if(window.openCollectionPopup){ window.openCollectionPopup(pid); }
      });
      bind('use', function(){
        var u=uc.querySelector('.universal-actions .use-btn')||uc.querySelector('.uc2-more-menu .use-btn');
        if(u){ u.click(); }
      });
      var shareBtns=hero.querySelectorAll('[data-mgs-share-platform]');
      for(var i=0;i<shareBtns.length;i++){
        (function(btn){
          btn.addEventListener('click', function(){
            var platform=btn.getAttribute('data-mgs-share-platform');
            if(platform==='copy'){
              var url=hero.getAttribute('data-url')||window.location.href;
              function done(){ if(window.doCopyFeedback){ window.doCopyFeedback(btn); } }
              if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(url).then(done,function(){ heroFallbackCopy(url); done(); }); }
              else { heroFallbackCopy(url); done(); }
              return;
            }
            if(window.shareToPlatform){
              window.mgsCurrentShareCard=uc;
              var tmp=document.createElement('button');
              tmp.setAttribute('data-platform', platform);
              window.shareToPlatform(tmp);
            }
          });
        })(shareBtns[i]);
      }
    }catch(e){}
  });
})();
