  var I_OUT = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>';
  var I_TIPS = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18h6"/><path d="M10 22h4"/><path d="M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z"/></svg>';

  function mgsHiResThumb(url){
    if(!url){return url;}
    try{
      url=String(url);
      url=url.replace(/\/s\d+(-[a-z-]+)?\//gi,'/s1600/');
      url=url.replace(/=s\d+(-[a-z-]+)?/gi,'=s1600');
      url=url.replace(/\/w\d+-h\d+(-[a-z-]+)?\//gi,'/s1600/');
      url=url.replace(/=w\d+-h\d+(-[a-z-]+)?/gi,'=s1600');
      url=url.replace(/-c-rw/gi,'');
      url=url.replace(/-c(?=[/?]|$)/gi,'');
      return url;
    }catch(e){return url;}
  }
  function mgsGetCardImage(entry){
    var rawUrl='';
    if(entry.content&&entry.content.$t){
      var m=entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
      if(m&&m[1]&&!/emoji|icon|spacer|pixel|1x1/i.test(m[1])){rawUrl=m[1];}
    }
    if(!rawUrl&&entry.media$thumbnail&&entry.media$thumbnail.url){rawUrl=entry.media$thumbnail.url;}
    if(!rawUrl&&entry.media$group&&entry.media$group.media$content){
      var mc=entry.media$group.media$content;
      if(mc&&mc[0]&&mc[0].url){rawUrl=mc[0].url;}
    }
    if(!rawUrl){return null;}
    return String(rawUrl)
      .replace(/\/s\d+(-[a-z0-9-]+)?\//gi,'/s1600/')
      .replace(/\/w\d+-h\d+(-[a-z0-9-]+)?\//gi,'/s1600/')
      .replace(/=s\d+(-[a-z0-9-]+)?/gi,'=s1600')
      .replace(/=w\d+-h\d+(-[a-z0-9-]+)?/gi,'=s1600')
      .replace(/-c-rw/gi,'')
      .replace(/-c(?=[/?]|$)/gi,'');
  }
  function mgsGetHighResImage(entry){ return mgsGetCardImage(entry); }
    function mgsCopy(text, btn){
    function done(){
      if(btn){
        var s=btn.querySelector('span');
        if(s){ var old=s.textContent; s.textContent='\u2713 Copied!'; setTimeout(function(){ s.textContent=old; },2000); }
      }
    }
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(done, function(){ mgsFallbackCopy(text); done(); });
    } else { mgsFallbackCopy(text); done(); }
  }
  function mgsShare(url, title){
    if(navigator.share){ navigator.share({title:title, url:url}).catch(function(){}); }
    else { mgsCopy(url); }
  }
  function mgsEntryId(entry){
    var m=((entry&&entry.id&&entry.id.$t)||'').match(/\.post-(\d+)$/);
    return m?m[1]:'';
  }
  function mgsPlainText(html){
    try{
      var d=document.createElement('div'); d.innerHTML=html||'';
      return (d.textContent||'').replace(/\u00a0/g,' ').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();
    }catch(e){ return ''; }
  }
  function mgsTextToHTML(t){
    return String(t||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br/>');
  }
  function mgsParsePrompt(html){
    var empty={prompt:'',negative:'',hasNegative:false,howTo:'',guide:'',tools:'',expected:'',tips:'',intro:'',promptHTML:''};
    var pub=window.uc2Public&&window.uc2Public.parsePromptBox;
    if(!pub){ return empty; }
    try{
      var d=document.createElement('div'); d.innerHTML=html||'';
      var r=pub(d);
      var prompt=(r&&r.promptText)||'';
      var promptHTML=(r&&r.promptHTML)||(prompt?('<span class="prompt-heading">PROMPT</span>'+mgsTextToHTML(prompt)):'');
      return {
        prompt:prompt,
        negative:(r&&r.negativeText)||'',
        hasNegative:!!(r&&r.hasNegative),
        howTo:(r&&r.howToHTML)||'',
        guide:(r&&r.guideText)||'',
        tools:(r&&r.toolsText)||'',
        expected:(r&&r.expectedText)||'',
        tips:(r&&r.tipsText)||'',
        intro:(r&&r.introText)||'',
        promptHTML:promptHTML
      };
    }catch(e){ return empty; }
  }
  function mgsFallbackCopy(text){
    try{
      var ta=document.createElement('textarea'); ta.value=text;
      ta.setAttribute('readonly',''); ta.style.position='fixed'; ta.style.left='-9999px';
      document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
    }catch(e){}
  }
  function mgsCopyPlain(text, btn){
    if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(text); }
    else { mgsFallbackCopy(text); }
    if(window.doCopyFeedback){ window.doCopyFeedback(btn); }
  }
  function mgsOpenUseGuide(card){
    var popup=document.getElementById('usePopup');
    var content=document.getElementById('usePopupContent');
    if(!popup||!content){ return; }
    function esc(t){ return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
    function plain(v){ if(!v) return ''; var d=document.createElement('div'); d.innerHTML=v; return (d.textContent||'').replace(/\u00a0/g,' ').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim(); }
    var tools=plain(card._parsedTools||'');
    var howto=plain(card._parsedGuide||'');
    var expected=plain(card._parsedExpected||'');
    var tips=plain(card._parsedTips||'');
    var guide=card.querySelector('.use-guide-data');
    var raw=guide?plain(guide.innerHTML):'';
    if(!howto && raw){ howto=raw; }
    function formatBody(text){
      var out='';
      String(text||'').split(/\n/).forEach(function(line){
        line=line.replace(/^\*+\s*|\s*\*+$/g,'').trim();
        if(!line) return;
        var sm=line.match(/^(.{1,42}?)\s*:\s*(.*)$/);
        if(sm && !/^https?:/i.test(sm[1]) && sm[1].length<42){
          out+='<div class="use-line"><span class="use-sub">'+esc(sm[1])+'</span>'+(sm[2]?esc(sm[2]):'')+'</div>';
        }else{
          out+='<div class="use-line">'+esc(line)+'</div>';
        }
      });
      return out;
    }
    var html='';
    if(tools){
      var chips=tools.split(/[\n,\/|]+/).map(function(t){ return t.replace(/^[-*\u2022]\s*/,'').trim(); }).filter(Boolean);
      var badges=chips.map(function(t){
        var cls='badge-default'; var tl=t.toLowerCase();
        if(tl.indexOf('chatgpt')>-1||tl.indexOf('dall')>-1){ cls='badge-chatgpt'; }
        else if(tl.indexOf('flux')>-1){ cls='badge-flux'; }
        else if(tl.indexOf('gemini')>-1){ cls='badge-gemini'; }
        else if(tl.indexOf('midjourney')>-1){ cls='badge-midjourney'; }
        else if(tl.indexOf('leonardo')>-1){ cls='badge-leonardo'; }
        return '<span class="ai-tool-badge '+cls+'">'+esc(t)+'</span>';
      }).join('');
      html+='<div class="use-item"><div class="use-sec-head">'+I_TOOLS+'<span>Compatible AI Tools</span></div><div class="ai-tool-badges">'+badges+'</div></div>';
    }
    if(howto){ html+='<div class="use-item"><div class="use-sec-head">'+I_HOW+'<span>How To Use This Prompt</span></div>'+formatBody(howto)+'</div>'; }
    if(expected){ html+='<div class="use-item"><div class="use-sec-head">'+I_OUT+'<span>Expected Output</span></div>'+formatBody(expected)+'</div>'; }
    if(tips){ html+='<div class="use-item"><div class="use-sec-head">'+I_TIPS+'<span>Tips &amp; Variations</span></div>'+formatBody(tips)+'</div>'; }
    if(!html){ html='<div class="use-item">No guide available for this prompt.</div>'; }
    content.innerHTML=html;
    popup.classList.add('active');
  }
  function placeFixed(el, anchor){
    var r=anchor.getBoundingClientRect();
    var mw=el.offsetWidth||190;
    var mh=el.offsetHeight||140;
    var top=r.bottom+8;
    if(top+mh>window.innerHeight){ top=r.top-8-mh; }
    if(top<8){ top=8; }
    var left=r.left;
    if(left+mw>window.innerWidth){ left=Math.max(8, window.innerWidth-mw-8); }
    el.style.position='fixed';
    el.style.top=Math.round(top)+'px';
    el.style.left=Math.round(left)+'px';
    el.style.right='auto';
    el.style.bottom='auto';
    el.style.margin='0';
    el.style.zIndex='100002';
  }
  function mgsBuildActions(card, meta){
    var title=meta&&meta.title?meta.title:'';
    var postUrl=meta&&meta.postUrl?meta.postUrl:'#';
    var postId=card.getAttribute('data-post-id')||card.getAttribute('data-id')||'';
    var wrap=document.createElement('div');
    wrap.className='mgs-related-actions';

    // ---- Copy Prompt button (Round 10 styling) ----
    var group=document.createElement('div');
    group.className='mgs-btn-group';

    var copyBtn=document.createElement('button');
    copyBtn.type='button';
    copyBtn.className='mgs-btn-copy';
    copyBtn.innerHTML=I_COPY+'<span>Copy Prompt</span>';
    copyBtn.addEventListener('click',function(e){
      e.preventDefault(); e.stopPropagation();
      if(window.closeAllCopyDropdowns){ window.closeAllCopyDropdowns(); }
      var data=window.getCopyData?window.getCopyData(card):null;
      var promptText=(data&&data.prompt)?data.prompt:(card._parsedPrompt||'');
      var negativeText=(data&&data.hasNegative&&data.negative)?data.negative:(card._parsedHasNegative?card._parsedNegativePrompt:'');
      var all='';
      if(promptText){ all+=promptText; }
      if(negativeText){ all+=(all?'\n\n':'')+'Negative Prompt:\n'+negativeText; }
      if(all){
        mgsCopyPlain(all, copyBtn);
        if(window.updateCopyCounter){ window.updateCopyCounter(card); }
        if(window.uc2TrackCopy){ window.uc2TrackCopy(card); }
      }
    });

    var ddBtn=document.createElement('button');
    ddBtn.type='button';
    ddBtn.className='mgs-btn-dropdown';
    ddBtn.setAttribute('aria-label','Copy options');
    ddBtn.innerHTML=I_CHEV;

    group.appendChild(copyBtn);
    group.appendChild(ddBtn);

    // ---- Variations dropdown (UC .copy-dropdown) ----
    var varMenu=document.createElement('div');
    varMenu.className='copy-dropdown';
    function copyOption(label, iconSvg, handler){
      var b=document.createElement('button');
      b.type='button';
      b.className='copy-option';
      b.innerHTML=iconSvg+'<span>'+label+'</span>';
      b.addEventListener('click',function(e){
        e.preventDefault(); e.stopPropagation();
        varMenu._card=card;  // UC handlers (copyPromptOnly etc.) resolve the card via dd._card
        handler(b);
        if(window.uc2TrackCopy){ window.uc2TrackCopy(card); }
      });
      return b;
    }
    varMenu.appendChild(copyOption('Copy Prompt', I_COPYOPT, function(btn){ window.copyPromptOnly(btn); }));
    varMenu.appendChild(copyOption('Copy Negative Prompt', I_NEG, function(btn){ window.copyNegativePrompt(btn); }));
    varMenu.appendChild(copyOption('Copy All Prompt', I_ALL, function(btn){ window.copyAllPrompt(btn); }));

    function openCopyDropdown(dd, anchor, cardEl){
      var isOpen=dd.classList.contains('open')&&dd._anchor===anchor;
      if(window.closeAllCopyDropdowns){ window.closeAllCopyDropdowns(); }
      if(window.uc2CloseAllMoreMenus){ window.uc2CloseAllMoreMenus(); }
      if(isOpen){ return; }
      dd._origParent=dd.parentNode;
      dd._origNext=dd.nextSibling;
      dd._card=cardEl;
      dd._anchor=anchor;
      document.body.appendChild(dd);
      dd.classList.add('open');
      if(cardEl){ cardEl.classList.add('has-open-dropdown'); }
      if(window.positionCopyDropdown){ window.positionCopyDropdown(dd, anchor); }
      else { placeFixed(dd, anchor); }
    }
    ddBtn.addEventListener('click',function(e){
      e.preventDefault(); e.stopPropagation();
      openCopyDropdown(varMenu, ddBtn, card);
    });

    // ---- 3-dots more menu (UC .uc2-more-menu) ----
    var menuBtn=document.createElement('button');
    menuBtn.type='button';
    menuBtn.className='mgs-btn-menu';
    menuBtn.setAttribute('aria-label','More actions');
    menuBtn.innerHTML=I_DOTS;

    var menu=document.createElement('div');
    menu.className='uc2-more-menu';
    menu._card=card;

    function menuItem(label, iconSvg, extraClass, attrs, onClick){
      var b=document.createElement('button');
      b.type='button';
      b.className='uc2-menu-item'+(extraClass?' '+extraClass:'');
      b.innerHTML=iconSvg+'<span>'+label+'</span>';
      if(attrs){ for(var k in attrs){ b.setAttribute(k, attrs[k]); } }
      if(onClick){ b.addEventListener('click', function(e){ onClick(b, e); }); }
      return b;
    }

    var viewBtn=menuItem('View', I_VIEW, '', {}, function(btn, e){
      e.preventDefault();
      if(window.uc2OpenPromptModal){ window.uc2OpenPromptModal(btn); }
      if(window.uc2TrackOpen){ window.uc2TrackOpen(card); }
    });
    var saveBtn=menuItem('Save Collection', I_SAVE, 'uc2-collection-btn', {'data-id':postId,'data-title':title,'data-url':postUrl}, null);
    var shareBtn=menuItem('Share', I_SHARE, 'share-btn', {'data-id':postId,'data-title':title,'data-url':postUrl}, function(btn, e){
      e.preventDefault();
      if(window.openSharePopup){ window.openSharePopup(btn); }
    });
    var useBtn=menuItem('Use', I_USE, 'use-btn', {}, function(btn, e){
      e.preventDefault();
      mgsOpenUseGuide(card);
    });

    menu.appendChild(viewBtn);
    menu.appendChild(saveBtn);
    menu.appendChild(shareBtn);
    menu.appendChild(useBtn);

    function openMoreMenu(m, anchor, cardEl){
      var isOpen=m.classList.contains('open')&&m._anchor===anchor;
      if(window.closeAllCopyDropdowns){ window.closeAllCopyDropdowns(); }
      if(window.uc2CloseAllMoreMenus){ window.uc2CloseAllMoreMenus(); }
      if(isOpen){ return; }
      m._origParent=m.parentNode;
      m._origNext=m.nextSibling;
      m._card=cardEl;
      m._anchor=anchor;
      document.body.appendChild(m);
      m.classList.add('open');
      if(cardEl){ cardEl.classList.add('has-open-dropdown'); }
      if(window.uc2PositionMoreMenu){ window.uc2PositionMoreMenu(m, anchor); }
      else { placeFixed(m, anchor); }
    }
    menuBtn.addEventListener('click',function(e){
      e.preventDefault(); e.stopPropagation();
      openMoreMenu(menu, menuBtn, card);
    });

    wrap.appendChild(group);
    wrap.appendChild(menuBtn);
    wrap.appendChild(varMenu);
    wrap.appendChild(menu);
    return wrap;
  }

  // Wait for DOM ready
  function mgsRelatedPosts() {
    var grid = document.getElementById('mgs-related-grid');
    if (!grid) return;

    // Get current post labels
    var labelLinks = document.querySelectorAll(
      '.post-labels a, a[rel="tag"], .labels a, .uc2-category-badge, a.uc2-category-badge'
   );

    if (!labelLinks || labelLinks.length === 0) {
      grid.innerHTML =
        '<p class="mgs-rel-empty">No related posts found.</p>';
      return;
   }

    // Prefer hub category label over tool/tag labels
    var hub={Photo:1,AI:1,Motion:1,Invitation:1,Video:1,Background:1,Text:1};
    var firstLabel='';
    for(var li=0;li<labelLinks.length;li++){
      var nm=(labelLinks[li].textContent||'').replace(/\s+/g,' ').trim();
      if(!nm) continue;
      if(!firstLabel) firstLabel=nm;
      if(hub[nm]){firstLabel=nm;break;}
    }
    if(!firstLabel) firstLabel=(labelLinks[0].textContent||'').trim();
    var blogUrl = window.location.origin;
    var currentUrl = window.location.href;
    function mgsNormUrl(u){
      try{
        var x=document.createElement('a');
        x.href=u||'';
        var host=(x.hostname||'').replace(/^www\./i,'').toLowerCase();
        var path=(x.pathname||'/').replace(/\/+$/,'')||'/';
        return host+path;
      }catch(e){
        return String(u||'').split('?')[0].split('#')[0].replace(/^https?:\/\//i,'').replace(/^www\./i,'').replace(/\/+$/,'');
      }
    }
    var currentNorm=mgsNormUrl(currentUrl);
    var maxResults = 6;

    var apiUrl = blogUrl +
      '/feeds/posts/default/-/' +
      encodeURIComponent(firstLabel) +
      '?alt=json&max-results=' + (maxResults + 1) +
      '&orderby=published';

    // Fetch posts via JSONP using script tag
    var callbackName = 'mgsRelCb_' +
      Math.random().toString(36).substr(2, 9);

    window[callbackName] = function(data) {
      // Cleanup script tag
      var old = document.getElementById('mgs-rel-script');
      if (old) old.parentNode.removeChild(old);
      delete window[callbackName];

      var entries = (data.feed && data.feed.entry) || [];

      // Filter out current post
      var filtered = entries.filter(function(entry) {
        var links = entry.link || [];
        for (var i = 0; i < links.length; i++) {
          if (links[i].rel === 'alternate' &&
              mgsNormUrl(links[i].href) === currentNorm) {
            return false;
          }
        }
        return true;
      });

      // Limit to maxResults
      filtered = filtered.slice(0, maxResults);

      if (filtered.length === 0) {
        grid.innerHTML =
          '<p class="mgs-rel-empty">No related posts found.</p>';
        return;
      }

      // Build cards
      filtered.forEach(function(entry) {
        // Get post URL
        var postUrl = '#';
        var links = entry.link || [];
        for (var j = 0; j < links.length; j++) {
          if (links[j].rel === 'alternate') {
            postUrl = links[j].href;
            break;
          }
        }

        // Get post title
        var title = entry.title
          ? entry.title.$t
          : 'Untitled Post';

        // Get thumbnail (high-res, uncropped) — content-first extractor
        var imgUrl = mgsGetCardImage(entry);

        // Fallback image
        if (!imgUrl) {
          imgUrl = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiPrQaJk-Pf87dHxd2QX7qqxE4T1lX5I5gKBHrca_jKa321zGWjxMl4Hz8jxr14dLA1Szje7lx4i40GfflOP9TGI9f4ddnv4YUyD2jz7H5tp2XNWAWS9vTzp1b4WwRRNyfKR0z0qboPIhX3SVnlYYPbFFXz_8PvuvZL5KIlpqLqV-bdXHTRe0sPKOj4Tl0/s1600/mgt_logo.png';
        }

        var card = document.createElement('article');
        card.className = 'mgs-related-card';

        var postId = mgsEntryId(entry);
        card.setAttribute('data-post-id', postId);
        card.setAttribute('data-url', postUrl);
        card.setAttribute('data-title', title);
        card.setAttribute('data-id', postId);

        var contentHtml = (entry.content && entry.content.$t) || '';
        var parsed = mgsParsePrompt(contentHtml);
        var fallbackPrompt = parsed.prompt || mgsPlainText(contentHtml);
        card._parsedPrompt = parsed.prompt || fallbackPrompt;
        card._parsedNegativePrompt = parsed.negative;
        card._parsedHasNegative = parsed.hasNegative;
        card._parsedIntro = parsed.intro;
        card._parsedTools = parsed.tools;
        card._parsedGuide = parsed.guide;
        card._parsedExpected = parsed.expected;
        card._parsedTips = parsed.tips;
        card._parsedCover = imgUrl;

        var promptBox = document.createElement('div');
        promptBox.className = 'prompttextbox';
        promptBox.id = 'prompt-' + postId;
        promptBox.style.display = 'none';
        promptBox.innerHTML = parsed.promptHTML || mgsTextToHTML(fallbackPrompt || title);
        card.appendChild(promptBox);

        var uTitle = document.createElement('div');
        uTitle.className = 'universal-title';
        uTitle.style.display = 'none';
        uTitle.textContent = title;
        card.appendChild(uTitle);

        var guideBox = document.createElement('div');
        guideBox.className = 'use-guide-data';
        guideBox.style.display = 'none';
        guideBox.innerHTML = parsed.howTo || '';
        card.appendChild(guideBox);

        if (window.uc2Public && window.uc2Public.registerPromptSnapshot) {
          window.uc2Public.registerPromptSnapshot(postId, {
            id: postId,
            title: title,
            url: postUrl,
            promptText: card._parsedPrompt,
            negative: parsed.negative,
            hasNegative: parsed.hasNegative,
            thumb: imgUrl
          });
        }

        var thumbLink = document.createElement('a');
        thumbLink.className = 'mgs-related-thumb';
        thumbLink.href = postUrl;
        thumbLink.setAttribute('aria-hidden','true');
        var img = document.createElement('img');
        img.src = imgUrl;
        img.alt = title.replace(/"/g,'&quot;');
        img.loading = 'lazy';
        img.decoding = 'async';
        thumbLink.appendChild(img);

        var content = document.createElement('div');
        content.className = 'mgs-related-content';
        var h = document.createElement('h3');
        h.className = 'mgs-related-title';
        var tlink = document.createElement('a');
        tlink.href = postUrl;
        tlink.textContent = title;
        h.appendChild(tlink);
        content.appendChild(h);
        content.appendChild(mgsBuildActions(card, {title: title, postUrl: postUrl}));

        card.appendChild(thumbLink);
        card.appendChild(content);
        grid.appendChild(card);
      });
    };

    // Append JSONP script
    var s = document.createElement('script');
    s.id = 'mgs-rel-script';
    s.src = apiUrl + '&callback=' + callbackName;
    s.onerror = function() {
      grid.innerHTML =
        '<p class="mgs-rel-empty">Could not load related posts.</p>';
    };
    document.body.appendChild(s);
  }

  // Run after page load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mgsRelatedPosts);
  } else {
    mgsRelatedPosts();
  }

})();
