main.script:
//

function copyText(id, btn) {

  var text = document.getElementById(id).innerText

  .replace(/\n\s*\n/g, '\n')

  .replace(/[ \t]+/g, ' ')

  .replace(/\n+/g, '\n')

  .trim();

  if (navigator.clipboard) {

    navigator.clipboard.writeText(text);

  } else {

    let textarea = document.createElement("textarea");

    textarea.value = text;

    document.body.appendChild(textarea);

    textarea.select();

    document.execCommand("copy");

    document.body.removeChild(textarea);

  }

  var origHTML = btn.innerHTML;

  btn.innerHTML = "&#10003; Copied!";

  btn.style.background = "linear-gradient(135deg,#4ade80,#22c55e)";

  btn.style.boxShadow = "0 0 16px rgba(74,222,128,.45)";

  btn.style.color = "#000";

  setTimeout(function(){

    btn.innerHTML = origHTML;

    btn.style.background = "";

    btn.style.boxShadow = "";

    btn.style.color = "";

  }, 1800);

}

/* =========================
   COPY DROPDOWN FUNCTIONS
========================= */

function positionCopyDropdown(dd,btn){
if(!dd||!btn)return;
var rect=btn.getBoundingClientRect();
var margin=8;
var ddW=dd.offsetWidth||200;
var ddH=dd.offsetHeight||160;
var spaceBelow=window.innerHeight-rect.bottom;
var spaceAbove=rect.top;
var openUp=(spaceBelow<ddH+margin && spaceAbove>spaceBelow);
var top;
if(openUp){
top=rect.top-6-ddH;
if(top<margin)top=margin;
}else{
top=rect.bottom+6;
if(top+ddH>window.innerHeight-margin){
top=Math.max(margin,window.innerHeight-margin-ddH);
}
}
dd.style.position='fixed';
dd.style.top=top+'px';
dd.style.bottom='auto';
dd.style.right='auto';
dd.style.margin='0';
dd.style.zIndex='100002';
var left=(rect.left+(rect.width/2))-(ddW/2);
var maxLeft=window.innerWidth-ddW-margin;
if(maxLeft<margin)maxLeft=margin;
if(left<margin)left=margin;
if(left>maxLeft)left=maxLeft;
dd.style.left=left+'px';
}
function closeAllCopyDropdowns(){
document.querySelectorAll('.copy-dropdown.open').forEach(function(d){
if(d._card){d._card.classList.remove('has-open-dropdown');}
if(d._origParent){d._origParent.insertBefore(d,d._origNext||null);d.style.position='';d.style.top='';d.style.right='';d.style.left='';d.style.bottom='';d.style.margin='';d.style.zIndex='';}
d._anchor=null;d.classList.remove('open');
});
}
window.closeAllCopyDropdowns=closeAllCopyDropdowns;
function toggleCopyDropdown(btn,nav){
/* MGS FIX 2026-07-11: Stop event propagation to prevent document click handler from closing the dropdown prematurely */
if(nav&&nav.stopPropagation){nav.stopPropagation();}else if(window.event&&window.event.stopPropagation){window.event.stopPropagation();}
if(window.uc2CloseAllMoreMenus){window.uc2CloseAllMoreMenus();}
var group=btn.closest('.copy-action-group');
if(!group)return;
var dd=group.querySelector('.copy-dropdown');
if(!dd){var list=document.querySelectorAll('body > .copy-dropdown');for(var i=0;i<list.length;i++){if(list[i]._origGroup===group){dd=list[i];break;}}}
if(!dd)return;
var isOpen=dd.classList.contains('open');
/* MGS FIX 2026-07-11: Remove has-open-dropdown from all cards when closing */
document.querySelectorAll('.copy-dropdown.open').forEach(function(d){if(d._card){d._card.classList.remove('has-open-dropdown');}if(d._origParent){d._origParent.insertBefore(d,d._origNext||null);d.style.position='';d.style.top='';d.style.right='';d.style.left='';d.style.bottom='';d.style.margin='';d.style.zIndex='';}d._anchor=null;d.classList.remove('open');});
if(!isOpen){
dd._origParent=dd.parentNode;
dd._origNext=dd.nextSibling;
dd._origGroup=group;
dd._card=btn.closest('.universal-card');
dd._anchor=btn;
document.body.appendChild(dd);
dd.classList.add('open');
if(dd._card){dd._card.classList.add('has-open-dropdown');}
positionCopyDropdown(dd,btn);
}
}
window.positionCopyDropdown=positionCopyDropdown;
window.toggleCopyDropdown=toggleCopyDropdown;

function getCopyData(card){
if(!card)return{prompt:'',negative:'',hasNegative:false};
var promptText=(typeof card._parsedPrompt==='string')?card._parsedPrompt.trim():'';
var negativeText=(typeof card._parsedNegativePrompt==='string')?card._parsedNegativePrompt.trim():'';
var hasNegative=!!card._parsedHasNegative&&negativeText.length>0;
return{prompt:promptText,negative:negativeText,hasNegative:hasNegative};
}

function doCopyFeedback(btn){
var origHTML=btn.innerHTML;
btn.innerHTML='&#10003; Copied!';
btn.style.background='linear-gradient(135deg,#4ade80,#22c55e)';
btn.style.boxShadow='0 0 16px rgba(74,222,128,.45)';
btn.style.color='#000';
setTimeout(function(){
btn.innerHTML=origHTML;
btn.style.background='';
btn.style.boxShadow='';
btn.style.color='';
},1800);
}

function updateCopyCounter(card){
var ce=card.querySelector('.counter-num');
if(!ce)return;
var pid=(card.querySelector('.copy-prompt-btn')||{}).getAttribute('data-id')||'';
var key='cc_'+pid,cnt=parseInt(localStorage.getItem(key)||'0')+1;
localStorage.setItem(key,cnt);
ce.textContent=cnt>=1000?(cnt/1000).toFixed(1)+'k':cnt;
}

function copyPromptOnly(btn){
var dd=btn.closest('.copy-dropdown');
var card=dd._card||btn.closest('.universal-card');
var data=getCopyData(card);
if(data.prompt){
if(navigator.clipboard){navigator.clipboard.writeText(data.prompt);}
else{var ta=document.createElement('textarea');ta.value=data.prompt;document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);}
doCopyFeedback(btn);
updateCopyCounter(card);
}
var dd=btn.closest('.copy-dropdown');if(dd._card){dd._card.classList.remove('has-open-dropdown');}if(dd._origParent){dd._origParent.insertBefore(dd,dd._origNext||null);dd.style.position='';dd.style.top='';dd.style.right='';dd.style.left='';dd.style.bottom='';dd.style.margin='';dd.style.zIndex='';}dd.classList.remove('open');
}

function copyNegativePrompt(btn){
var dd=btn.closest('.copy-dropdown');
var card=dd._card||btn.closest('.universal-card');
var data=getCopyData(card);
if(data.hasNegative&&data.negative){
if(navigator.clipboard){navigator.clipboard.writeText(data.negative);}
else{var ta=document.createElement('textarea');ta.value=data.negative;document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);}
doCopyFeedback(btn);
updateCopyCounter(card);
}else{
showToast('No Negative Prompt Available');
}
var dd=btn.closest('.copy-dropdown');if(dd._card){dd._card.classList.remove('has-open-dropdown');}if(dd._origParent){dd._origParent.insertBefore(dd,dd._origNext||null);dd.style.position='';dd.style.top='';dd.style.right='';dd.style.left='';dd.style.bottom='';dd.style.margin='';dd.style.zIndex='';}dd.classList.remove('open');
}

function copyAllPrompt(btn){
var dd=btn.closest('.copy-dropdown');
var card=dd._card||btn.closest('.universal-card');
var data=getCopyData(card);
var all='';
if(data.prompt){all+='Prompt:\n'+data.prompt;}
if(data.hasNegative&&data.negative){all+=(all?'\n\n':'')+'Negative Prompt:\n'+data.negative;}
if(!all){all=data.prompt||'';}
if(all){
if(navigator.clipboard){navigator.clipboard.writeText(all);}
else{var ta=document.createElement('textarea');ta.value=all;document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);}
doCopyFeedback(btn);
updateCopyCounter(card);
}
var dd=btn.closest('.copy-dropdown');if(dd._card){dd._card.classList.remove('has-open-dropdown');}if(dd._origParent){dd._origParent.insertBefore(dd,dd._origNext||null);dd.style.position='';dd.style.top='';dd.style.right='';dd.style.left='';dd.style.bottom='';dd.style.margin='';dd.style.zIndex='';}dd.classList.remove('open');
}

function doSearch(){

  let q = document.getElementById("searchInput").value.trim();

  if(q !== ""){

    window.location.href =
    "/search?q=" + encodeURIComponent(q);

  }

}

document.addEventListener("DOMContentLoaded", function(){

  var searchBox =
  document.getElementById("searchInput");

  if(searchBox){

    searchBox.addEventListener("keypress", function(e){

      if(e.key === "Enter"){

        doSearch();

      }

    });

  }

});

