window.uc2Public=window.uc2Public||{};
window.uc2Public.initCompareSlider=function(card,container){
  try{
    if(!card||!container||!card.querySelector||!container.appendChild){return false;}
    var media=card.querySelector('.universal-media');
    if(!media){return false;}
    var all=Array.from(media.querySelectorAll('img'));
    function isCover(img,index){
      if(!img){return true;}
      if(img.closest&&img.closest('.uc2-cover-thumb,[data-uc2-cover="true"]')){return true;}
      if(index===0){
        var s=String(img.getAttribute('src')||img.src||'').toLowerCase();
        if(s.indexOf('cover')!==-1||s.indexOf('thumb')!==-1){return true;}
      }
      return false;
    }
    var imgs=[];
    for(var i=0;i<all.length;i++){
      var im=all[i];
      var src=im.getAttribute('src')||im.src||'';
      if(!src||src.indexOf('data:')===0){continue;}
      if(isCover(im,i)){continue;}
      imgs.push(src);
    }
    if(imgs.length<2){return false;}
    function hiRes(u){try{u=String(u).replace(/\/s\d+(-[a-z0-9-]+)?\//gi,'/s1600/').replace(/\/w\d+-h\d+(-[a-z0-9-]+)?\//gi,'/s1600/').replace(/=s\d+(-[a-z0-9-]+)?/gi,'=s1600').replace(/=w\d+-h\d+(-[a-z0-9-]+)?/gi,'=s1600').replace(/-c-rw/gi,'').replace(/-c(?=[/?]|$)/gi,'');}catch(e){}return u;}
    var beforeSrc=hiRes(imgs[0]);
    var afterSrc=hiRes(imgs[1]);
    container.innerHTML='<div class="compare-container">'
      +'<img class="img-before" src="'+afterSrc+'" alt="After Editing Image" loading="lazy" decoding="async"/>'
      +'<div class="img-after"><img src="'+beforeSrc+'" alt="Before Editing Image" loading="lazy" decoding="async"/></div>'
      +'<div class="ba-label-wrap ba-before-wrap"><div class="ba-label ba-label-before">Before</div></div>'
      +'<div class="ba-label-wrap ba-after-wrap"><div class="ba-label ba-label-after">After</div></div>'
      +'<input class="slider" type="range" min="0" max="100" value="50" aria-label="Before and After Image Comparison Slider"/>'
      +'<div class="slider-handle"></div>'
      +'</div>';
    var slider=container.querySelector('.slider');
    var afterBox=container.querySelector('.img-after');
    var handle=container.querySelector('.slider-handle');
    var cc=container.querySelector('.compare-container');
    if(!slider||!afterBox||!handle){return false;}
    function updateSlider(){
      var v=slider.value;
      afterBox.style.clipPath='inset(0 '+(100-v)+'% 0 0)';
      var bw=container.querySelector('.ba-before-wrap');
      var aw=container.querySelector('.ba-after-wrap');
      if(bw&&aw){bw.style.width=v+'%';aw.style.width=(100-v)+'%';}
      handle.style.left=v+'%';
    }
    updateSlider();
    slider.addEventListener('input',updateSlider);
    if(cc){
      var isTouch=(window.matchMedia&&window.matchMedia('(hover: none)').matches)||('ontouchstart' in window);
      var hoverFrame=null,hoverPercent=50,resetTimer=null;
      function setP(p){slider.value=Math.max(0,Math.min(100,p));updateSlider();}
      function queueHover(ev){var r=cc.getBoundingClientRect();hoverPercent=((ev.clientX-r.left)/r.width)*100;if(hoverFrame!==null){return;}hoverFrame=window.requestAnimationFrame(function(){hoverFrame=null;setP(hoverPercent);});}
      if(!isTouch){
        cc._mgsResetToCenter=function(){
          if(hoverFrame!==null){window.cancelAnimationFrame(hoverFrame);hoverFrame=null;}
          if(resetTimer){window.clearTimeout(resetTimer);}
          cc.classList.add('ba-resetting');
          setP(50);
          resetTimer=window.setTimeout(function(){cc.classList.remove('ba-resetting');resetTimer=null;},300);
        };
        cc.addEventListener('mouseenter',function(){
          var prev=window.__mgsActiveCompareCard;
          if(prev&&prev!==cc&&typeof prev._mgsResetToCenter==='function'){prev._mgsResetToCenter();}
          window.__mgsActiveCompareCard=cc;
          cc.classList.remove('ba-resetting');
          if(resetTimer){window.clearTimeout(resetTimer);resetTimer=null;}
        });
        cc.addEventListener('mousemove',queueHover);
        cc.addEventListener('mouseleave',function(){if(hoverFrame!==null){window.cancelAnimationFrame(hoverFrame);hoverFrame=null;setP(hoverPercent);}});
      }
    }
    return true;
  }catch(e){return false;}
};

window.addEventListener("DOMContentLoaded", function(){

function uc2IsCoverImage(img, index){
if(!img){return false;}

/* Existing manually wrapped cover support. */
if(img.closest(".uc2-cover-thumb,[data-uc2-cover='true']")){return true;}

/* Compose-view shortcut: only the first post image can be a filename-marked cover. */
if(index === 0){
var src=String(img.getAttribute("src")||img.src||"").toLowerCase();
if(src.indexOf("cover") !== -1 || src.indexOf("thumb") !== -1){return true;}
}

return false;
}

window.mgsInitCardMedia=function(card){

if(card.getAttribute("data-mgs-media")==="true"){return;}
card.setAttribute("data-mgs-media","true");
card.classList.add("uc-initialized");

let media = card.querySelector(".universal-media");
if(!media){return;}
let allImgs = Array.from(media.querySelectorAll("img"));
let coverImgs = allImgs.filter(uc2IsCoverImage);

/* Hide an automatically detected Compose-view cover when a single real image
   leaves the original media DOM in place. Wrapped covers remain hidden by CSS. */
coverImgs.forEach(function(img){
img.classList.add("uc2-auto-cover-thumb");
});

let imgs = allImgs.filter(function(img, index){
return !uc2IsCoverImage(img, index);
});

if(imgs.length == 2){

let img1 = imgs[0].src;
let img2 = imgs[1].src;

media.innerHTML = `

<div class="compare-container">

<img
class="img-before"
src="${img2.replace('/w640-h426/','/w400-h275/')}"
width="370"
height="246"
loading="lazy"
decoding="async"
alt="After Editing Image"/>

<div class="img-after">
<img
src="${img1.replace('/w640-h426/','/w400-h275/')}"
width="370"
height="246"
loading="lazy"
decoding="async"
alt="Before Editing Image"/>
</div>

<div class='ba-label-wrap ba-before-wrap'>
  <div class='ba-label ba-label-before'>
    Before
  </div>
</div>

<div class='ba-label-wrap ba-after-wrap'>
  <div class='ba-label ba-label-after'>
    After
  </div>
</div>
<input
class="slider"
type="range"
min="0"
max="100"
value="50"
aria-label="Before and After Image Comparison Slider"/>

<div class="slider-handle">
<img src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjPt4e6EjoOpeCtYFeP9yGXIYcKHBMFLErW2wDSgVEFI4BkrUNF-nsehnDj2Oi_Ika5FEj7X7XxJcxO-GsZzvhXBPLSR2OBDXusaLyQjGIwiw4drQjJLzUJ_dKDVnOdyv39aPSyrzBZ1A7pQ3WTY3B0iR0Oh_JmG3FBHXOgSYtHgHeY4W0op2C290K0C9c/s444/PNG_LINE.png" alt="" width="94" height="444" decoding="async">
</div>

</div>

`;

let slider = media.querySelector(".slider");
let afterBox = media.querySelector(".img-after");
let handle = media.querySelector(".slider-handle");

function updateSlider(){

let value = slider.value;

/* img-after: reveals from left as value increases */
afterBox.style.clipPath =
`inset(0 ${100 - value}% 0 0)`;
const beforeWrap =
media.querySelector('.ba-before-wrap');

const afterWrap =
media.querySelector('.ba-after-wrap');

if(beforeWrap && afterWrap){

beforeWrap.style.width =
value + '%';

afterWrap.style.width =
(100 - value) + '%';

}
handle.style.left = value + "%";

/* Before label: same clip direction as img-after
   value=50 → inset(0 50% 0 0) → left half visible (where before image shows) ✓
   value=0  → inset(0 100% 0 0) → fully hidden (handle at left edge) ✓
   value=100 → inset(0 0% 0 0)  → fully visible ✓ */
}

updateSlider();

slider.addEventListener("input", updateSlider);

/* Desktop only: the pointer controls this card's comparison while inside it.
   The native range input remains untouched as the mouse/touch drag fallback. */
const compareContainer = media.querySelector(".compare-container");
const isTouchDevice = window.matchMedia("(hover: none)").matches ||
  ("ontouchstart" in window);
let hoverFrame = null;
let hoverPercent = 50;
let resetTimer = null;

function setSliderPercent(percent){
  slider.value = Math.max(0, Math.min(100, percent));
  updateSlider();
}

function queueHoverUpdate(event){
  const rect = compareContainer.getBoundingClientRect();
  hoverPercent = ((event.clientX - rect.left) / rect.width) * 100;

  if(hoverFrame !== null){return;}
  hoverFrame = window.requestAnimationFrame(function(){
    hoverFrame = null;
    setSliderPercent(hoverPercent);
  });
}

if(!isTouchDevice && compareContainer){
  compareContainer._mgsResetToCenter = function(){
    if(hoverFrame !== null){
      window.cancelAnimationFrame(hoverFrame);
      hoverFrame = null;
    }
    if(resetTimer){
      window.clearTimeout(resetTimer);
    }

    compareContainer.classList.add("ba-resetting");
    setSliderPercent(50);
    resetTimer = window.setTimeout(function(){
      compareContainer.classList.remove("ba-resetting");
      resetTimer = null;
    }, 300);
  };

  compareContainer.addEventListener("mouseenter", function(){
    const previousContainer = window.__mgsActiveCompareCard;

    if(previousContainer && previousContainer !== compareContainer &&
       typeof previousContainer._mgsResetToCenter === "function"){
      previousContainer._mgsResetToCenter();
    }

    window.__mgsActiveCompareCard = compareContainer;
    compareContainer.classList.remove("ba-resetting");
    if(resetTimer){
      window.clearTimeout(resetTimer);
      resetTimer = null;
    }
  });

  compareContainer.addEventListener("mousemove", queueHoverUpdate);

  compareContainer.addEventListener("mouseleave", function(){
    if(hoverFrame !== null){
      window.cancelAnimationFrame(hoverFrame);
      hoverFrame = null;
      setSliderPercent(hoverPercent);
    }
    /* Keep this card at its last reveal position until another card is entered. */
  });
}

}

else if(imgs.length >= 3){

let sliderHTML = `
<div class="retouch-slider">

<div class="retouch-track">
`;

imgs.forEach(function(img){

sliderHTML += `
<img src="${img.src}" alt="Retouch example slide" loading="lazy" decoding="async">
`;

});

sliderHTML += `
</div>

<button class="retouch-arrow retouch-prev"><svg fill='none' height='20' style='vertical-align:-2px' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.8' viewBox='0 0 24 24' width='20' xmlns='http://www.w3.org/2000/svg'><path d='m15 18-6-6 6-6'/></svg></button>
<button class="retouch-arrow retouch-next"><svg fill='none' height='20' style='vertical-align:-2px' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.8' viewBox='0 0 24 24' width='20' xmlns='http://www.w3.org/2000/svg'><path d='m9 18 6-6-6-6'/></svg></button>

</div>

<div class="retouch-dots"></div>
`;

media.innerHTML = sliderHTML;

let track = media.querySelector(".retouch-track");
let slides = media.querySelectorAll(".retouch-track img");

let prev = media.querySelector(".retouch-prev");
let next = media.querySelector(".retouch-next");

let dotsWrap = media.querySelector(".retouch-dots");

let index = 0;

slides.forEach(function(_,i){

let dot = document.createElement("span");

dot.className = "retouch-dot";

if(i==0) dot.classList.add("active");

dot.onclick = function(){

index = i;
updateSlide();

};

dotsWrap.appendChild(dot);

});

function updateSlide(){

track.style.transform =
`translateX(-${index * 100}%)`;

let dots = media.querySelectorAll(".retouch-dot");

dots.forEach(function(dot){
dot.classList.remove("active");
});

dots[index].classList.add("active");

}

function autoSlide(){

index++;

if(index >= slides.length){
index = 0;
}

updateSlide();

}

let auto = setInterval(autoSlide,3000);

card.onmouseenter = function(){
clearInterval(auto);
};

card.onmouseleave = function(){
auto = setInterval(autoSlide,3000);
};

prev.onclick = function(){

index--;

if(index < 0){
index = slides.length - 1;
}

updateSlide();

};

next.onclick = function(){

index++;

if(index >= slides.length){
index = 0;
}

updateSlide();

};

}

};

document.querySelectorAll(".universal-card").forEach(window.mgsInitCardMedia);

});

