/* =========================
   USE GUIDE POPUP SYSTEM
========================= */

document.addEventListener("DOMContentLoaded",function(){

const popup=document.getElementById("usePopup");

const popupContent=document.getElementById("usePopupContent");

const closeBtn=document.getElementById("closeUsePopup");

/* ALL BUTTONS */

document.querySelectorAll(".use-btn").forEach(function(btn){

btn.addEventListener("click",function(){

let card=btn.closest(".universal-card");
if(!card){const mm=btn.closest(".uc2-more-menu");if(mm&&mm._card)card=mm._card;}
if(!card) return;

function esc(t){return String(t||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function plain(v){if(!v)return "";var d=document.createElement("div");d.innerHTML=v;return (d.textContent||"").replace(/\u00a0/g," ").replace(/[ \t]+/g," ").replace(/\n{3,}/g,"\n\n").trim();}

var tools=plain(card._parsedTools||"");
var howto=plain(card._parsedGuide||"");
var expected=plain(card._parsedExpected||"");
var tips=plain(card._parsedTips||"");

var guide=card.querySelector(".use-guide-data");
var raw=guide?plain(guide.innerHTML):"";
if(!howto && raw) howto=raw;

if(howto && /(?:^|\n)\s*(use|before|after|tips|warning|ai\s*tool|best\s*for)\s*:/i.test(howto)){
  var buckets={tools:[],howto:[],expected:[],tips:[]};
  howto.split(/\n/).forEach(function(line){
    line=line.trim();
    if(!line) return;
    var m=line.match(/^([^:]{1,40}):\s*([\s\S]*)$/);
    if(m){
      var lab=m[1].replace(/[^\w\s]/g,"").replace(/\s+/g," ").trim().toLowerCase();
      var val=m[2].trim();
      if(lab==="ai tool"||lab==="compatible ai tools"||lab==="compatible tools"){if(val)buckets.tools.push(val);return;}
      if(lab==="tips"){if(val)buckets.tips.push(val);return;}
      if(lab==="after"){if(val)buckets.expected.push("After: "+val);return;}
      if(val) buckets.howto.push(m[1].trim()+": "+val);
      else buckets.howto.push(line);
      return;
    }
    buckets.howto.push(line);
  });
  if(!tools && buckets.tools.length) tools=buckets.tools.join(", ");
  if(buckets.howto.length) howto=buckets.howto.join("\n");
  if(!expected && buckets.expected.length) expected=buckets.expected.join("\n");
  if(!tips && buckets.tips.length) tips=buckets.tips.join("\n");
}

function formatBody(text){
  var out="";
  String(text||"").split(/\n/).forEach(function(line){
    line=line.replace(/^\*+\s*|\s*\*+$/g,"").trim();
    if(!line) return;
    var sm=line.match(/^(.{1,42}?)\s*:\s*(.*)$/);
    if(sm && !/^https?:/i.test(sm[1]) && sm[1].length<42){
      out+="<div class='use-line'><span class='use-sub'>"+esc(sm[1])+"</span>"+(sm[2]?esc(sm[2]):"")+"</div>";
    }else{
      out+="<div class='use-line'>"+esc(line)+"</div>";
    }
  });
  return out;
}

var icoTools="<svg fill='none' height='18' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.9' viewBox='0 0 24 24' width='18'><path d='M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z'/></svg>";
var icoHow="<svg fill='none' height='18' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.9' viewBox='0 0 24 24' width='18'><path d='M4 19.5A2.5 2.5 0 0 1 6.5 17H20'/><path d='M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z'/></svg>";
var icoOut="<svg fill='none' height='18' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.9' viewBox='0 0 24 24' width='18'><path d='M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z'/><circle cx='12' cy='12' r='3'/></svg>";
var icoTips="<svg fill='none' height='18' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.9' viewBox='0 0 24 24' width='18'><path d='M9 18h6'/><path d='M10 22h4'/><path d='M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z'/></svg>";

var finalHTML="";
if(tools){
  var chips=tools.split(/[\n,\/|]+/).map(function(t){return t.replace(/^[-*•✅]\\s*/,"").trim();}).filter(Boolean);
  var badgesHTML=chips.map(function(t){
    var cls="badge-default";
    var tl=t.toLowerCase();
    if(tl.indexOf("chatgpt")>-1||tl.indexOf("dall")>-1) cls="badge-chatgpt";
    else if(tl.indexOf("flux")>-1) cls="badge-flux";
    else if(tl.indexOf("gemini")>-1) cls="badge-gemini";
    else if(tl.indexOf("midjourney")>-1) cls="badge-midjourney";
    else if(tl.indexOf("leonardo")>-1) cls="badge-leonardo";
    return "<span class='ai-tool-badge "+cls+"'>"+esc(t)+"</span>";
  }).join("");
  finalHTML+="<div class='use-item'><div class='use-sec-head'>"+icoTools+"<span>Compatible AI Tools</span></div><div class='ai-tool-badges'>"+badgesHTML+"</div></div>";
}
if(howto){
  finalHTML+="<div class='use-item'><div class='use-sec-head'>"+icoHow+"<span>How To Use This Prompt</span></div>"+formatBody(howto)+"</div>";
}
if(expected){
  finalHTML+="<div class='use-item'><div class='use-sec-head'>"+icoOut+"<span>Expected Output</span></div>"+formatBody(expected)+"</div>";
}
if(tips){
  finalHTML+="<div class='use-item'><div class='use-sec-head'>"+icoTips+"<span>Tips &amp; Variations</span></div>"+formatBody(tips)+"</div>";
}
if(!finalHTML){
  finalHTML="<div class='use-item'>No guide available for this prompt.</div>";
}

popupContent.innerHTML=finalHTML;

popup.classList.add("active");

});

});

/* CLOSE */

closeBtn.addEventListener("click",function(){

popup.classList.remove("active");

});

    /* MOBILE SWIPE CLOSE */

let startY=0;

popup.addEventListener("touchstart",function(e){

startY=e.touches[0].clientY;

});

popup.addEventListener("touchmove",function(e){

let endY=e.touches[0].clientY;

if(endY-startY>120){

popup.classList.remove("active");

}

});

/* CLICK OUTSIDE */

popup.addEventListener("click",function(e){

if(e.target===popup){

popup.classList.remove("active");

}

});

});

//

/* SWIPE CLOSE MENU */

document.addEventListener('DOMContentLoaded', function(){

var touchStartX = 0;
var touchEndX = 0;

var swipeMenu = document.querySelector('.menu');

if(swipeMenu){

swipeMenu.addEventListener('touchstart', function(e){
touchStartX = e.changedTouches[0].screenX;
});

swipeMenu.addEventListener('touchend', function(e){
touchEndX = e.changedTouches[0].screenX;
if(touchEndX - touchStartX > 80){
closeMobileMenu();
}
});

}

});

//

/* PREVENT MOBILE MENU JUMP */

document.addEventListener('touchmove', function(e){

if(document.body.classList.contains('menu-open')){

if(!e.target.closest('.menu')){

e.preventDefault();

}

}

},{ passive:false });

//

/* ACTIVE BOTTOM NAV & MENU HIGHLIGHT */

document.addEventListener('DOMContentLoaded', function(){

var currentUrl = window.location.href.split(/[?#]/)[0];
var navItems = document.querySelectorAll('.bottom-nav-item, .menu a');

navItems.forEach(function(item){
  var itemUrl = item.href.split(/[?#]/)[0];
  if(itemUrl === currentUrl){
    item.classList.add('active');

    /* Highlight Parents if in dropdown */
    var subDrop = item.closest('.sub-drop');
    if(subDrop) subDrop.classList.add('active-child');

    var mainDrop = item.closest('.dropdown');
    if(mainDrop) mainDrop.classList.add('active-child');
  }
});

});

//

//

/* =========================
   SMART NAVBAR SCROLL
========================= */

let lastScrollTop = 0;

const header =
document.querySelector('.header');

const bottomBar =
document.querySelector('.mobile-bottom-bar');

window.addEventListener('scroll', function(){

let scrollTop =
window.pageYOffset ||
document.documentElement.scrollTop;

/* ADD BACKGROUND */

if(scrollTop > 20){

header.classList.add('scrolled');

}else{

header.classList.remove('scrolled');

}

/* SCROLL DOWN */

if(scrollTop > lastScrollTop &&
scrollTop > 80){

header.classList.add('hide-header');

if(bottomBar){

bottomBar.classList.add('hide-bottom-bar');

}

}

/* SCROLL UP */

else{

header.classList.remove('hide-header');

if(bottomBar){

bottomBar.classList.remove('hide-bottom-bar');

}

}

lastScrollTop = scrollTop;

});

//

//

/* =========================
   MOBILE MENU SYSTEM
========================= */

var mobileMenu, mobileBtn, mobileOverlay;

/* TOGGLE — called from onclick in HTML */
function toggleMobileMenu(event){
if(event){
event.preventDefault();
event.stopPropagation();
}
mobileMenu = mobileMenu || document.querySelector('.menu');
mobileBtn  = mobileBtn  || document.querySelector('.mobile-menu-btn');
mobileOverlay = mobileOverlay || document.querySelector('.mobile-overlay');
if(!mobileMenu) return;

mobileMenu.classList.toggle('active');
if(mobileBtn) mobileBtn.classList.toggle('active');
if(mobileOverlay) mobileOverlay.classList.toggle('active');
document.body.classList.toggle('menu-open');
}

/* CLOSE MENU */
function closeMobileMenu(){
mobileMenu = mobileMenu || document.querySelector('.menu');
mobileBtn  = mobileBtn  || document.querySelector('.mobile-menu-btn');
mobileOverlay = mobileOverlay || document.querySelector('.mobile-overlay');
if(!mobileMenu) return;

mobileMenu.classList.remove('active');
if(mobileBtn) mobileBtn.classList.remove('active');
if(mobileOverlay) mobileOverlay.classList.remove('active');
document.body.classList.remove('menu-open');

/* RESET ALL SUB-DROPS */
document.querySelectorAll('.sub-drop').forEach(function(item){
item.classList.remove('active');
});
document.querySelectorAll('.dropdown').forEach(function(item){
item.classList.remove('active');
});
}

document.addEventListener('DOMContentLoaded', function(){

mobileMenu    = document.querySelector('.menu');
mobileBtn     = document.querySelector('.mobile-menu-btn');
mobileOverlay = document.querySelector('.mobile-overlay');

/* OVERLAY CLICK */
if(mobileOverlay){
mobileOverlay.addEventListener('click', closeMobileMenu);
}

/* OUTSIDE CLICK */
document.addEventListener('click', function(e){
if(mobileMenu && mobileMenu.classList.contains('active')
  && !mobileMenu.contains(e.target)
  && mobileBtn && !mobileBtn.contains(e.target)){
closeMobileMenu();
}
});

/* ESC KEY */
document.addEventListener('keydown', function(e){
if(e.key === 'Escape') closeMobileMenu();
});

/* MOBILE DROPDOWN */
document.querySelectorAll('.dropdown > a').forEach(function(dropBtn){
dropBtn.addEventListener('click', function(e){
if(window.innerWidth <= 768){
e.preventDefault();
var parent = this.parentElement;
document.querySelectorAll('.dropdown').forEach(function(item){
if(item !== parent) item.classList.remove('active');
});
parent.classList.toggle('active');
}
});
});

/* MOBILE SUB-DROP ACCORDION */
document.querySelectorAll('.sub-drop > a').forEach(function(subBtn){
subBtn.addEventListener('click', function(e){
if(window.innerWidth <= 768){
e.preventDefault();
e.stopPropagation();
var parent = this.parentElement;
var isActive = parent.classList.contains('active');
document.querySelectorAll('.sub-drop').forEach(function(item){
item.classList.remove('active');
});
if(!isActive) parent.classList.add('active');
}
});
});

/* AUTO CLOSE ON LINK CLICK */
document.querySelectorAll('.menu .sub-menu a, .menu > a').forEach(function(link){
link.addEventListener('click', function(){
if(window.innerWidth <= 768) closeMobileMenu();
});
});

/* RESIZE RESET */
window.addEventListener('resize', function(){
if(window.innerWidth > 768){
closeMobileMenu();
document.querySelectorAll('.dropdown').forEach(function(item){
item.classList.remove('active');
});
}
});

});

