body.script:
//
(function(){
  var UC2_AI_TOOLS=[
    {name:'ChatGPT',slug:'chatgpt',patterns:[/\bchat\s*gpt\b/i,/\bgpt[-\s]?(3\.5|4|4o|5)?\b/i,/\bopenai\b/i]},
    {name:'Gemini',slug:'gemini',patterns:[/\bgemini\b/i,/\bgoogle\s+ai\b/i,/\bbard\b/i]},
    {name:'Midjourney',slug:'midjourney',patterns:[/\bmid\s*journey\b/i,/\bmidjourney\b/i,/\b--ar\s*\d/i]},
    {name:'DALL·E',slug:'dalle',patterns:[/\bdall[\s-]*e\b/i,/\bdalle\b/i]},
    {name:'Stable Diffusion',slug:'stable-diffusion',patterns:[/\bstable\s+diffusion\b/i,/\bsd(xl|3)?\b/i]},
    {name:'Flux',slug:'flux',patterns:[/\bflux\b/i,/\bflux\s*(dev|pro|schnell)\b/i]},
    {name:'Leonardo AI',slug:'leonardo-ai',patterns:[/\bleonardo\s*ai\b/i,/\bleonardo\b/i]},
    {name:'Ideogram',slug:'ideogram',patterns:[/\bideogram\b/i]},
    {name:'Canva',slug:'canva',patterns:[/\bcanva\b/i]},
    {name:'Adobe Firefly',slug:'adobe-firefly',patterns:[/\bfirefly\b/i,/\badobe\s+firefly\b/i]},
    {name:'Runway',slug:'runway',patterns:[/\brunway\b/i,/\bgen[-\s]?(2|3|4)\b/i]},
    {name:'Kling AI',slug:'kling-ai',patterns:[/\bkling\b/i,/\bkling\s*ai\b/i]},
    {name:'Sora',slug:'sora',patterns:[/\bsora\b/i]},
    {name:'Pika',slug:'pika',patterns:[/\bpika\b/i,/\bpika\s*labs\b/i]},
    {name:'Veo',slug:'veo',patterns:[/\bveo\b/i,/\bveo\s*(2|3)?\b/i]},
    {name:'CapCut',slug:'capcut',patterns:[/\bcap\s*cut\b/i,/\bcapcut\b/i]},
    {name:'Photoshop',slug:'photoshop',patterns:[/\bphotoshop\b/i,/\bpsd\b/i]},
    {name:'After Effects',slug:'after-effects',patterns:[/\bafter\s+effects\b/i,/\baftereffects\b/i,/\bae\s+template\b/i]}
  ];

  var UC2_CATEGORIES=[
    {name:'Photo Editing',slug:'photo-editing',patterns:[/\bphoto\s*(editing|retouch|cleaning|enhance|generate)\b/i,/\bretouch\b/i,/\bcolor\s*grading\b/i,/\bportrait\b/i]},
    {name:'AI Prompt',slug:'ai-prompt',patterns:[/\bai\s*prompt\b/i,/\bprompt\b/i,/\bchatgpt\b/i,/\bmidjourney\b/i]},
    {name:'Motion Graphics',slug:'motion-graphics',patterns:[/\bmotion\s*graphics\b/i,/\btext\s*animation\b/i,/\blogo\s*reveal\b/i,/\bbeat\s*sync\b/i]},
    {name:'Invitation',slug:'invitation',patterns:[/\binvitation\b/i,/\bwedding\s*card\b/i,/\bbirthday\s*card\b/i,/\bhaldi\b/i]},
    {name:'Video FX',slug:'video-fx',patterns:[/\bvideo\b/i,/\bgreen\s*screen\b/i,/\btransition\b/i,/\breels?\b/i]},
    {name:'Background',slug:'background',patterns:[/\bbackground\b/i,/\bstudio\s*background\b/i,/\bnature\s*background\b/i]},
    {name:'Text Effect',slug:'text-effect',patterns:[/\btext\s*effect\b/i,/\bgold\s*text\b/i,/\bfire\s*text\b/i,/\bneon\s*text\b/i]}
  ];

  function uc2NormalizePromptText(text){return (text||'').replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();}
  function uc2WordCount(text){return uc2NormalizePromptText(text).split(/\s+/).filter(function(word){return word.length>1;}).length;}
  function uc2FirstMatch(list,text){
    for(var i=0;i<list.length;i++){
      for(var j=0;j<list[i].patterns.length;j++){
        if(list[i].patterns[j].test(text)){return {name:list[i].name,slug:list[i].slug};}
      }
    }
    return null;
  }

  function uc2QualityFromSignals(text,lower,words){
    if(!text){return 0;}
    var score=20;
    score+=Math.min(25,Math.floor(words*1.1));
    if(words>=20){score+=10;}
    if(words>=45){score+=10;}
    if(/negative\s*prompt|avoid|no\s+blur|without/i.test(lower)){score+=10;}
    if(/style|lighting|cinematic|realistic|ultra|detailed|composition|camera|lens|mood|color|background/i.test(lower)){score+=10;}
    if(/aspect\s*ratio|--ar|resolution|4k|8k|high\s*quality|sharp|depth/i.test(lower)){score+=8;}
    if(/how\s*to\s*use|steps?|instruction|paste|adjust|settings?/i.test(lower)){score+=7;}
    if(/[,.]/.test(text)&&words>=12){score+=5;}
    if(words<8){score-=15;}
    if(words>120){score-=5;}
    return Math.max(0,Math.min(100,score));
  }

  function uc2CompletenessFromSignals(text,lower,words){
    if(!text){return 0;}
    var score=0;
    if(words>=8){score+=15;}else if(words>=4){score+=8;}
    if(words>=24){score+=10;}else if(words>=14){score+=5;}
    if(/style|lighting|cinematic|realistic|detailed|color|texture|mood|atmosphere|background|environment/i.test(lower)){score+=15;}
    if(/camera|lens|angle|composition|portrait|wide|close\s*up|depth|focus|framing/i.test(lower)){score+=15;}
    if(/4k|8k|resolution|high\s*quality|sharp|ultra|hd|aspect\s*ratio|--ar|ratio/i.test(lower)){score+=15;}
    if(/negative\s*prompt|avoid|no\s+blur|without|exclude|low\s*quality|distorted/i.test(lower)){score+=15;}
    if(/how\s*to\s*use|steps?|instruction|paste|adjust|settings?|parameter|seed/i.test(lower)){score+=10;}
    if(/[,.]/.test(text)&&words>=10){score+=5;}
    return Math.max(0,Math.min(100,score));
  }

  function uc2AnalyzePrompt(promptText){
    var text=uc2NormalizePromptText(promptText);
    var lower=text.toLowerCase();
    var words=uc2WordCount(text);
    var tool=uc2FirstMatch(UC2_AI_TOOLS,text);
    var category=uc2FirstMatch(UC2_CATEGORIES,text);
    return {
      category:category?category.name:null,
      categorySlug:category?category.slug:null,
      tool:tool?tool.name:null,
      toolSlug:tool?tool.slug:null,
      quality:uc2QualityFromSignals(text,lower,words),
      completeness:uc2CompletenessFromSignals(text,lower,words),
      words:words
    };
  }

  function uc2ReadCardPromptIntelligence(card){
    var refs={};
    var parts=[];
    var nodes=card.querySelectorAll('.prompttextbox,.uc2-tool-container,.uc2-tool-text,.uc2-quality-score,.uc2-quality-badge,.uc2-completeness-value,.uc2-completeness-badge,.uc2-category-text,.universal-title,.universal-media,img[alt],a[title],[data-tool]');
    nodes.forEach(function(el){
      if(el.classList){
        if(el.classList.contains('prompttextbox')){refs.promptBox=el;}
        else if(el.classList.contains('uc2-tool-container')){refs.toolContainer=el;}
        else if(el.classList.contains('uc2-tool-text')){refs.toolText=el;}
        else if(el.classList.contains('uc2-quality-score')){refs.qualityScore=el;}
        else if(el.classList.contains('uc2-quality-badge')){refs.qualityBadge=el;}
        else if(el.classList.contains('uc2-completeness-value')){refs.completenessValue=el;}
        else if(el.classList.contains('uc2-completeness-badge')){refs.completenessBadge=el;}
        if(el.classList.contains('uc2-category-text')||el.classList.contains('universal-title')||el.classList.contains('universal-media')){parts.push(el.textContent||'');}
      }
      parts.push(el.getAttribute?((el.getAttribute('alt')||'')+' '+(el.getAttribute('title')||'')+' '+(el.getAttribute('data-tool')||'')):'');
    });
    var promptText=refs.promptBox?((refs.promptBox.innerText||refs.promptBox.textContent||'').trim()):'';
    var analysisText=(promptText+' '+parts.join(' ')).trim();
    if(card._uc2AnalysisText===analysisText&&card._uc2Intelligence){return {refs:refs,result:card._uc2Intelligence,promptText:promptText,cached:true};}
    var result=uc2AnalyzePrompt(analysisText);
    card._uc2AnalysisText=analysisText;
    card._uc2PromptText=promptText;
    card._uc2Intelligence=result;
    return {refs:refs,result:result,promptText:promptText,cached:false};
  }

  function uc2ApplyPromptIntelligence(){
    document.querySelectorAll('.universal-card').forEach(function(card){
      var data=uc2ReadCardPromptIntelligence(card);
      var refs=data.refs;
      var result=data.result;
      card._uc2Category=result.category;
      if(refs.toolContainer&&refs.toolText&&result.tool){
        refs.toolText.textContent=result.tool;
        refs.toolContainer.setAttribute('data-tool',result.toolSlug||'');
        refs.toolContainer.classList.add('is-detected');
      }
      if(refs.qualityScore&&refs.qualityBadge){
        refs.qualityScore.textContent=result.quality+'/100';
        refs.qualityBadge.setAttribute('data-uc2-quality',String(result.quality));
      }
      if(refs.completenessValue&&refs.completenessBadge){
        refs.completenessValue.textContent=result.completeness+'%';
        refs.completenessBadge.setAttribute('data-uc2-completeness',String(result.completeness));
      }
    });
  }

  function uc2DetectAiTool(text){
    var result=uc2AnalyzePrompt(text);
    return result.tool?{name:result.tool,slug:result.toolSlug}:null;
  }
  function uc2PromptQualityScore(text){return uc2AnalyzePrompt(text).quality;}
  function uc2PromptCompleteness(text){return uc2AnalyzePrompt(text).completeness;}

  window.uc2AnalyzePrompt=uc2AnalyzePrompt;
  window.uc2ApplyPromptIntelligence=uc2ApplyPromptIntelligence;
  window.uc2ReadCardPromptIntelligence=uc2ReadCardPromptIntelligence;
  window.uc2DetectAiTool=uc2DetectAiTool;
  window.uc2PromptQualityScore=uc2PromptQualityScore;
  window.uc2PromptCompleteness=uc2PromptCompleteness;
  window.uc2ApplyToolBadges=uc2ApplyPromptIntelligence;
  window.uc2ApplyQualityScores=uc2ApplyPromptIntelligence;
  window.uc2ApplyCompletenessMeters=uc2ApplyPromptIntelligence;

  function uc2SchedulePromptIntelligence(){
    window.setTimeout(uc2ApplyPromptIntelligence,0);
    window.setTimeout(uc2ApplyPromptIntelligence,300);
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',uc2SchedulePromptIntelligence);
  }else{
    uc2SchedulePromptIntelligence();
  }
})();
