(function(){
  var UC2_EXPAND_LABEL='Show more';
  var UC2_COLLAPSE_LABEL='Show less';
  var UC2_OVERFLOW_TOLERANCE=2;

  function uc2PromptHasOverflow(promptBox){
    if(!promptBox){return false;}
    var previousExpanded=promptBox.classList.contains('uc2-expanded');
    if(previousExpanded){promptBox.classList.remove('uc2-expanded');}
    var hasOverflow=(promptBox.scrollHeight-promptBox.clientHeight)>UC2_OVERFLOW_TOLERANCE;
    if(previousExpanded){promptBox.classList.add('uc2-expanded');}
    return hasOverflow;
  }

  function uc2SetExpanded(card,promptBox,button,expanded){
    card.classList.toggle('uc2-expanded',expanded);
    promptBox.classList.toggle('uc2-expanded',expanded);
    button.textContent=expanded?UC2_COLLAPSE_LABEL:UC2_EXPAND_LABEL;
  }

  function uc2PreparePromptCard(card){
    var promptBox=card.querySelector('.prompttextbox');
    var button=card.querySelector('.uc2-expand-toggle');
    if(!promptBox||!button){return;}
    var hasOverflow=uc2PromptHasOverflow(promptBox);
    promptBox.classList.toggle('uc2-collapsible',hasOverflow);
    button.classList.toggle('is-visible',hasOverflow);
    if(!hasOverflow){
      uc2SetExpanded(card,promptBox,button,false);
      return;
    }
    if(button.getAttribute('data-uc2-bound')!=='true'){
      button.setAttribute('data-uc2-bound','true');
      button.addEventListener('click',function(){
        uc2SetExpanded(card,promptBox,button,!promptBox.classList.contains('uc2-expanded'));
      });
    }
    button.textContent=promptBox.classList.contains('uc2-expanded')?UC2_COLLAPSE_LABEL:UC2_EXPAND_LABEL;
  }

  function uc2InitPromptExpand(){
    document.querySelectorAll('.universal-card').forEach(uc2PreparePromptCard);
  }

  window.uc2PromptHasOverflow=uc2PromptHasOverflow;
  window.uc2InitPromptExpand=uc2InitPromptExpand;

  function uc2SchedulePromptExpand(){
    window.setTimeout(uc2InitPromptExpand,0);
    window.setTimeout(uc2InitPromptExpand,250);
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',uc2SchedulePromptExpand);
  }else{
    uc2SchedulePromptExpand();
  }
  window.addEventListener('resize',function(){window.clearTimeout(window._uc2PromptExpandResize);window._uc2PromptExpandResize=window.setTimeout(uc2InitPromptExpand,160);});
})();
