(function(){
  function uc2GetModal(){return document.querySelector('.uc2-modal');}
  function uc2Esc(t){return String(t||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
  function uc2Plain(html){var d=document.createElement('div');d.innerHTML=html||'';return (d.textContent||'').replace(/\u00a0/g,' ').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();}
  function uc2FileName(url){var u=(url||'').split('?')[0].split('#')[0];try{u=decodeURIComponent(u);}catch(e){}var parts=u.split('/');return (parts[parts.length-1]||'').toLowerCase();}
  function uc2IsCoverFile(url){var f=uc2FileName(url);if(!f)return false;return f.indexOf('_cover')!==-1||f.indexOf('-cover')!==-1||f.indexOf('cover')!==-1||f.indexOf('_thumb')!==-1||f.indexOf('-thumb')!==-1||f.indexOf('thumb')!==-1;}
  function uc2FindCover(card){
    if(!card)return '';
    if(card._parsedCover)return card._parsedCover;
    var imgs=card.querySelectorAll('.universal-media img, .universal-image-box img, img');
    for(var i=0;i<imgs.length;i++){
      var src=imgs[i].currentSrc||imgs[i].src||imgs[i].getAttribute('data-src')||imgs[i].getAttribute('data-lazy-src')||'';
      if(src&&src.indexOf('data:')!==0&&uc2IsCoverFile(src))return src;
    }
    return '';
  }
  function uc2CloseModal(){
    var modal=uc2GetModal();
    if(!modal){return;}
    modal.setAttribute('data-open','false');
    modal.removeAttribute('data-has-thumb');
    var body=modal.querySelector('.uc2-modal-body');
    if(body){body.innerHTML='';}
    var titleNode=modal.querySelector('.uc2-modal-title');
    if(titleNode){titleNode.textContent='';titleNode.classList.remove('is-on');}
    var thumb=modal.querySelector('.uc2-modal-thumb');
    if(thumb){thumb.removeAttribute('src');thumb.removeAttribute('srcset');thumb.alt='Prompt thumbnail';}
  }
  function uc2OpenPromptModal(button){
    var modal=uc2GetModal();
    if(!modal||!button){return;}
    var card=button.closest('.universal-card');
    if(!card){
      var mm=button.closest('.uc2-more-menu');
      card=mm&&mm._card?mm._card:null;
    }
    var promptBox=card?card.querySelector('.prompttextbox'):null;
    var modalBody=modal.querySelector('.uc2-modal-body');
    if(!promptBox||!modalBody){return;}
    var titleEl=card.querySelector('.universal-title');
    var title=(titleEl?(titleEl.textContent||''):'').replace(/\s+/g,' ').trim();
    var intro=card._parsedIntro||'';
    var tools=card._parsedTools||'';
    var titleNode=modal.querySelector('.uc2-modal-title');
    if(titleNode){
      titleNode.textContent=title||'';
      if(title){titleNode.classList.add('is-on');}else{titleNode.classList.remove('is-on');}
    }
    var html='';
    if(intro){html+='<p class="uc2-modal-intro">'+uc2Esc(intro)+'</p>';}
    html+='<div class="uc2-modal-prompt">'+promptBox.innerHTML+'</div>';
    if(tools){
      var chips=tools.split(/[\n,\/|]+/).map(function(t){return t.replace(/^[-*•]\s*/,'').trim();}).filter(Boolean);
      if(chips.length){
        html+='<div class="uc2-modal-sec"><span class="uc2-modal-sec-label">Compatible AI Tools</span><div class="uc2-modal-tools">';
        chips.forEach(function(t){html+='<span class="uc2-modal-tool">'+uc2Esc(t)+'</span>';});
        html+='</div></div>';
      }
    }
    modalBody.innerHTML=html;
    var thumb=modal.querySelector('.uc2-modal-thumb');
    var thumbSrc=uc2FindCover(card);
    if(thumb){
      if(thumbSrc){thumb.src=thumbSrc;thumb.alt=title||'Prompt thumbnail';modal.setAttribute('data-has-thumb','true');}
      else{thumb.removeAttribute('src');modal.removeAttribute('data-has-thumb');}
    }
    modal.setAttribute('data-open','true');
    var closeButton=modal.querySelector('.uc2-modal-close');
    if(closeButton){closeButton.focus();}
  }
  document.addEventListener('click',function(event){
    var viewButton=event.target.closest('[data-uc2-view-prompt]');
    if(viewButton){
      event.preventDefault();
      uc2OpenPromptModal(viewButton);
      return;
    }
    if(event.target.closest('.uc2-modal-close')){
      event.preventDefault();
      uc2CloseModal();
      return;
    }
    if(event.target.classList&&event.target.classList.contains('uc2-modal-overlay')){
      uc2CloseModal();
    }
  });
  document.addEventListener('keydown',function(event){
    if(event.key==='Escape'){
      uc2CloseModal();
    }
  });
  document.addEventListener('contextmenu',function(event){
    if(event.target&&event.target.closest&&event.target.closest('.uc2-modal-body')){
      event.preventDefault();
    }
  });
  document.addEventListener('copy',function(event){
    if(event.target&&event.target.closest&&event.target.closest('.uc2-modal-body')){
      event.preventDefault();
    }
  });
  document.addEventListener('cut',function(event){
    if(event.target&&event.target.closest&&event.target.closest('.uc2-modal-body')){
      event.preventDefault();
    }
  });
  document.addEventListener('selectstart',function(event){
    if(event.target&&event.target.closest&&event.target.closest('.uc2-modal-body')){
      event.preventDefault();
    }
  });
  window.uc2OpenPromptModal=uc2OpenPromptModal;
  window.uc2CloseModal=uc2CloseModal;
})();
