(function(){
  var UC2_RELATED_LIMIT=3;
  var UC2_TITLE_STOPWORDS={a:1,an:1,the:1,and:1,or:1,for:1,to:1,with:1,of:1,in:1,on:1,by:1,ai:1,prompt:1,prompts:1,image:1,photo:1,video:1};

  function uc2Text(el){return el?(el.textContent||'').replace(/\s+/g,' ').trim():'';}
  function uc2TokenSet(text){
    var set={};
    (text||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).forEach(function(token){
      if(token.length>2&&!UC2_TITLE_STOPWORDS[token]){set[token]=true;}
    });
    return set;
  }
  function uc2SharedTokenCount(a,b){
    var count=0;
    Object.keys(a||{}).forEach(function(token){if(b&&b[token]){count++;}});
    return count;
  }
  function uc2GetCardAnalysis(card,text){
    if(card._uc2Intelligence){return card._uc2Intelligence;}
    if(window.uc2ReadCardPromptIntelligence){return window.uc2ReadCardPromptIntelligence(card).result;}
    return window.uc2AnalyzePrompt?window.uc2AnalyzePrompt(text||''):{category:null,tool:null,quality:0,completeness:0};
  }
  function uc2BuildRelatedIndex(){
    var cards=[];
    document.querySelectorAll('.universal-card').forEach(function(card,index){
      var nodes=card.querySelectorAll('.universal-title,.uc2-category-text,.prompttextbox,.uc2-related-section,.uc2-related-list');
      var refs={};
      nodes.forEach(function(el){
        if(el.classList.contains('universal-title')){refs.title=el;}
        else if(el.classList.contains('uc2-category-text')){refs.category=el;}
        else if(el.classList.contains('prompttextbox')){refs.prompt=el;}
        else if(el.classList.contains('uc2-related-section')){refs.section=el;}
        else if(el.classList.contains('uc2-related-list')){refs.list=el;}
      });
      var title=uc2Text(refs.title)||('Prompt '+(index+1));
      var promptText=card._uc2PromptText||uc2Text(refs.prompt);
      var labelText=uc2Text(refs.category);
      var analysis=uc2GetCardAnalysis(card,(promptText+' '+title+' '+labelText));
      cards.push({
        card:card,
        index:index,
        title:title,
        url:card.getAttribute('data-url')||'',
        label:labelText,
        labels:uc2TokenSet(labelText),
        titleTokens:uc2TokenSet(title),
        analysis:analysis,
        refs:refs
      });
    });
    return cards;
  }
  function uc2RelatedScore(current,candidate){
    if(!current||!candidate||current.card===candidate.card){return 0;}
    var score=0;
    if(current.analysis && candidate.analysis && current.analysis.category && candidate.analysis.category && current.analysis.category===candidate.analysis.category){score+=50;}
    if(current.analysis && candidate.analysis && current.analysis.tool && candidate.analysis.tool && current.analysis.tool===candidate.analysis.tool){score+=30;}
    if(uc2SharedTokenCount(current.labels,candidate.labels)>0){score+=20;}
    if(uc2SharedTokenCount(current.titleTokens,candidate.titleTokens)>0){score+=10;}
    return score;
  }
  function uc2FindRelatedPrompts(currentCard,allCards){
    allCards=allCards||uc2BuildRelatedIndex();
    var current=null;
    for(var i=0;i<allCards.length;i++){if(allCards[i].card===currentCard){current=allCards[i];break;}}
    if(!current){return [];}
    var seen={};
    return allCards.map(function(candidate){
      return {item:candidate,score:uc2RelatedScore(current,candidate)};
    }).filter(function(entry){
      if(!entry.score||entry.item.card===current.card){return false;}
      var key=(entry.item.url||entry.item.title||entry.item.index).toLowerCase();
      if(seen[key]){return false;}
      seen[key]=true;
      return true;
    }).sort(function(a,b){
      if(b.score!==a.score){return b.score-a.score;}
      return a.item.index-b.item.index;
    }).slice(0,UC2_RELATED_LIMIT).map(function(entry){
      return {title:entry.item.title,url:entry.item.url,score:entry.score,category:entry.item.analysis?entry.item.analysis.category:null,tool:entry.item.analysis?entry.item.analysis.tool:null};
    });
  }
  function uc2RenderRelatedList(data,related){
    var section=data.refs.section;
    var list=data.refs.list;
    if(!section||!list){return;}
    list.innerHTML='';
    if(!related.length){section.setAttribute('data-uc2-related','false');return;}
    related.forEach(function(item){
      var link=document.createElement('a');
      link.className='uc2-related-item';
      link.href=item.url||'#';
      link.textContent=item.title;
      list.appendChild(link);
    });
    section.setAttribute('data-uc2-related','true');
  }
  function uc2ApplyRelatedPrompts(){
    return; /* MGS HIDE — Related Prompts section disabled: keep cards clean */
  }
  window.uc2FindRelatedPrompts=uc2FindRelatedPrompts;
  window.uc2ApplyRelatedPrompts=uc2ApplyRelatedPrompts;
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){window.setTimeout(uc2ApplyRelatedPrompts,320);});
  }else{
    window.setTimeout(uc2ApplyRelatedPrompts,320);
  }
})();
