(function(){
  var UC2_ANALYTICS_PREFIX='uc2Analytics:';
  var UC2_EVENT_LIMIT=80;
  var UC2_EVENT_WEIGHTS={view:1,copy:5,save:10,open:4,related:3};

  function uc2ClampScore(value){return Math.max(0,Math.min(100,Math.round(value||0)));}
  function uc2Now(){return Date.now?Date.now():(new Date()).getTime();}
  function uc2CardKey(card){
    if(!card){return 'unknown';}
    return card.getAttribute('data-post-id')||card.getAttribute('data-url')||('card-'+Array.prototype.indexOf.call(document.querySelectorAll('.universal-card'),card));
  }
  function uc2StorageKey(cardOrKey){
    var key=(typeof cardOrKey==='string')?cardOrKey:uc2CardKey(cardOrKey);
    return UC2_ANALYTICS_PREFIX+key;
  }
  function uc2DefaultAnalytics(){
    return {cardViewCount:0,cardCopyCount:0,cardSaveCount:0,cardOpenCount:0,cardRelatedClickCount:0,events:[]};
  }
  function uc2GetAnalytics(cardOrKey){
    var storageKey=uc2StorageKey(cardOrKey);
    try{
      var parsed=JSON.parse(localStorage.getItem(storageKey)||'null')||uc2DefaultAnalytics();
      parsed.cardViewCount=parsed.cardViewCount||0;
      parsed.cardCopyCount=parsed.cardCopyCount||0;
      parsed.cardSaveCount=parsed.cardSaveCount||0;
      parsed.cardOpenCount=parsed.cardOpenCount||0;
      parsed.cardRelatedClickCount=parsed.cardRelatedClickCount||0;
      parsed.events=Array.isArray(parsed.events)?parsed.events:[];
      return parsed;
    }catch(e){return uc2DefaultAnalytics();}
  }
  function uc2SaveAnalytics(cardOrKey,data){
    try{localStorage.setItem(uc2StorageKey(cardOrKey),JSON.stringify(data));}catch(e){}
    return data;
  }
  function uc2RecordEvent(cardOrKey,type){
    var data=uc2GetAnalytics(cardOrKey);
    if(type==='view'){data.cardViewCount++;}
    else if(type==='copy'){data.cardCopyCount++;}
    else if(type==='save'){data.cardSaveCount++;}
    else if(type==='open'){data.cardOpenCount++;}
    else if(type==='related'){data.cardRelatedClickCount++;}
    data.events.push({type:type,t:uc2Now()});
    if(data.events.length>UC2_EVENT_LIMIT){data.events=data.events.slice(data.events.length-UC2_EVENT_LIMIT);}
    return uc2SaveAnalytics(cardOrKey,data);
  }
  function uc2CalculatePopularity(data){
    data=data||uc2DefaultAnalytics();
    return uc2ClampScore((data.cardViewCount||0)*1+(data.cardCopyCount||0)*5+(data.cardSaveCount||0)*10+(data.cardOpenCount||0)*4+(data.cardRelatedClickCount||0)*3);
  }
  function uc2CalculateTrending(data){
    data=data||uc2DefaultAnalytics();
    var now=uc2Now();
    var raw=0;
    (data.events||[]).forEach(function(event){
      var ageHours=Math.max(0,(now-(event.t||now))/36e5);
      var decay=1/(1+(ageHours/24));
      raw+=(UC2_EVENT_WEIGHTS[event.type]||1)*decay;
    });
    return uc2ClampScore(raw*4);
  }
  function uc2CalculateEngagement(data){
    data=data||uc2DefaultAnalytics();
    var views=data.cardViewCount||0;
    var actions=(data.cardCopyCount||0)+(data.cardSaveCount||0)+(data.cardOpenCount||0);
    var weighted=(data.cardCopyCount||0)*6+(data.cardSaveCount||0)*12+(data.cardOpenCount||0)*5;
    var ratio=views?Math.min(40,(actions/views)*40):(actions?30:0);
    return uc2ClampScore(weighted+ratio);
  }
  function uc2PopularityLabel(score){
    if(score>=90){return 'Viral';}
    if(score>=75){return 'Trending';}
    if(score>=60){return 'Popular';}
    if(score>=40){return 'Rising';}
    return 'New';
  }
  function uc2PopularityIcon(label){
    if(label==='Viral'){return "<svg fill='none' height='14' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.8' viewBox='0 0 24 24' width='14'><path d='M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09z'/><path d='m12 15-3-3a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.35 22.35 0 0 1-4 2z'/><path d='M9 12H4s.55-3.03 2-4c1.62-1.08 5 0 5 0'/><path d='M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5'/></svg>";}
    if(label==='Trending'){return "<svg fill='none' height='14' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.8' viewBox='0 0 24 24' width='14'><path d='M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z'/></svg>";}
    if(label==='Popular'){return "<svg fill='none' height='14' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.8' viewBox='0 0 24 24' width='14'><path d='M12 2l2.9 6.3 6.9.7-5.1 4.7 1.4 6.8L12 17.8 5.9 20.5l1.4-6.8L2.2 9l6.9-.7Z'/></svg>";}
    if(label==='Rising'){return "<svg fill='none' height='14' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.8' viewBox='0 0 24 24' width='14'><polyline points='22 7 13.5 15.5 8.5 10.5 2 17'/><polyline points='16 7 22 7 22 13'/></svg>";}
    return "<svg fill='none' height='14' stroke='currentColor' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.8' viewBox='0 0 24 24' width='14'><path d='m12 3-1.9 5.8a2 2 0 0 1-1.3 1.3L3 12l5.8 1.9a2 2 0 0 1 1.3 1.3L12 21l1.9-5.8a2 2 0 0 1 1.3-1.3L21 12l-5.8-1.9a2 2 0 0 1-1.3-1.3Z'/></svg>";
  }
  function uc2UpdatePopularityBadge(card,data){
    var badge=card?card.querySelector('.uc2-popularity-badge'):null;
    if(!badge){return;}
    data=data||uc2GetAnalytics(card);
    var popularity=uc2CalculatePopularity(data);
    var trending=uc2CalculateTrending(data);
    var engagement=uc2CalculateEngagement(data);
    var displayScore=Math.max(popularity,trending,engagement);
    var label=uc2PopularityLabel(displayScore);
    var labelEl=badge.querySelector('.uc2-popularity-label');
    var scoreEl=badge.querySelector('.uc2-popularity-score');
    if(labelEl){labelEl.textContent=label;}
    if(scoreEl){scoreEl.textContent=String(displayScore);}
    var iconEl=badge.querySelector('.uc2-popularity-icon');if(iconEl){iconEl.innerHTML=uc2PopularityIcon(label);}
    badge.setAttribute('data-uc2-popularity',String(displayScore));
    badge.setAttribute('data-uc2-trending',String(trending));
    badge.setAttribute('data-uc2-engagement',String(engagement));
  }
  function uc2TrackView(card){var data=uc2RecordEvent(card,'view');uc2UpdatePopularityBadge(card,data);return data;}
  function uc2TrackCopy(card){var data=uc2RecordEvent(card,'copy');uc2UpdatePopularityBadge(card,data);return data;}
  function uc2TrackSave(card){var data=uc2RecordEvent(card,'save');uc2UpdatePopularityBadge(card,data);return data;}
  function uc2TrackOpen(card){var data=uc2RecordEvent(card,'open');uc2UpdatePopularityBadge(card,data);return data;}
  function uc2TrackRelatedClick(card){var data=uc2RecordEvent(card,'related');uc2UpdatePopularityBadge(card,data);return data;}
  function uc2ApplyPopularityBadges(){
    document.querySelectorAll('.universal-card').forEach(function(card){
      if(card.getAttribute('data-uc2-view-tracked')!=='true'){
        card.setAttribute('data-uc2-view-tracked','true');
        uc2TrackView(card);
      }else{
        uc2UpdatePopularityBadge(card,uc2GetAnalytics(card));
      }
    });
  }
  function uc2BindAnalytics(){
    if(window._uc2AnalyticsBound){return;}
    window._uc2AnalyticsBound=true;
    document.addEventListener('click',function(event){
      var related=event.target.closest('.uc2-related-item');
      if(related){uc2TrackRelatedClick(related.closest('.universal-card'));return;}
      var copy=event.target.closest('.copy-prompt-btn,.copy-option');
      if(copy){uc2TrackCopy(copy.closest('.universal-card'));return;}
      var save=event.target.closest('.save-btn');
      if(save){uc2TrackSave(save.closest('.universal-card'));return;}
      var open=event.target.closest('[data-uc2-view-prompt]');
      if(open){uc2TrackOpen(open.closest('.universal-card'));}
    });
  }
  window.uc2TrackView=uc2TrackView;
  window.uc2TrackCopy=uc2TrackCopy;
  window.uc2TrackSave=uc2TrackSave;
  window.uc2TrackOpen=uc2TrackOpen;
  window.uc2TrackRelatedClick=uc2TrackRelatedClick;
  window.uc2CalculatePopularity=uc2CalculatePopularity;
  window.uc2CalculateTrending=uc2CalculateTrending;
  window.uc2CalculateEngagement=uc2CalculateEngagement;
  window.uc2ApplyPopularityBadges=uc2ApplyPopularityBadges;
  function uc2ScheduleAnalytics(){uc2BindAnalytics();window.setTimeout(uc2ApplyPopularityBadges,340);}
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',uc2ScheduleAnalytics);
  }else{
    uc2ScheduleAnalytics();
  }
})();
