(function(){
  var UC2_FEED_LIMIT=10;
  var UC2_ANALYTICS_PREFIX='uc2Analytics:';

  function uc2FeedCardKey(card){return card.getAttribute('data-post-id')||card.getAttribute('data-url')||'';}
  function uc2FeedStorageKey(card){return UC2_ANALYTICS_PREFIX+uc2FeedCardKey(card);}
  function uc2FeedDefaultAnalytics(){return {cardViewCount:0,cardCopyCount:0,cardSaveCount:0,cardOpenCount:0,cardRelatedClickCount:0,events:[]};}
  function uc2FeedAnalytics(card){
    try{
      var data=JSON.parse(localStorage.getItem(uc2FeedStorageKey(card))||'null')||uc2FeedDefaultAnalytics();
      data.cardViewCount=data.cardViewCount||0;
      data.cardCopyCount=data.cardCopyCount||0;
      data.cardSaveCount=data.cardSaveCount||0;
      data.cardOpenCount=data.cardOpenCount||0;
      data.cardRelatedClickCount=data.cardRelatedClickCount||0;
      data.events=Array.isArray(data.events)?data.events:[];
      return data;
    }catch(e){return uc2FeedDefaultAnalytics();}
  }
  function uc2FeedText(el){return el?(el.textContent||'').replace(/\s+/g,' ').trim():'';}
  function uc2BuildFeedIndex(){
    var items=[];
    document.querySelectorAll('.universal-card').forEach(function(card,index){
      var titleEl=card.querySelector('.universal-title');
      var promptEl=card.querySelector('.prompttextbox');
      var title=uc2FeedText(titleEl)||('Prompt '+(index+1));
      var prompt=card._uc2PromptText||uc2FeedText(promptEl);
      var analysis=card._uc2Intelligence||(window.uc2ReadCardPromptIntelligence?window.uc2ReadCardPromptIntelligence(card).result:(window.uc2AnalyzePrompt?window.uc2AnalyzePrompt(prompt+' '+title):{}));
      var analytics=uc2FeedAnalytics(card);
      var popularity=window.uc2CalculatePopularity?window.uc2CalculatePopularity(analytics):0;
      var trending=window.uc2CalculateTrending?window.uc2CalculateTrending(analytics):0;
      var engagement=window.uc2CalculateEngagement?window.uc2CalculateEngagement(analytics):0;
      items.push({card:card,index:index,title:title,url:card.getAttribute('data-url')||'#',analysis:analysis||{},analytics:analytics,popularity:popularity,trending:trending,engagement:engagement});
    });
    return items;
  }
  function uc2UniqueFeedItems(items,scoreKey,filterFn){
    var seen={};
    return (items||[]).filter(function(item){return filterFn?filterFn(item):true;}).sort(function(a,b){
      var av=typeof scoreKey==='function'?scoreKey(a):(a[scoreKey]||0);
      var bv=typeof scoreKey==='function'?scoreKey(b):(b[scoreKey]||0);
      if(bv!==av){return bv-av;}
      return a.index-b.index;
    }).filter(function(item){
      var key=(item.url||item.title||item.index).toLowerCase();
      if(seen[key]){return false;}
      seen[key]=true;
      return true;
    }).slice(0,UC2_FEED_LIMIT);
  }
  function uc2BuildTrendingFeed(items){return uc2UniqueFeedItems(items,'trending',function(item){return item.trending>0;});}
  function uc2BuildMostSavedFeed(items){return uc2UniqueFeedItems(items,function(item){return item.analytics.cardSaveCount||0;},function(item){return (item.analytics.cardSaveCount||0)>0;});}
  function uc2BuildMostCopiedFeed(items){return uc2UniqueFeedItems(items,function(item){return item.analytics.cardCopyCount||0;},function(item){return (item.analytics.cardCopyCount||0)>0;});}
  function uc2BuildViralFeed(items){return uc2UniqueFeedItems(items,'popularity',function(item){return item.popularity>=90;});}
  function uc2BuildAiRecommendedFeed(items){
    return uc2UniqueFeedItems(items,function(item){
      var quality=item.analysis.quality||0;
      var completeness=item.analysis.completeness||0;
      return (quality*.30)+(completeness*.20)+(item.popularity*.30)+(item.trending*.20);
    },function(item){return item.analysis && ((item.analysis.quality||0)>0 || (item.analysis.completeness||0)>0);});
  }
  function uc2FeedBadgeLabel(type){
    var map={trending:'🔥 Trending',saved:'⭐ Most Saved',copied:'📋 Most Copied',viral:'⚡ Viral',recommended:'🤖 AI Pick'};
    return map[type]||'';
  }
  /* Thumbnail: REUSES the same cover/thumb detection already used across the
     theme. card._parsedCover is computed by mgsInitCardCore; the fallback below
     mirrors the existing uc2FindCover / mgsCoverSrcFrom scan (cover/thumb files). */
  function uc2FeedThumbSrc(item){
    var card=item.card;
    if(card && typeof card._parsedCover==='string' && card._parsedCover){return card._parsedCover;}
    if(card){
      var imgs=card.querySelectorAll('.universal-media img, .universal-image-box img, img');
      for(var i=0;i<imgs.length;i++){
        var src=imgs[i].currentSrc||imgs[i].src||imgs[i].getAttribute('data-src')||imgs[i].getAttribute('data-lazy-src')||'';
        if(src && src.indexOf('data:')!==0){
          var file=(src.split('?')[0].split('#')[0].split('/').pop()||'').toLowerCase();
          if(file.indexOf('cover')!==-1||file.indexOf('thumb')!==-1){return src;}
        }
      }
    }
    return '';
  }
  function uc2RenderFeed(type,items){
    var section=document.querySelector('.uc2-feed-section[data-uc2-feed-type="'+type+'"]');
    if(!section){return;}
    var carousel=section.querySelector('.uc2-feed-carousel');
    if(!carousel){return;}
    carousel.innerHTML='';
    if(!items.length){section.setAttribute('data-uc2-feed','empty');return;} /* PHASE 3A */
    var badge=uc2FeedBadgeLabel(type);

    /* Inner sliding track */
    var track=document.createElement('div');
    track.className='uc2-feed-track';

    items.forEach(function(item){
      var link=document.createElement('a');
      link.className='uc2-feed-item';
      link.href=item.url||'#';
      link.title=item.title;

      var thumb=document.createElement('span');
      thumb.className='uc2-feed-thumb';
      var src=uc2FeedThumbSrc(item);
      if(src){
        var img=document.createElement('img');
        img.src=src;
        img.alt=item.title;
        img.loading='lazy';
        img.decoding='async';
        thumb.appendChild(img);
      }else{
        thumb.className+=' uc2-feed-thumb--empty';
        thumb.textContent='🖼️';
      }
      if(badge){
        var b=document.createElement('span');
        b.className='uc2-feed-badge';
        b.textContent=badge;
        thumb.appendChild(b);
      }

      var t=document.createElement('span');
      t.className='uc2-feed-item-title';
      t.textContent=item.title;

      link.appendChild(thumb);
      link.appendChild(t);
      track.appendChild(link);
    });

    /* Prev button (before track) */
    var prev=document.createElement('button');
    prev.type='button';
    prev.className='uc2-feed-nav uc2-feed-nav--prev';
    prev.setAttribute('aria-label','Previous');
    prev.setAttribute('disabled','disabled');
    prev.textContent='‹';
    carousel.appendChild(prev);

    /* Inner track */
    carousel.appendChild(track);

    /* Next button (after track) */
    var next=document.createElement('button');
    next.type='button';
    next.className='uc2-feed-nav uc2-feed-nav--next';
    next.setAttribute('aria-label','Next');
    next.textContent='›';
    carousel.appendChild(next);

    section.setAttribute('data-uc2-feed','true');
  }

  function uc2BuildSmartHomeFeed(){
    if(window._uc2SmartHomeFeedBuilt){return;}
    window._uc2SmartHomeFeedBuilt=true;
    var items=uc2BuildFeedIndex();
    uc2RenderFeed('trending',uc2BuildTrendingFeed(items));
    uc2RenderFeed('saved',uc2BuildMostSavedFeed(items));
    uc2RenderFeed('copied',uc2BuildMostCopiedFeed(items));
    uc2RenderFeed('viral',uc2BuildViralFeed(items));
    uc2RenderFeed('recommended',uc2BuildAiRecommendedFeed(items));
  }
  window.uc2BuildTrendingFeed=uc2BuildTrendingFeed;
  window.uc2BuildMostSavedFeed=uc2BuildMostSavedFeed;
  window.uc2BuildMostCopiedFeed=uc2BuildMostCopiedFeed;
  window.uc2BuildViralFeed=uc2BuildViralFeed;
  window.uc2BuildAiRecommendedFeed=uc2BuildAiRecommendedFeed;
  window.uc2BuildSmartHomeFeed=uc2BuildSmartHomeFeed;
  /* PHASE 3A: build at DOM-ready with no 460ms delay. Listeners registered
     earlier in the template (universal-card init) fire first, so all card
     data the feed needs is already available. */
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){uc2BuildSmartHomeFeed();});
  }else{
    uc2BuildSmartHomeFeed();
  }
})();
