(function(){
  /* Page-based slider for the feed carousels.
     Runs after uc2RenderFeed() has created the .uc2-feed-track elements. */
  function initFeedSliders(){
    document.querySelectorAll('.uc2-feed-section').forEach(function(section){
      var track=section.querySelector('.uc2-feed-track');
      if(!track){return;}
      var cards=track.querySelectorAll('.uc2-feed-item');
      var prevBtn=section.querySelector('.uc2-feed-nav--prev');
      var nextBtn=section.querySelector('.uc2-feed-nav--next');
      if(!cards.length){return;}

      var visibleCount=2;
      if(cards.length<=visibleCount){
        section.querySelectorAll('.uc2-feed-nav').forEach(function(b){b.style.display='none';});
        return;
      }

      var currentPage=0;
      var totalPages=Math.ceil(cards.length/visibleCount);

      function getSlideOffset(){
        if(!cards[0]){return 0;}
        var cardW=cards[0].offsetWidth;
        var gap=12;
        return (cardW+gap)*visibleCount;
      }

      function updateSlide(){
        var offset=currentPage*getSlideOffset();
        /* clamp so the last page never overshoots (odd card counts) */
        var maxShift=Math.max(0,track.scrollWidth-track.clientWidth);
        if(offset>maxShift){offset=maxShift;}
        track.style.transform='translateX(-'+offset+'px)';
        if(prevBtn){prevBtn.disabled=(currentPage===0);}
        if(nextBtn){nextBtn.disabled=(currentPage>=totalPages-1);}
      }

      if(prevBtn){
        prevBtn.addEventListener('click',function(){if(currentPage>0){currentPage--;updateSlide();}});
      }
      if(nextBtn){
        nextBtn.addEventListener('click',function(){if(currentPage<totalPages-1){currentPage++;updateSlide();}});
      }

      updateSlide();

      /* Recalculate offsets on viewport resize (fluid card width) */
      window.addEventListener('resize',function(){updateSlide();});
    });
  }

  /* Run after feeds are populated */
  var feedCheckInterval=setInterval(function(){
    var tracks=document.querySelectorAll('.uc2-feed-track');
    if(tracks.length>0){
      clearInterval(feedCheckInterval);
      setTimeout(initFeedSliders,500);
    }
  },300);
})();
