(function(){
  var UC2_SEARCH_INDEX=null;
  function uc2SearchText(el){return el?(el.textContent||'').replace(/\s+/g,' ').trim():'';}
  function uc2SearchNum(text){var n=parseInt(String(text||'').replace(/[^0-9]/g,''),10);return isNaN(n)?0:n;}
  function uc2SearchSavedIds(){
    try{
      var ids=[];
      var pRaw=localStorage.getItem('promptCollections');
      /* PHASE 2B: uc2Collections read removed - legacy data migrated into promptCollections at page load */
      if(pRaw){
        var pData=JSON.parse(pRaw);
        if(pData&&Array.isArray(pData.collections)){
          pData.collections.forEach(function(c){
            (c.prompts||[]).forEach(function(item){
              var id=(typeof item==='object'&&item!==null)?String(item.id||''):String(item);
              if(id&&ids.indexOf(id)===-1)ids.push(id);
            });
          });
        }
      }
      return ids;
    }catch(e){return [];}
  }
  function uc2SearchAnalytics(card){
    var data=null;
    if(window.uc2CalculatePopularity||window.uc2CalculateTrending){
      try{data=JSON.parse(localStorage.getItem('uc2Analytics:'+(card.getAttribute('data-post-id')||card.getAttribute('data-url')||''))||'null');}catch(e){data=null;}
    }
    data=data||{cardViewCount:0,cardCopyCount:0,cardSaveCount:0,cardOpenCount:0,cardRelatedClickCount:0,events:[]};
    return data;
  }
  function uc2SearchBuildIndex(){
    if(UC2_SEARCH_INDEX){return UC2_SEARCH_INDEX;}
    UC2_SEARCH_INDEX=[];
    document.querySelectorAll('.universal-card').forEach(function(card,index){
      var titleEl=card.querySelector('.universal-title');
      var promptEl=card.querySelector('.prompttextbox');
      var categoryEl=card.querySelector('.uc2-category-badge');
      var toolEl=card.querySelector('.uc2-tool-badge');
      var qualityEl=card.querySelector('.uc2-quality-score');
      var completeEl=card.querySelector('.uc2-completeness-score')||card.querySelector('.uc2-completeness-value');
      var popularityEl=card.querySelector('.uc2-popularity-label');
      var saveBtn=card.querySelector('.save-btn');
      var analytics=uc2SearchAnalytics(card);
      var intelligence=card._uc2Intelligence||(window.uc2ReadCardPromptIntelligence?window.uc2ReadCardPromptIntelligence(card).result:(window.uc2AnalyzePrompt?window.uc2AnalyzePrompt(uc2SearchText(promptEl)+' '+uc2SearchText(titleEl)):{}));
      var popularity=window.uc2CalculatePopularity?window.uc2CalculatePopularity(analytics):uc2SearchNum((card.querySelector('.uc2-popularity-score')||{}).textContent);
      var trending=window.uc2CalculateTrending?window.uc2CalculateTrending(analytics):0;
      var quality=uc2SearchNum(uc2SearchText(qualityEl))||(intelligence.quality||0);
      var completeness=uc2SearchNum(uc2SearchText(completeEl))||(intelligence.completeness||0);
      UC2_SEARCH_INDEX.push({
        card:card,
        index:index,
        title:uc2SearchText(titleEl),
        prompt:uc2SearchText(promptEl),
        category:uc2SearchText(categoryEl),
        tool:uc2SearchText(toolEl),
        quality:quality,
        completeness:completeness,
        popularityLabel:uc2SearchText(popularityEl),
        popularity:popularity,
        trending:trending,
        saveId:saveBtn?String(saveBtn.getAttribute('data-id')||''):'',
        rank:(popularity*.40)+(trending*.30)+(quality*.20)+(completeness*.10)
      });
    });
    return UC2_SEARCH_INDEX;
  }
  function uc2SearchValues(panel){
    function value(name){var el=panel.querySelector('[data-uc2-filter="'+name+'"]');return el?String(el.value||'').trim():'all';}
    return {keyword:value('keyword').toLowerCase(),category:value('category'),tool:value('tool'),quality:parseInt(value('quality'),10)||0,completeness:parseInt(value('completeness'),10)||0,popularity:value('popularity'),saved:value('saved')};
  }
  function uc2SearchMatch(item,filters,savedIds){
    if(filters.keyword){
      var haystack=(item.title+' '+item.prompt+' '+item.category+' '+item.tool).toLowerCase();
      if(haystack.indexOf(filters.keyword)===-1){return false;}
    }
    if(filters.category!=='all'&&item.category.toLowerCase().indexOf(filters.category.toLowerCase())===-1){return false;}
    if(filters.tool!=='all'&&item.tool.toLowerCase().indexOf(filters.tool.toLowerCase())===-1){return false;}
    if(item.quality<filters.quality){return false;}
    if(item.completeness<filters.completeness){return false;}
    if(filters.popularity!=='all'&&item.popularityLabel!==filters.popularity){return false;}
    if(filters.saved==='saved'&&savedIds.indexOf(item.saveId)===-1){return false;}
    return true;
  }
  function uc2ApplyAdvancedSearch(){
    var panel=document.querySelector('.uc2-search-panel');
    if(!panel){return;}
    var filters=uc2SearchValues(panel);
    var savedIds=uc2SearchSavedIds();
    var matched=[];
    uc2SearchBuildIndex().forEach(function(item){
      if(uc2SearchMatch(item,filters,savedIds)){matched.push(item);}else{item.card.style.display='none';}
    });
    matched.sort(function(a,b){if(b.rank!==a.rank){return b.rank-a.rank;}return a.index-b.index;}).forEach(function(item,order){item.card.style.display='flex';item.card.style.order=String(order);});
    var empty=panel.querySelector('.uc2-search-empty');
    var results=panel.querySelector('.uc2-search-results');
    if(empty){empty.setAttribute('data-uc2-empty',matched.length?'false':'true');}
    if(results){results.textContent=matched.length?'Showing '+matched.length+' matching prompts':'No matching prompts found';}
  }
  function uc2ResetAdvancedSearch(){
    var panel=document.querySelector('.uc2-search-panel');
    if(!panel){return;}
    panel.querySelectorAll('.uc2-filter-select').forEach(function(el){el.value=el.getAttribute('data-uc2-filter')==='keyword'?'':'all';if(el.getAttribute('data-uc2-filter')==='quality'||el.getAttribute('data-uc2-filter')==='completeness'){el.value='0';}});
    uc2ApplyAdvancedSearch();
  }
  function uc2BindAdvancedSearch(){
    if(!document.querySelector('.uc2-search-panel')){return;}
    if(window._uc2AdvancedSearchBound){return;}
    window._uc2AdvancedSearchBound=true;
    document.addEventListener('input',function(event){if(event.target.closest('.uc2-search-panel')&&event.target.classList.contains('uc2-filter-select')){uc2ApplyAdvancedSearch();}});
    document.addEventListener('change',function(event){if(event.target.closest('.uc2-search-panel')&&event.target.classList.contains('uc2-filter-select')){uc2ApplyAdvancedSearch();}});
    document.addEventListener('click',function(event){if(event.target.closest('[data-uc2-filter-reset]')){uc2ResetAdvancedSearch();}});
  }
  window.uc2SearchBuildIndex=uc2SearchBuildIndex;
  window.uc2ApplyAdvancedSearch=uc2ApplyAdvancedSearch;
  window.uc2ResetAdvancedSearch=uc2ResetAdvancedSearch;
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){uc2BindAdvancedSearch();window.setTimeout(uc2ApplyAdvancedSearch,520);});
  }else{
    uc2BindAdvancedSearch();
    window.setTimeout(uc2ApplyAdvancedSearch,520);
  }
})();
