(function() {
  'use strict';

  var STORAGE_KEY = 'promptCollections';
  var DEFAULT_COLLECTIONS = [
    { id: 'col_' + 1, name: 'My Favorites', prompts: [] },
    { id: 'col_' + 2, name: 'Work Prompts', prompts: [] }
  ];
  var currentPostId = null;
  var snapshotRegistry = {};

  function loadCollectionsFromStorage() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) {
        var defaultData = { collections: DEFAULT_COLLECTIONS };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(defaultData));
        if (typeof updateMyCollectionBtnVisibility === 'function') {
          updateMyCollectionBtnVisibility();
        }
        return defaultData;
      }
      var parsed = JSON.parse(raw);
      if (!parsed || !Array.isArray(parsed.collections)) {
        var fixData = { collections: DEFAULT_COLLECTIONS };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(fixData));
        if (typeof updateMyCollectionBtnVisibility === 'function') {
          updateMyCollectionBtnVisibility();
        }
        return fixData;
      }
      return parsed;
    } catch (err) {
      console.warn('Error loading collections from storage:', err);
      return { collections: DEFAULT_COLLECTIONS };
    }
  }

  function saveCollectionsToStorage(data) {
    try {
      if (!data || !Array.isArray(data.collections)) return false;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
      if (typeof updateMyCollectionBtnVisibility === 'function') {
        updateMyCollectionBtnVisibility();
      }
      return true;
    } catch (err) {
      console.warn('Error saving collections to storage:', err);
      return false;
    }
  }

  function isPromptInCollection(collection, postId) {
    if (!collection || !Array.isArray(collection.prompts) || !postId) return false;
    var targetId = String(postId);
    return collection.prompts.some(function(item) {
      var existingId = (typeof item === 'object' && item !== null) ? String(item.id || '') : String(item);
      return existingId === targetId;
    });
  }

  /* MGS 2026-08-30: Build a rich snapshot of a prompt so saved collections store
     thumbnail, title, url and full prompt text (for the professional My Collection page). */
  function buildPromptSnapshot(postId) {
    if (!postId) return null;
    postId = String(postId);
    if (snapshotRegistry[postId]) { return snapshotRegistry[postId]; }
    var card = null;
    try {
      var btn = document.querySelector('.uc2-collection-btn[data-id="'+postId+'"]') ||
                document.querySelector('.copy-prompt-btn[data-id="prompt-'+postId+'"]');
      if (btn) card = btn.closest('.universal-card');
      if (!card) card = document.querySelector('.universal-card[data-post-id="'+postId+'"]');
    } catch (e) { card = null; }
    if (!card) {
      return { id: postId, title: '', url: '', promptText: '', negative: '', hasNegative: false, thumb: '' };
    }
    var titleEl = card.querySelector('.universal-title');
    var title = titleEl ? (titleEl.textContent || '').trim() : '';
    var url = card.getAttribute('data-url') || '';
    var thumb = (typeof card._parsedCover === 'string' && card._parsedCover) ? card._parsedCover : '';
    if (!thumb) {
      try {
        var mediaImg = card.querySelector('.universal-media img');
        if (mediaImg && mediaImg.src && mediaImg.src.indexOf('data:') !== 0) thumb = mediaImg.src;
      } catch (e) {}
    }
    return {
      id: postId,
      title: title,
      url: url,
      promptText: (typeof card._parsedPrompt === 'string') ? card._parsedPrompt : '',
      negative: (typeof card._parsedNegativePrompt === 'string') ? card._parsedNegativePrompt : '',
      hasNegative: !!card._parsedHasNegative,
      thumb: thumb
    };
  }

  function togglePromptInCollection(collectionId, postId) {
    if (!collectionId || !postId) return false;
    var data = loadCollectionsFromStorage();
    var isNowSaved = false;

    data.collections.forEach(function(col) {
      if (String(col.id) === String(collectionId)) {
        if (!Array.isArray(col.prompts)) col.prompts = [];
        var found = false;
        col.prompts = col.prompts.filter(function(item) {
          var existingId = (typeof item === 'object' && item !== null) ? String(item.id || '') : String(item);
          if (existingId === String(postId)) {
            found = true;
            return false;
          }
          return true;
        });

        if (!found) {
          col.prompts.push(buildPromptSnapshot(postId));
          isNowSaved = true;
        }
      }
    });

    saveCollectionsToStorage(data);
    renderCollectionList(postId);
    return isNowSaved;
  }

  function createNewCollection(name) {
    var trimmed = (name || '').trim();
    if (!trimmed) return null;

    var data = loadCollectionsFromStorage();
    var newId = 'col_' + Date.now() + '_' + Math.floor(Math.random() * 999);
    var newCollection = {
      id: newId,
      name: trimmed,
      prompts: currentPostId ? [buildPromptSnapshot(currentPostId)] : []
    };

    data.collections.push(newCollection);
    saveCollectionsToStorage(data);

    if (currentPostId) {
      renderCollectionList(currentPostId);
    }
    return newCollection;
  }

  function renderCollectionList(postId) {
    var container = document.getElementById('uc2-collection-list-container');
    if (!container) return;

    var data = loadCollectionsFromStorage();
    container.innerHTML = '';

    if (!data.collections || data.collections.length === 0) {
      var emptyEl = document.createElement('div');
      emptyEl.className = 'uc2-collection-empty';
      emptyEl.textContent = 'No collections yet. Click "+ Create new collection" below.';
      container.appendChild(emptyEl);
      return;
    }

    data.collections.forEach(function(col) {
      var itemRow = document.createElement('div');
      itemRow.className = 'uc2-collection-item';
      itemRow.setAttribute('role', 'checkbox');
      itemRow.setAttribute('tabindex', '0');
      var checked = isPromptInCollection(col, postId);
      itemRow.setAttribute('aria-checked', checked ? 'true' : 'false');
      itemRow.setAttribute('data-col-id', col.id);

      var leftEl = document.createElement('div');
      leftEl.className = 'uc2-collection-item-left';

      var chk = document.createElement('input');
      chk.type = 'checkbox';
      chk.className = 'uc2-collection-checkbox';
      chk.checked = checked;
      chk.tabIndex = -1;
      chk.setAttribute('aria-label', 'Toggle ' + col.name);

      var nameSpan = document.createElement('span');
      nameSpan.className = 'uc2-collection-name';
      nameSpan.textContent = col.name;
      nameSpan.title = col.name;

      leftEl.appendChild(chk);
      leftEl.appendChild(nameSpan);

      var countSpan = document.createElement('span');
      countSpan.className = 'uc2-collection-count';
      var cnt = (col.prompts && col.prompts.length) ? col.prompts.length : 0;
      countSpan.textContent = cnt === 1 ? '1 prompt' : (cnt + ' prompts');

      itemRow.appendChild(leftEl);
      itemRow.appendChild(countSpan);

      itemRow.addEventListener('click', function(e) {
        e.preventDefault();
        togglePromptInCollection(col.id, postId);
      });

      itemRow.addEventListener('keydown', function(e) {
        if (e.key === ' ' || e.key === 'Enter') {
          e.preventDefault();
          togglePromptInCollection(col.id, postId);
        }
      });

      container.appendChild(itemRow);
    });
  }

  function resetCreateForm() {
    var showBtn = document.getElementById('uc2-show-create-btn');
    var createForm = document.getElementById('uc2-create-form');
    var createInput = document.getElementById('uc2-create-input');
    if (showBtn) showBtn.style.display = 'flex';
    if (createForm) createForm.setAttribute('data-active', 'false');
    if (createInput) createInput.value = '';
  }

  function openCollectionPopup(postId) {
    if (!postId) return;
    currentPostId = String(postId);

    resetCreateForm();
    renderCollectionList(currentPostId);

    var modal = document.getElementById('uc2-collection-modal');
    if (modal) {
      modal.setAttribute('data-uc2-open', 'true');
      document.body.style.overflow = 'hidden';
      setTimeout(function() {
        var closeBtn = document.getElementById('uc2-collection-close');
        if (closeBtn) closeBtn.focus();
      }, 50);
    }
  }

  function closeCollectionPopup() {
    var modal = document.getElementById('uc2-collection-modal');
    if (modal) {
      modal.setAttribute('data-uc2-open', 'false');
      document.body.style.overflow = '';
      currentPostId = null;
    }
  }

  function getPostIdFromButton(btn) {
    if (!btn) return null;
    var inlineId = btn.getAttribute('data-id');
    if (inlineId) return inlineId;

    var card = btn.closest('.universal-card');
    if (card) {
      var cardId = card.getAttribute('data-post-id') || card.getAttribute('data-id');
      if (cardId) return cardId;
    }
    return 'default-post-id';
  }

  function bindCollectionPopupEvents() {
    document.addEventListener('click', function(e) {
      var collectionBtn = e.target.closest('.uc2-collection-btn');
      if (collectionBtn) {
        e.preventDefault();
        var postId = getPostIdFromButton(collectionBtn);
        openCollectionPopup(postId);
        return;
      }

      if (e.target.closest('#uc2-collection-close') || e.target.closest('.uc2-collection-close-btn')) {
        e.preventDefault();
        closeCollectionPopup();
        return;
      }

      if (e.target.id === 'uc2-collection-overlay' || (e.target.classList && e.target.classList.contains('uc2-collection-overlay'))) {
        e.preventDefault();
        closeCollectionPopup();
        return;
      }

      if (e.target.id === 'uc2-collection-done' || e.target.closest('.uc2-collection-done-btn')) {
        e.preventDefault();
        closeCollectionPopup();
        return;
      }
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var modal = document.getElementById('uc2-collection-modal');
        if (modal && modal.getAttribute('data-uc2-open') === 'true') {
          closeCollectionPopup();
        }
      }
    });

    var showCreateBtn = document.getElementById('uc2-show-create-btn');
    var createForm = document.getElementById('uc2-create-form');
    var createInput = document.getElementById('uc2-create-input');
    var cancelCreateBtn = document.getElementById('uc2-create-cancel');
    var submitCreateBtn = document.getElementById('uc2-create-submit');

    if (showCreateBtn && createForm && createInput) {
      showCreateBtn.addEventListener('click', function(e) {
        e.preventDefault();
        showCreateBtn.style.display = 'none';
        createForm.setAttribute('data-active', 'true');
        setTimeout(function() {
          createInput.focus();
        }, 50);
      });
    }

    if (cancelCreateBtn) {
      cancelCreateBtn.addEventListener('click', function(e) {
        e.preventDefault();
        resetCreateForm();
      });
    }

    function handleCreateSubmit() {
      if (!createInput) return;
      var val = createInput.value.trim();
      if (!val) return;
      createNewCollection(val);
      resetCreateForm();
    }

    if (submitCreateBtn) {
      submitCreateBtn.addEventListener('click', function(e) {
        e.preventDefault();
        handleCreateSubmit();
      });
    }

    if (createInput) {
      createInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          handleCreateSubmit();
        } else if (e.key === 'Escape') {
          e.stopPropagation();
          resetCreateForm();
        }
      });
    }
  }

  window.uc2Public = window.uc2Public || {};
  window.uc2Public.registerPromptSnapshot = function(id, snapshot) { snapshotRegistry[String(id)] = snapshot; };
  window.openCollectionPopup = openCollectionPopup;
  window.closeCollectionPopup = closeCollectionPopup;
  window.renderCollectionList = renderCollectionList;
  window.togglePromptInCollection = togglePromptInCollection;
  window.createNewCollection = createNewCollection;
  window.saveCollectionsToStorage = saveCollectionsToStorage;
  window.loadCollectionsFromStorage = loadCollectionsFromStorage;

  window.uc2OpenCollectionModal = function(prompt) {
    var postId = (typeof prompt === 'object' && prompt ? prompt.id : prompt) || '';
    openCollectionPopup(postId);
  };
  window.uc2CloseCollectionModal = closeCollectionPopup;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindCollectionPopupEvents);
  } else {
    bindCollectionPopupEvents();
  }
})();
