(function(){
  var UC2_VERSION_KEY='uc2PromptVersions';
  var UC2_VERSION_ANALYTICS_KEY='uc2VersionAnalytics';
  var uc2CurrentVersionPrompt=null;
  var uc2CompareBuffer=[];

  function uc2VersionDefault(){return {versions:[]};}
  function uc2VersionData(){
    try{var data=JSON.parse(localStorage.getItem(UC2_VERSION_KEY)||'null')||uc2VersionDefault();data.versions=Array.isArray(data.versions)?data.versions:[];return data;}catch(e){return uc2VersionDefault();}
  }
  function uc2SaveVersionData(data){localStorage.setItem(UC2_VERSION_KEY,JSON.stringify(data));return data;}
  function uc2VersionAnalytics(){try{return JSON.parse(localStorage.getItem(UC2_VERSION_ANALYTICS_KEY)||'null')||{versionOpen:0,versionCompare:0,versionRestore:0,versionLatestUsage:0};}catch(e){return {versionOpen:0,versionCompare:0,versionRestore:0,versionLatestUsage:0};}}
  function uc2TrackVersion(type){var a=uc2VersionAnalytics();a[type]=(a[type]||0)+1;localStorage.setItem(UC2_VERSION_ANALYTICS_KEY,JSON.stringify(a));return a;}
  function uc2VersionPromptFromButton(button){var card=button.closest('.universal-card');var prompt=card?card.querySelector('.prompttextbox'):null;return {id:String(button.getAttribute('data-id')||button.getAttribute('data-url')||''),title:String(button.getAttribute('data-title')||'Prompt'),url:String(button.getAttribute('data-url')||'#'),prompt:prompt?(prompt.innerText||prompt.textContent||''):''};}
  function uc2VersionsFor(id){return uc2VersionData().versions.filter(function(version){return String(version.id)===String(id);}).sort(function(a,b){return String(a.version).localeCompare(String(b.version),undefined,{numeric:true});});}
  function uc2EnsurePromptVersions(prompt){
    var data=uc2VersionData();
    var existing=data.versions.filter(function(version){return String(version.id)===String(prompt.id);});
    if(!existing.length){
      data.versions.push({id:prompt.id,version:'1.0',date:(new Date()).toISOString(),stable:true,latest:false,summary:'Initial version',prompt:prompt.prompt||'',negativePrompt:'',notes:'Created from current prompt content.'});
      data.versions.push({id:prompt.id,version:'1.1',date:(new Date()).toISOString(),stable:false,latest:false,summary:'Improved Lighting',prompt:prompt.prompt||'',negativePrompt:'blurry, distorted, low quality',notes:'Improved lighting and added negative prompt.'});
      data.versions.push({id:prompt.id,version:'2.0',date:(new Date()).toISOString(),stable:true,latest:false,summary:'Added DSLR Camera Settings',prompt:prompt.prompt||'',negativePrompt:'blurry, distorted, low quality',notes:'Added DSLR Camera Settings and improved composition.'});
      data.versions.push({id:prompt.id,version:'2.1',date:(new Date()).toISOString(),stable:false,latest:true,summary:'Latest update',prompt:prompt.prompt||'',negativePrompt:'blurry, distorted, low quality',notes:'LATEST. Added Negative Prompt and updated settings.'});
      uc2SaveVersionData(data);
    }
    return uc2VersionsFor(prompt.id);
  }
  function uc2LatestVersion(versions){return versions.filter(function(v){return v.latest;})[0]||versions[versions.length-1]||null;}
  function uc2StableVersion(versions){var stable=versions.filter(function(v){return v.stable;});return stable[stable.length-1]||null;}
  function uc2UpdateVersionBadges(){document.querySelectorAll('.uc2-version-badge').forEach(function(button){var prompt=uc2VersionPromptFromButton(button);var versions=uc2EnsurePromptVersions(prompt);var latest=uc2LatestVersion(versions);var stable=uc2StableVersion(versions);var number=button.querySelector('[data-uc2-version-number]');var updated=button.querySelector('[data-uc2-version-updated]');var stableEl=button.querySelector('[data-uc2-version-stable]');if(number&&latest){number.textContent='v'+latest.version;}if(updated){updated.textContent=latest?'LATEST':'NEW';}if(stableEl){stableEl.textContent=stable?'STABLE':'UPDATED';}});}
  function uc2DiffText(a,b){var oldWords=String(a||'').split(/\s+/);var newWords=String(b||'').split(/\s+/);var added=[];newWords.forEach(function(word){if(oldWords.indexOf(word)===-1&&added.indexOf(word)===-1){added.push(word);}});return added.length?'Changes: '+added.slice(0,24).join(' '):'Changes: No major text differences detected.';}
  function uc2RenderVersionModal(){
    var modal=document.querySelector('.uc2-version-modal');if(!modal||!uc2CurrentVersionPrompt){return;}
    var versions=uc2EnsurePromptVersions(uc2CurrentVersionPrompt);var timeline=modal.querySelector('.uc2-version-timeline');var list=modal.querySelector('.uc2-version-list');var compare=modal.querySelector('.uc2-version-compare');var empty=modal.querySelector('.uc2-version-empty');
    if(timeline){timeline.innerHTML='';versions.forEach(function(v,i){var span=document.createElement('span');span.textContent='v'+v.version+(i<versions.length-1?' ↓':'');timeline.appendChild(span);});}
    if(list){list.innerHTML='';versions.forEach(function(v){var item=document.createElement('div');item.className='uc2-version-item';item.setAttribute('data-uc2-version',v.version);var strong=document.createElement('strong');strong.textContent='v'+v.version;item.appendChild(strong);item.appendChild(document.createTextNode(' '+(v.latest?'LATEST ':'')+(v.stable?'STABLE ':'')));item.appendChild(document.createElement('br'));item.appendChild(document.createTextNode(v.summary||''));item.appendChild(document.createElement('br'));item.appendChild(document.createTextNode(v.notes||''));var view=document.createElement('button');view.setAttribute('data-uc2-version-view',v.version);view.textContent='View';item.appendChild(view);var cmp=document.createElement('button');cmp.setAttribute('data-uc2-version-compare',v.version);cmp.textContent='Compare';item.appendChild(cmp);var restore=document.createElement('button');restore.className='uc2-version-restore';restore.setAttribute('data-uc2-version-restore',v.version);restore.textContent='Restore';item.appendChild(restore);list.appendChild(item);});}
    if(compare){compare.textContent='Select two versions to compare.';}if(empty){empty.setAttribute('data-uc2-empty',versions.length?'false':'true');}
  }
  function uc2OpenVersionModal(prompt){uc2CurrentVersionPrompt=prompt;uc2CompareBuffer=[];uc2TrackVersion('versionOpen');uc2EnsurePromptVersions(prompt);uc2RenderVersionModal();var modal=document.querySelector('.uc2-version-modal');if(modal){modal.setAttribute('data-uc2-open','true');}}
  function uc2CloseVersionModal(){var modal=document.querySelector('.uc2-version-modal');if(modal){modal.setAttribute('data-uc2-open','false');}}
  function uc2ViewVersion(version){var v=uc2VersionsFor(uc2CurrentVersionPrompt.id).filter(function(item){return item.version===version;})[0];var box=document.querySelector('.uc2-version-compare');if(v&&box){box.textContent='Prompt:\n'+v.prompt+'\n\nNegative Prompt:\n'+v.negativePrompt+'\n\nNotes:\n'+v.notes+'\n\nSummary:\n'+v.summary;}}
  function uc2CompareVersions(version){uc2CompareBuffer.push(version);if(uc2CompareBuffer.length>2){uc2CompareBuffer=uc2CompareBuffer.slice(uc2CompareBuffer.length-2);}if(uc2CompareBuffer.length===2){var versions=uc2VersionsFor(uc2CurrentVersionPrompt.id);var a=versions.filter(function(v){return v.version===uc2CompareBuffer[0];})[0];var b=versions.filter(function(v){return v.version===uc2CompareBuffer[1];})[0];var box=document.querySelector('.uc2-version-compare');if(a&&b&&box){uc2TrackVersion('versionCompare');box.textContent='Compare v'+a.version+' → v'+b.version+'\n\nPrompt A:\n'+a.prompt+'\n\nPrompt B:\n'+b.prompt+'\n\nNegative A:\n'+a.negativePrompt+'\n\nNegative B:\n'+b.negativePrompt+'\n\nNotes:\n'+a.notes+'\n---\n'+b.notes+'\n\n'+uc2DiffText(a.prompt+' '+a.notes,b.prompt+' '+b.notes);}}}
  function uc2RestoreVersion(version){var data=uc2VersionData();data.versions.forEach(function(v){if(String(v.id)===String(uc2CurrentVersionPrompt.id)){v.latest=(v.version===version);}});uc2SaveVersionData(data);uc2TrackVersion('versionRestore');uc2TrackVersion('versionLatestUsage');uc2RenderVersionModal();uc2UpdateVersionBadges();return true;}
  function uc2BindVersions(){if(window._uc2VersionsBound){return;}window._uc2VersionsBound=true;document.addEventListener('click',function(event){var badge=event.target.closest('.uc2-version-badge');if(badge){event.preventDefault();uc2OpenVersionModal(uc2VersionPromptFromButton(badge));return;}if(event.target.closest('[data-uc2-version-close]')){uc2CloseVersionModal();return;}if(event.target.classList&&event.target.classList.contains('uc2-version-overlay')){uc2CloseVersionModal();return;}var view=event.target.closest('[data-uc2-version-view]');if(view){uc2ViewVersion(view.getAttribute('data-uc2-version-view'));return;}var cmp=event.target.closest('[data-uc2-version-compare]');if(cmp){uc2CompareVersions(cmp.getAttribute('data-uc2-version-compare'));return;}var restore=event.target.closest('[data-uc2-version-restore]');if(restore){uc2RestoreVersion(restore.getAttribute('data-uc2-version-restore'));}});document.addEventListener('keydown',function(event){if(event.key==='Escape'){uc2CloseVersionModal();}});}
  window.uc2EnsurePromptVersions=uc2EnsurePromptVersions;window.uc2OpenVersionModal=uc2OpenVersionModal;window.uc2CloseVersionModal=uc2CloseVersionModal;window.uc2CompareVersions=uc2CompareVersions;window.uc2RestoreVersion=uc2RestoreVersion;window.uc2VersionData=uc2VersionData;window.uc2VersionAnalytics=uc2VersionAnalytics;window.uc2UpdateVersionBadges=uc2UpdateVersionBadges;
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){uc2BindVersions();window.setTimeout(uc2UpdateVersionBadges,620);});}else{uc2BindVersions();window.setTimeout(uc2UpdateVersionBadges,620);}
})();
