//
/* ============================================================
   MGS SMART NUMBERED PAGINATION v4 — PURE NATIVE (2026-07-03)
   AJAX removed (Task 6.1): every page number / Prev / Next is a
   plain anchor to a native Blogger URL; the browser performs a
   normal full-page navigation. No fetch, no History API, no page
   swapping, no loading states. rel=prev/next kept for SEO.
   Progressive enhancement over Blogger's native cursor pagination.
   - Server layer: 'nextprev' includable renders real Older/Newer
     links (crawl path, no-JS fallback).
   - This script upgrades #blog-pager into numbered pagination
     using ONLY native Blogger URLs (updated-max / updated-min /
     max-results). No hash navigation. No JS-only routing.
   Verified live protocol facts baked in:
   * Index pages order posts by PUBLISHED desc.
   * ?updated-max=YYYY-MM-DDTHH:MM:SS±hh:mm (NO milliseconds) is an
     EXCLUSIVE upper bound on published date. Millisecond timestamps
     are silently ignored by Blogger — never emit them.
   * Homepage path (/) ignores updated-max; its older pages must use
     /search?updated-max=...  (this is also what native Blogger does).
   * Archive paths ignore updated-max; their older pages must use
     /search?updated-min=WINDOW_START&updated-max=CURSOR (native
     Blogger behavior as well).
   * ?q= searches have no queryable total (page vs feed results
     differ), so they gracefully keep Prev/Next only.
   ============================================================ */
(function () {
  'use strict';

  var pager = document.getElementById('blog-pager');
  if (!pager) { return; }                    /* item/static pages: no pager */

  var loc = window.location;
  var path = loc.pathname;
  var params = new URLSearchParams(loc.search);
  var CACHE_TTL = 10 * 60 * 1000;            /* 10 min */
  var FEED_CAP = 500;

  /* ---------- context detection ---------- */
  var ctx = null;
  var mLabel = path.match(/^\/search\/label\/([^/?]+)/);
  var mArch1 = path.match(/^\/(\d{4})\/(\d{2})\/?$/);
  var mArch2 = path.match(/^\/(\d{4})_(\d{2})_\d{2}_archive\.html$/);

  if (mLabel) {
    ctx = { type: 'label', label: decodeURIComponent(mLabel[1]) };
  } else if (mArch1 || mArch2) {
    var am = mArch1 || mArch2;
    ctx = { type: 'archive', y: +am[1], mo: +am[2] };
  } else if (path === '/search' || path === '/search/') {
    if (params.get('q')) {
      ctx = { type: 'query' };
    } else if (params.get('updated-min')) {
      var um = params.get('updated-min').match(/^(\d{4})-(\d{2})/);
      ctx = um ? { type: 'archive', y: +um[1], mo: +um[2] } : { type: 'home' };
    } else {
      ctx = { type: 'home' };
    }
  } else if (path === '/' || path === '/index.html') {
    ctx = { type: 'home' };
  } else {
    return;                                   /* unknown context: leave fallback */
  }

  /* ---------- q-search: style native prev/next only ---------- */
  if (ctx.type === 'query') {
    enhanceFallbackOnly();
    return;
  }

  /* ---------- page size: read it from Blogger's own pager URLs ---------- */
  function pageSizeFromFallback() {
    var links = pager.querySelectorAll('a[href*="max-results="]');
    for (var i = 0; i < links.length; i++) {
      var m = links[i].getAttribute('href').match(/[?&]max-results=(\d+)/);
      if (m) { return +m[1]; }
    }
    var mr = params.get('max-results');
    if (mr && +mr > 0) { return +mr; }
    var cards = document.querySelectorAll('.universal-card').length;
    return cards > 0 ? cards : 20;
  }
  var PER = pageSizeFromFallback();

  /* ---------- date helpers (all second-precision, tz preserved) ---------- */
  function trunc(iso) { return iso.replace(/\.\d+/, ''); }
  function epoch(iso) { var t = Date.parse(iso); return isNaN(t) ? 0 : Math.floor(t / 1000); }
  function offMin(iso) {
    var m = iso.match(/([+-])(\d{2}):(\d{2})$/); if (!m) { return 0; }
    var v = (+m[2]) * 60 + (+m[3]); return m[1] === '-' ? -v : v;
  }
  function fmt(ep, om) {
    var d = new Date((ep + om * 60) * 1000);
    function p(n) { return (n < 10 ? '0' : '') + n; }
    var o = (om < 0 ? '-' : '+') + p(Math.floor(Math.abs(om) / 60)) + ':' + p(Math.abs(om) % 60);
    return d.getUTCFullYear() + '-' + p(d.getUTCMonth() + 1) + '-' + p(d.getUTCDate()) +
      'T' + p(d.getUTCHours()) + ':' + p(d.getUTCMinutes()) + ':' + p(d.getUTCSeconds()) + o;
  }

  /* ---------- feed URL for this context ---------- */
  function feedUrl() {
    var base = '/feeds/posts/summary';
    if (ctx.type === 'label') { base += '/-/' + encodeURIComponent(ctx.label); }
    var qs = '?alt=json&orderby=published&max-results=' + FEED_CAP;
    if (ctx.type === 'archive') {
      var y2 = ctx.mo === 12 ? ctx.y + 1 : ctx.y, m2 = ctx.mo === 12 ? 1 : ctx.mo + 1;
      qs += '&published-min=' + ctx.y + '-' + pad2(ctx.mo) + '-01T00:00:00' +
            '&published-max=' + y2 + '-' + pad2(m2) + '-01T00:00:00';
    }
    return base + qs;
  }
  function pad2(n) { return (n < 10 ? '0' : '') + n; }

  /* ---------- page URL builders (native Blogger URLs only) ---------- */
  function windowMin() { return ctx.y + '-' + pad2(ctx.mo) + '-01T00:00:00'; }
  function pageUrl(n, boundaries) {
    if (n <= 1) {
      if (ctx.type === 'label') { return '/search/label/' + encodeURIComponent(ctx.label).replace(/%20/g, '%20'); }
      if (ctx.type === 'archive') { return '/' + ctx.y + '/' + pad2(ctx.mo) + '/'; }
      return '/';
    }
    var cur = encodeURIComponent(boundaries[n - 2]);
    if (ctx.type === 'label') {
      return '/search/label/' + encodeURIComponent(ctx.label) + '?updated-max=' + cur + '&max-results=' + PER;
    }
    if (ctx.type === 'archive') {
      return '/search?updated-min=' + encodeURIComponent(windowMin()) + '&updated-max=' + cur + '&max-results=' + PER;
    }
    return '/search?updated-max=' + cur + '&max-results=' + PER; /* home */
  }

  /* ---------- boundary cursors from DESC published dates ---------- */
  function boundaries(pubs) {
    var out = [];
    for (var k = 1; k * PER < pubs.length; k++) {
      var last = pubs[k * PER - 1], next = pubs[k * PER];
      var b = trunc(last), be = epoch(b);
      if (be <= epoch(next)) { b = fmt(be + 1, offMin(last)); } /* same-second collision */
      out.push(b);
    }
    return out;
  }

  /* ---------- current page ---------- */
  function currentPage(bnds, pubs) {
    var umax = params.get('updated-max');
    if (!umax) { return 1; }
    for (var i = 0; i < bnds.length; i++) { if (bnds[i] === umax) { return i + 2; } }
    var t = epoch(umax), newer = 0;
    for (var j = 0; j < pubs.length; j++) { if (epoch(pubs[j]) >= t) { newer++; } }
    var total = Math.ceil(pubs.length / PER);
    return Math.min(Math.max(Math.floor(newer / PER) + 1, 1), total);
  }

  /* ---------- 1 2 … c-1 c c+1 … N ---------- */
  function pageList(cur, total) {
    if (total <= 7) { var a = []; for (var i = 1; i <= total; i++) { a.push(i); } return a; }
    var keep = {}, arr = [1, 2, cur - 1, cur, cur + 1, total - 1, total];
    for (var k = 0; k < arr.length; k++) { if (arr[k] >= 1 && arr[k] <= total) { keep[arr[k]] = 1; } }
    var nums = Object.keys(keep).map(Number).sort(function (x, y) { return x - y; });
    var out = [];
    for (var j = 0; j < nums.length; j++) {
      if (j > 0 && nums[j] - nums[j - 1] > 1) { out.push(0); }
      out.push(nums[j]);
    }
    return out;
  }

  /* ---------- cached feed fetch (sessionStorage, 10 min TTL) ---------- */
  function cacheKey() {
    return 'mgsPg:' + ctx.type + ':' + (ctx.label || (ctx.y ? ctx.y + '-' + ctx.mo : '')) + ':' + PER;
  }
  function getCached() {
    try {
      var raw = sessionStorage.getItem(cacheKey());
      if (!raw) { return null; }
      var obj = JSON.parse(raw);
      if (Date.now() - obj.t > CACHE_TTL) { return null; }
      return obj.pubs;
    } catch (e) { return null; }
  }
  function setCached(pubs) {
    try { sessionStorage.setItem(cacheKey(), JSON.stringify({ t: Date.now(), pubs: pubs })); } catch (e) {}
  }

  /* ---------- rel=prev/next head links (SEO, no AJAX) ---------- */
  function relLink(rel, href) {
    var id = 'mgs-rel-' + rel;
    var n = document.getElementById(id);
    if (!href) {
      if (n && n.parentNode) { n.parentNode.removeChild(n); }
      return;
    }
    if (!n) {
      n = document.createElement('link');
      n.id = id;
      n.setAttribute('rel', rel);
      (document.head || document.getElementsByTagName('head')[0] || document.body).appendChild(n);
    }
    n.setAttribute('href', href);
  }

  /* ---------- render ---------- */
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) { n.className = cls; }
    if (text != null) { n.appendChild(document.createTextNode(text)); }
    return n;
  }
  function navBtn(label, arrow, href, disabled, rel) {
    var n;
    if (disabled) {
      n = el('span', 'mgs-pg-btn is-disabled');
      n.setAttribute('aria-disabled', 'true');
    } else {
      n = el('a', 'mgs-pg-btn');
      n.href = href;
      if (rel) { n.setAttribute('rel', rel); }
    }
    if (arrow === 'prev') {
      n.appendChild(el('span', 'mgs-pg-arrow', '\u2190'));
      n.appendChild(el('span', 'mgs-pg-btntext', label));
    } else {
      n.appendChild(el('span', 'mgs-pg-btntext', label));
      n.appendChild(el('span', 'mgs-pg-arrow', '\u2192'));
    }
    n.setAttribute('aria-label', label);
    return n;
  }
  function render(pubs) {
    var total = Math.ceil(pubs.length / PER);
    var bnds = boundaries(pubs);
    var cur = currentPage(bnds, pubs);
    relLink('prev', cur > 1 ? pageUrl(cur - 1, bnds) : null);
    relLink('next', cur < total ? pageUrl(cur + 1, bnds) : null);
    if (total <= 1) { pager.style.display = 'none'; return; }

    var nav = el('nav', 'mgs-pg');
    nav.setAttribute('aria-label', 'Pagination');
    nav.appendChild(navBtn('Previous', 'prev', pageUrl(cur - 1, bnds), cur === 1, 'prev'));

    var ul = el('ul', 'mgs-pg-list');
    pageList(cur, total).forEach(function (n) {
      var li = el('li');
      if (n === 0) {
        var dots = el('span', 'mgs-pg-dots', '\u2026');
        dots.setAttribute('aria-hidden', 'true');
        li.appendChild(dots);
      } else if (n === cur) {
        var c = el('span', 'mgs-pg-current', String(n));
        c.setAttribute('aria-current', 'page');
        c.setAttribute('aria-label', 'Page ' + n + ', current page');
        li.appendChild(c);
      } else {
        var a = el('a', null, String(n));
        a.href = pageUrl(n, bnds);
        a.setAttribute('aria-label', 'Go to page ' + n);
        li.appendChild(a);
      }
      ul.appendChild(li);
    });
    nav.appendChild(ul);
    nav.appendChild(navBtn('Next', 'next', pageUrl(cur + 1, bnds), cur === total, 'next'));

    while (pager.firstChild) { pager.removeChild(pager.firstChild); }
    pager.appendChild(nav);
  }

  /* ---------- q-search / error fallback: restyle native links ---------- */
  function enhanceFallbackOnly() {
    var older = pager.querySelector('.blog-pager-older-link');
    var newer = pager.querySelector('.blog-pager-newer-link');
    if (!older && !newer) { return; }
    var nav = el('nav', 'mgs-pg');
    nav.setAttribute('aria-label', 'Pagination');
    nav.appendChild(navBtn('Previous', 'prev', newer ? newer.getAttribute('href') : '#', !newer, 'prev'));
    nav.appendChild(navBtn('Next', 'next', older ? older.getAttribute('href') : '#', !older, 'next'));
    while (pager.firstChild) { pager.removeChild(pager.firstChild); }
    pager.appendChild(nav);
  }

  /* ---------- bootstrap ---------- */
  var cached = getCached();
  if (cached) { render(cached); return; }

  var xhr = new XMLHttpRequest();
  xhr.open('GET', feedUrl(), true);
  xhr.onload = function () {
    try {
      var d = JSON.parse(xhr.responseText);
      var entries = (d.feed && d.feed.entry) || [];
      var pubs = [];
      for (var i = 0; i < entries.length; i++) { pubs.push(entries[i].published.$t); }
      /* feed orderby=published is DESC — assert & normalize just in case */
      pubs.sort(function (a, b) { return epoch(b) - epoch(a); });
      setCached(pubs);
      render(pubs);
    } catch (e) { enhanceFallbackOnly(); }
  };
  xhr.onerror = function () { enhanceFallbackOnly(); };
  xhr.send();
})();

