document.addEventListener('DOMContentLoaded', function () {
  var postBody = document.querySelector('.post-body, .entry-content, .post-content, .article-body');
  var tocBox = document.getElementById('autoTocContainer');
  if (!postBody || !tocBox) return;

  var headings = postBody.querySelectorAll('h2, h3');
  if (!headings || headings.length < 2) {
    tocBox.style.display = 'none';
    return;
  }

  var html = '<div class="toc-title">Table of Contents</div><ul>';
  for (var i = 0; i < headings.length; i++) {
    var h = headings[i];
    var id = h.getAttribute('id');
    if (!id) {
      id = 'toc-heading-' + i;
      h.setAttribute('id', id);
    }
    html += '<li class="' + (h.tagName === 'H3' ? 'toc-h3' : 'toc-h2') + '"><a href="#' + id + '">' + h.textContent + '</a></li>';
  }
  html += '</ul>';
  tocBox.innerHTML = html;
});
