body.script:
//
/* ============================================================
   PREMIUM SHARE POPUP JS (Universal Card)
   Global functions for the new Share popup
============================================================ */

window.mgsSharePopup = null;
window.mgsCurrentShareCard = null;

// Initialize share popup on DOM load
if (window.addEventListener) {
  window.addEventListener('DOMContentLoaded', function() {
    window.mgsSharePopup = document.getElementById('mgsSharePopup');
    if (window.mgsSharePopup) {
      // Close on ESC key
      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' || e.key === 'Esc') {
          window.closeSharePopup();
        }
      });
    }
  });
}

// Open share popup with card data
window.openSharePopup = function(btn) {
  var menu = btn.closest('.uc2-more-menu');
  var card = null;

  // Try to get card from menu's stored reference (menu is body-appended)
  if (menu && menu._card) {
    card = menu._card;
  } else {
    // Fallback: try closest universal-card
    card = btn.closest('.universal-card');
  }

  if (!card) return;

  window.mgsCurrentShareCard = card;

  var url = card.getAttribute('data-url') || window.location.href;
  var title = card.getAttribute('data-title') || document.title;
  var postId = card.getAttribute('data-id') || '';

  var popup = document.getElementById('mgsSharePopup');
  var urlInput = document.getElementById('mgsShareUrlInput');
  var copyBtn = document.getElementById('mgsShareCopyBtn');

  if (popup && urlInput) {
    urlInput.value = url;
    popup.classList.add('active');

    // Reset copy button text
    if (copyBtn) {
      copyBtn.classList.remove('copied');
      copyBtn.textContent = 'Copy';
    }
  }

  // Close the 3-dots menu
  window.uc2CloseAllMoreMenus && window.uc2CloseAllMoreMenus();
};

// Close share popup
window.closeSharePopup = function() {
  var popup = document.getElementById('mgsSharePopup');
  if (popup) {
    popup.classList.remove('active');
  }
  window.mgsCurrentShareCard = null;
};

// Copy URL to clipboard
window.copyShareUrl = function() {
  var urlInput = document.getElementById('mgsShareUrlInput');
  var copyBtn = document.getElementById('mgsShareCopyBtn');

  if (!urlInput) return;

  var url = urlInput.value;

  if (navigator.clipboard) {
    navigator.clipboard.writeText(url).then(function() {
      showCopyFeedback(copyBtn);
    }).catch(function(err) {
      fallbackCopy(url, copyBtn);
    });
  } else {
    fallbackCopy(url, copyBtn);
  }
};

function showCopyFeedback(btn) {
  if (btn) {
    btn.classList.add('copied');
    btn.textContent = 'Copied!';
    setTimeout(function() {
      btn.classList.remove('copied');
      btn.textContent = 'Copy';
    }, 1500);
  }
}

function fallbackCopy(text, btn) {
  var textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.style.position = 'fixed';
  textarea.style.opacity = '0';
  document.body.appendChild(textarea);
  textarea.select();
  try {
    document.execCommand('copy');
    showCopyFeedback(btn);
  } catch (err) {
    // Copy failed
  }
  document.body.removeChild(textarea);
}

// Share to specific platform
window.shareToPlatform = function(btn) {
  var platform = btn.getAttribute('data-platform');
  var card = window.mgsCurrentShareCard;

  // Fallback 1: try menu's stored card reference
  if (!card) {
    var menu = btn.closest('.uc2-more-menu');
    if (menu && menu._card) {
      card = menu._card;
    }
  }

  // Fallback 2: try closest universal-card
  if (!card) {
    card = btn.closest('.universal-card');
  }

  if (!card) return;

  var url = card.getAttribute('data-url') || window.location.href;
  var title = card.getAttribute('data-title') || document.title;

  var shareUrl = '';
  var encodedUrl = encodeURIComponent(url);
  var encodedTitle = encodeURIComponent(title);

  switch (platform) {
    case 'whatsapp':
      shareUrl = 'https://api.whatsapp.com/send?text=' + encodedTitle + '%20' + encodedUrl;
      break;
    case 'facebook':
      shareUrl = 'https://www.facebook.com/sharer/sharer.php?u=' + encodedUrl;
      break;
    case 'x':
      shareUrl = 'https://twitter.com/intent/tweet?url=' + encodedUrl + '&text=' + encodedTitle;
      break;
    case 'email':
      shareUrl = 'mailto:?subject=' + encodedTitle + '&body=' + encodedUrl;
      break;
    case 'reddit':
      shareUrl = 'https://www.reddit.com/submit?url=' + encodedUrl + '&title=' + encodedTitle;
      break;
    case 'pinterest':
      shareUrl = 'https://pinterest.com/pin/create/button/?url=' + encodedUrl + '&description=' + encodedTitle;
      break;
    case 'linkedin':
      shareUrl = 'https://www.linkedin.com/sharing/share-offsite/?url=' + encodedUrl;
      break;
    case 'copy':
      window.copyShareUrl();
      return;
    default:
      return;
  }

  // Open in new tab
  window.open(shareUrl, '_blank', 'noopener,noreferrer');

  // Close popup after a short delay
  setTimeout(window.closeSharePopup, 300);
};

//

//
/* ============================================================
   MGS 2026-08-05: Prompt box protection (universal card only)
   - blocks right-click (context menu) inside .prompttextbox
   - blocks copy events originating inside .prompttextbox
   The Copy Prompt button and the copy dropdown options keep
   working: they use their own clipboard logic, not selection.
============================================================ */
(function(){
  function mgsNodeToElement(node){
    if(!node){return null;}
    if(node.nodeType===1){return node;}
    if(node.nodeType===3){return node.parentElement;}
    return null;
  }
  function mgsInPromptBox(node){
    var el=mgsNodeToElement(node);
    return !!(el&&el.closest&&el.closest('.prompttextbox'));
  }
  document.addEventListener('contextmenu',function(e){
    if(mgsInPromptBox(e.target)){e.preventDefault();}
  },false);
  document.addEventListener('copy',function(e){
    if(mgsInPromptBox(e.target)){e.preventDefault();}
  });
})();
//

//
(function() {
  var btn = document.getElementById('mgs-back-to-top');
  if (!btn) return;
  window.addEventListener('scroll', function() {
    if (window.pageYOffset > 300) {
      btn.style.display = 'block';
    } else {
      btn.style.display = 'none';
    }
  }, { passive: true });
  btn.addEventListener('click', function(e) {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
})();
