(function() {
  var COOKIE_KEY = 'mgs_cookie_consent';
  var GA_ID = 'G-GCD3W9TV5F';
  function mgsLoadGtag() {
    if (window._mgsGtagLoaded) return;
    window._mgsGtagLoaded = true;
    window.dataLayer = window.dataLayer || [];
    window.gtag = function(){ dataLayer.push(arguments); };
    gtag('js', new Date());
    gtag('config', GA_ID);
    var s = document.createElement('script');
    s.async = true;
    s.src = 'https://www.googletagmanager.com/gtag/js?id=' + GA_ID;
    document.head.appendChild(s);
  }
  var consent = null;
  try { consent = localStorage.getItem(COOKIE_KEY); } catch (e) {}
  if (consent === 'accepted') { mgsLoadGtag(); }
  var banner = document.getElementById('mgs-cookie-banner');
  if (!banner) return;
  if (consent) return;
  banner.style.display = 'block';
  var acc = document.getElementById('mgs-cookie-accept');
  var dec = document.getElementById('mgs-cookie-decline');
  if (acc) {
    acc.addEventListener('click', function() {
      try { localStorage.setItem(COOKIE_KEY, 'accepted'); } catch (e) {}
      banner.style.display = 'none';
      mgsLoadGtag();
    });
  }
  if (dec) {
    dec.addEventListener('click', function() {
      try { localStorage.setItem(COOKIE_KEY, 'declined'); } catch (e) {}
      banner.style.display = 'none';
    });
  }
})();
