    mail:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m22 7-10 6L2 7"/></svg>',
    copy:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>',
    print:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9V2h12v7"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>'
  };

  function escHtml(t){ return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

  function cacheGet(key){ try{ var raw=sessionStorage.getItem('mgs:'+key); if(!raw){return null;} var o=JSON.parse(raw); if(!o||!o.t||(Date.now()-o.t)>TTL){ sessionStorage.removeItem('mgs:'+key); return null; } return o.d; }catch(e){ return null; } }
  function cacheSet(key,data){ try{ sessionStorage.setItem('mgs:'+key, JSON.stringify({t:Date.now(),d:data})); }catch(e){} }

  function fetchFeed(url){
    return new Promise(function(resolve,reject){
      var cached=cacheGet(url);
      if(cached){ resolve(cached); return; }
      var cb='mgsCb_'+Math.random().toString(36).substr(2,9);
      var s=document.createElement('script');
      var done=false;
      function clean(){ if(s.parentNode){s.parentNode.removeChild(s);} try{delete window[cb];}catch(e){window[cb]=undefined;} }
      window[cb]=function(data){ if(done){return;} done=true; clean(); cacheSet(url,data); resolve(data); };
      s.onerror=function(){ if(done){return;} done=true; clean(); reject(new Error('feed error')); };
      s.src=url+(url.indexOf('?')===-1?'?':'&')+'callback='+cb;
      document.body.appendChild(s);
    });
  }

  function entryUrl(entry){ if(entry&&entry.link){ for(var i=0;i<entry.link.length;i++){ if(entry.link[i].rel==='alternate'){ return entry.link[i].href; } } } return '#'; }
  function entryTitle(entry){ return (entry&&entry.title&&entry.title.$t)?entry.title.$t:'Untitled Prompt'; }
  function entryId(entry){ var m=((entry&&entry.id&&entry.id.$t)||'').match(/\.post-(\d+)$/); return m?m[1]:''; }
  function entryCats(entry){ var out=[]; ((entry&&entry.category)||[]).forEach(function(c){ if(c.term){out.push(c.term);} }); return out; }
  function mgsHiResThumb(url){
    if(!url){return url;}
    try{
      url=String(url);
      url=url.replace(/\/s\d+(-[a-z-]+)?\//gi,'/s1600/');
      url=url.replace(/=s\d+(-[a-z-]+)?/gi,'=s1600');
      url=url.replace(/\/w\d+-h\d+(-[a-z-]+)?\//gi,'/s1600/');
      url=url.replace(/=w\d+-h\d+(-[a-z-]+)?/gi,'=s1600');
      url=url.replace(/-c-rw/gi,'');
      url=url.replace(/-c(?=[/?]|$)/gi,'');
      return url;
    }catch(e){return url;}
  }
  function mgsGetCardImage(entry){
    var rawUrl='';
    if(entry.content&&entry.content.$t){
      var m=entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
      if(m&&m[1]&&!/emoji|icon|spacer|pixel|1x1/i.test(m[1])){rawUrl=m[1];}
    }
    if(!rawUrl&&entry.media$thumbnail&&entry.media$thumbnail.url){rawUrl=entry.media$thumbnail.url;}
    if(!rawUrl&&entry.media$group&&entry.media$group.media$content){
      var mc=entry.media$group.media$content;
      if(mc&&mc[0]&&mc[0].url){rawUrl=mc[0].url;}
    }
    if(!rawUrl){return null;}
    return String(rawUrl)
      .replace(/\/s\d+(-[a-z0-9-]+)?\//gi,'/s1600/')
      .replace(/\/w\d+-h\d+(-[a-z0-9-]+)?\//gi,'/s1600/')
      .replace(/=s\d+(-[a-z0-9-]+)?/gi,'=s1600')
      .replace(/=w\d+-h\d+(-[a-z0-9-]+)?/gi,'=s1600')
      .replace(/-c-rw/gi,'')
      .replace(/-c(?=[/?]|$)/gi,'');
  }
  function mgsGetHighResImage(entry){ return mgsGetCardImage(entry); }
  function extractThumbFromFeedEntry(entry){ return mgsGetCardImage(entry); }

  function isItemPage(){ return !!document.querySelector('.mgs-prompt-hero') || !!document.querySelector('.mgs-post-section[data-mgs-section="share"]'); }
  function normUrl(u){ try{ var a=document.createElement('a'); a.href=u||''; return (a.hostname||'').replace(/^www\./i,'')+(a.pathname||'/').replace(/\/+$/,''); }catch(e){ return String(u||'').split('?')[0].split('#')[0]; } }
  function currentPostUrl(){ var c=document.querySelector('.universal-card[data-url]'); return (c&&c.getAttribute('data-url'))||window.location.href; }
  function currentLabel(){
    var el=document.querySelector('.mgs-context[data-mgs-role="label"]');
    if(el&&el.getAttribute('data-mgs-label')){ return el.getAttribute('data-mgs-label'); }
    var m=window.location.pathname.match(/\/search\/label\/([^\/]+)/i);
    if(m){ try{ return decodeURIComponent(m[1]); }catch(e){ return m[1]; } }
    var b=document.querySelector('.uc2-category-badge');
    if(b){ return (b.textContent||'').replace(/\s+/g,' ').trim(); }
    return '';
  }
  function filterOutCurrent(entries){
    if(!isItemPage()){ return entries; }
    var cur=normUrl(currentPostUrl());
    return entries.filter(function(e){ return normUrl(entryUrl(e))!==cur; });
  }

  function buildCard(entry,badgeLabel){
    var a=document.createElement('a');
    a.className='uc2-feed-item';
    a.href=entryUrl(entry);
    a.title=entryTitle(entry);
    var thumb=document.createElement('span');
    thumb.className='uc2-feed-thumb';
    var src=extractThumbFromFeedEntry(entry);
    if(src){
      var img=document.createElement('img');
      img.src=src; img.alt=a.title; img.loading='lazy'; img.decoding='async';
      thumb.appendChild(img);
    }else{
      var img=document.createElement('img');
      img.src='https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiPrQaJk-Pf87dHxd2QX7qqxE4T1lX5I5gKBHrca_jKa321zGWjxMl4Hz8jxr14dLA1Szje7lx4i40GfflOP9TGI9f4ddnv4YUyD2jz7H5tp2XNWAWS9vTzp1b4WwRRNyfKR0z0qboPIhX3SVnlYYPbFFXz_8PvuvZL5KIlpqLqV-bdXHTRe0sPKOj4Tl0/s1600/mgt_logo.png';
      img.alt=a.title; img.loading='lazy'; img.decoding='async';
      thumb.appendChild(img);
    }
    if(badgeLabel){
      var b=document.createElement('span');
      b.className='uc2-feed-badge';
      b.innerHTML=badgeLabel;
      thumb.appendChild(b);
    }
    var t=document.createElement('span');
    t.className='uc2-feed-item-title';
    t.textContent=a.title;
    a.appendChild(thumb);
    a.appendChild(t);
    return a;
  }

  /* ---- per-section page slider (4 / 3 / 2 responsive) ---- */
  var sliders=[];
  function initOneSlider(section){
    var carousel=section.querySelector('.uc2-feed-carousel');
    var track=section.querySelector('.uc2-feed-track');
    if(!carousel||!track){ return; }
    var prevBtn=section.querySelector('.uc2-feed-nav--prev');
    var nextBtn=section.querySelector('.uc2-feed-nav--next');
    var st={carousel:carousel,track:track,prevBtn:prevBtn,nextBtn:nextBtn,page:0};
    function measure(){
      var list=track.querySelectorAll('.uc2-feed-item');
      var gap=12;
      try{ var cs=getComputedStyle(track); var g=parseFloat(cs.columnGap)||parseFloat(cs.gap); if(g){gap=g;} }catch(e){}
      var cardStep=list.length?(list[0].getBoundingClientRect().width+gap):0;
      var visible=Math.max(1,Math.round(carousel.clientWidth/(cardStep||1)));
      var maxShift=Math.max(0,track.scrollWidth-carousel.clientWidth);
      return {list:list,cardStep:cardStep,visible:visible,maxShift:maxShift,totalPages:Math.ceil(list.length/Math.max(1,visible))};
    }
    function hideNav(){ if(prevBtn){prevBtn.style.display='none';} if(nextBtn){nextBtn.style.display='none';} }
    function showNav(){ if(prevBtn){prevBtn.style.display='';} if(nextBtn){nextBtn.style.display='';} }
    st.refresh=function(){
      var m=measure();
      if(!m.list.length||m.maxShift<=0||m.totalPages<=1){ hideNav(); track.style.transform='translateX(0px)'; return; }
      showNav();
      st.page=Math.max(0,Math.min(m.totalPages-1,st.page));
      var offset=st.page*m.visible*m.cardStep;
      if(offset>m.maxShift){offset=m.maxShift;}
      track.style.transform='translateX(-'+offset+'px)';
      if(prevBtn){prevBtn.disabled=(st.page===0);}
      if(nextBtn){nextBtn.disabled=(st.page>=m.totalPages-1);}
    };
    if(prevBtn){prevBtn.addEventListener('click',function(){st.page--;st.refresh();});}
    if(nextBtn){nextBtn.addEventListener('click',function(){st.page++;st.refresh();});}
    sliders.push(st);
    st.refresh();
  }
  var resizeT;
  window.addEventListener('resize',function(){ clearTimeout(resizeT); resizeT=setTimeout(function(){ sliders.forEach(function(s){s.refresh();}); },150); });

  function emptySection(section,msg){
    var navs=section.querySelectorAll('.uc2-feed-nav');
    for(var i=0;i<navs.length;i++){ navs[i].style.display='none'; }
    var track=section.querySelector('.uc2-feed-track');
    if(track){ track.innerHTML='<div class="mgs-empty" role="status">'+escHtml(msg)+'</div>'; }
    var grid=section.querySelector('.mgs-category-grid');
    if(grid){ grid.innerHTML='<div class="mgs-empty" role="status">'+escHtml(msg)+'</div>'; }
  }

  function renderCards(section,entries,badgeLabel){
    var track=section.querySelector('.uc2-feed-track');
    if(!track){return;}
    track.innerHTML='';
    if(!entries.length){ emptySection(section,'No prompts found here yet.'); return; }
    entries.forEach(function(e){ track.appendChild(buildCard(e,badgeLabel)); });
    initOneSlider(section);
  }

  /* Section A: similar (same label) */
  function loadSimilar(section){
    var label=currentLabel();
    if(!label){ emptySection(section,'No category detected for this prompt.'); return; }
    fetchFeed(FEED_BASE+'/default/-/'+encodeURIComponent(label)+'?alt=json&max-results=7')
      .then(function(data){
        var entries=filterOutCurrent((data.feed&&data.feed.entry)||[]).slice(0,6);
        renderCards(section,entries,BADGE_ICONS.similar+' Similar');
      })
      .catch(function(){ emptySection(section,'Could not load similar prompts.'); });
  }

  /* Section B: trending (analytics-ranked, recent fallback) */
  function readAnalytics(id){
    if(!id){return {};}
    try{ return JSON.parse(localStorage.getItem('uc2Analytics:'+id)||'null')||{}; }catch(e){ return {}; }
  }
  function loadTrending(section){
    fetchFeed(FEED_BASE+'/default?alt=json&max-results=30')
      .then(function(data){
        var entries=filterOutCurrent((data.feed&&data.feed.entry)||[]);
        var hasData=false;
        var scored=entries.map(function(e){
          var st=readAnalytics(entryId(e));
          var copies=st.cardCopyCount||0, saves=st.cardSaveCount||0, views=st.cardViewCount||0;
          if(copies||saves||views){hasData=true;}
          return {e:e,s:copies*5+saves*10+views*1};
        });
        if(hasData){scored.sort(function(a,b){return b.s-a.s;});}
        renderCards(section,scored.slice(0,6).map(function(x){return x.e;}),BADGE_ICONS.trending+' Trending');
      })
      .catch(function(){ emptySection(section,'Could not load trending prompts.'); });
  }

  /* Section C: recommended (different categories for discovery) */
  function loadRecommended(section){
    fetchFeed(FEED_BASE+'/default?alt=json&max-results=30')
      .then(function(data){
        var entries=filterOutCurrent((data.feed&&data.feed.entry)||[]);
        var label=currentLabel();
        if(label){
          var low=label.toLowerCase();
          var variety=entries.filter(function(e){
            var cats=entryCats(e).map(function(c){return c.toLowerCase();});
            return cats.indexOf(low)===-1;
          });
          if(variety.length>=3){entries=variety;}
        }
        renderCards(section,entries.slice(0,6),BADGE_ICONS.discover+' Discover');
      })
      .catch(function(){ emptySection(section,'Could not load recommendations.'); });
  }

  /* Section D: category explorer */
  function loadCategories(section){
    var grid=section.querySelector('.mgs-category-grid');
    if(!grid){return;}
    fetchFeed(FEED_BASE+'/default?alt=json&max-results=150')
      .then(function(data){
        var entries=(data.feed&&data.feed.entry)||[];
        var counts={};
        entries.forEach(function(e){ entryCats(e).forEach(function(c){ counts[c]=(counts[c]||0)+1; }); });
        var labels=Object.keys(counts).sort(function(a,b){return counts[b]-counts[a];}).slice(0,16);
        if(!labels.length){ grid.innerHTML='<div class="mgs-empty" role="status">No categories found.</div>'; return; }
        grid.innerHTML='';
        labels.forEach(function(name){
          var icon=ICONS[name]||ICONS[name.toLowerCase()]||DEFAULT_ICON;
          var a=document.createElement('a');
          a.className='mgs-category-card';
          a.href='/search/label/'+encodeURIComponent(name);
          var i=document.createElement('span'); i.className='mgs-category-icon'; i.innerHTML=icon;
          var n=document.createElement('span'); n.className='mgs-category-name'; n.textContent=name;
          var cc=document.createElement('span'); cc.className='mgs-category-count'; cc.textContent=counts[name]+' prompt'+(counts[name]===1?'':'s');
          a.appendChild(i); a.appendChild(n); a.appendChild(cc);
          grid.appendChild(a);
        });
      })
      .catch(function(){ grid.innerHTML='<div class="mgs-empty" role="status">Could not load categories.</div>'; });
  }

  /* Section E: share (post pages) */
  function fallbackCopy(text){
    var ta=document.createElement('textarea');
    ta.value=text; ta.setAttribute('readonly','');
    ta.style.position='fixed'; ta.style.top='-9999px'; ta.style.opacity='0';
    document.body.appendChild(ta);
    var sel=document.getSelection(); var rng=document.createRange(); rng.selectNodeContents(ta);
    sel.removeAllRanges(); sel.addRange(rng);
    try{ document.execCommand('copy'); }catch(e){}
    sel.removeAllRanges();
    document.body.removeChild(ta);
  }
  function initShare(section){
    var box=section.querySelector('.mgs-share-buttons');
    if(!box){return;}
    var url=encodeURIComponent(currentPostUrl());
    var title=encodeURIComponent(document.title||'Motion Graphics Studio');
    var defs=[
      {c:'mgs-share-btn--wa',href:'https://api.whatsapp.com/send?text='+title+'%20'+url,label:'WhatsApp',icon:'wa',t:'_blank'},
      {c:'mgs-share-btn--fb',href:'https://www.facebook.com/sharer/sharer.php?u='+url,label:'Facebook',icon:'fb',t:'_blank'},
      {c:'mgs-share-btn--x',href:'https://twitter.com/intent/tweet?url='+url+'&text='+title,label:'X / Twitter',icon:'x',t:'_blank'},
      {c:'mgs-share-btn--pin',href:'https://pinterest.com/pin/create/button/?url='+url+'&description='+title,label:'Pinterest',icon:'pin',t:'_blank'},
      {c:'mgs-share-btn--mail',href:'mailto:?subject='+title+'&body='+url,label:'Email',icon:'mail'},
      {c:'mgs-share-btn--copy',href:null,label:'Copy Link',icon:'copy',action:'copy'},
      {c:'mgs-share-btn--print',href:null,label:'Print',icon:'print',action:'print'}
    ];
    defs.forEach(function(d){
      var el;
      if(d.href){
        el=document.createElement('a');
        el.href=d.href;
        if(d.t){el.target=d.t;el.rel='noopener';}
      }else{
        el=document.createElement('button');
        el.type='button';
      }
      el.className='mgs-share-btn '+d.c;
      el.innerHTML=SVG[d.icon]+'<span>'+escHtml(d.label)+'</span>';
      if(d.action==='copy'){
        el.addEventListener('click',function(){
          var btn=el; var urlRaw=currentPostUrl(); var labelEl=btn.querySelector('span'); var old=labelEl.textContent;
          function done(){ btn.classList.add('mgs-copied'); labelEl.textContent='✓ Copied!'; setTimeout(function(){ btn.classList.remove('mgs-copied'); labelEl.textContent=old; },2000); }
          if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(urlRaw).then(done,function(){fallbackCopy(urlRaw);done();}); }
          else{ fallbackCopy(urlRaw); done(); }
        });
      }else if(d.action==='print'){
        el.addEventListener('click',function(){window.print();});
      }
      box.appendChild(el);
    });
  }

  function loadSection(section){
    var t=section.getAttribute('data-mgs-section');
    if(t==='similar'){loadSimilar(section);}
    else if(t==='trending'){loadTrending(section);}
    else if(t==='recommended'){loadRecommended(section);}
    else if(t==='categories'){loadCategories(section);}
    else if(t==='share'){initShare(section);}
  }

  function init(){
    var container=document.querySelector('.mgs-post-enhancement-container');
    if(!container){return;}
    var sections=container.querySelectorAll('.mgs-post-section');
    if(!sections.length){return;}
    if('IntersectionObserver' in window){
      var io=new IntersectionObserver(function(entries){
        entries.forEach(function(en){
          if(en.isIntersecting){ io.unobserve(en.target); loadSection(en.target); }
        });
      },{rootMargin:'300px 0px'});
      sections.forEach(function(s){io.observe(s);});
    }else{
      sections.forEach(loadSection);
    }
  }

  if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded',init); }
  else{ init(); }
})();
