/* ============================================================
   ROUND 23 — SMART LIVE SEARCH ENGINE (self-contained IIFE)
   Two instances: desktop header (#mgsSearchWrapper / #searchInput)
   and mobile overlay (#mgsSearchWrapperM / #mobileSearchInput).
   - Focus shows dropdown; empty input shows Recent Searches
     (localStorage mgsRecentSearches) + Trending Label pills.
   - Typing debounced 300ms; queries of 2+ chars hit
     /feeds/posts/summary?q=...&alt=json&max-results=5
     (sessionStorage cache -> fetch -> JSONP fallback).
   - Rich results: hi-res thumbs via the established
     mgsGetCardImage()/mgsHiResThumb() normalization chain
     (inlined: those helpers are private to page-scoped IIFEs
     that do not exist on the homepage).
   - Keyword highlighting, skeleton loader, no-results fallback
     with 3 popular prompts, arrow-key navigation, Enter submit.
   No globals are exposed; existing systems are untouched.
   ============================================================ */
(function(){
  'use strict';

  var DEBOUNCE_MS=300;
  var MIN_QUERY=2;
  var MAX_RESULTS=5;
  var RECENT_KEY='mgsRecentSearches';
  var RECENT_SHOWN=5;
  var RECENT_STORED=8;
  var CACHE_PREFIX='mgsSearch:';
  var CACHE_TTL=3600000;
  var FEED_BASE=window.location.origin+'/feeds/posts';
  var TRENDING_LABELS=['Cinematic','AI Background','Photo Retouch','Color Grading','HD Enhance','Wedding Editing','Background Change','Portrait Editing'];
  var FALLBACK_THUMB='https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiPrQaJk-Pf87dHxd2QX7qqxE4T1lX5I5gKBHrca_jKa321zGWjxMl4Hz8jxr14dLA1Szje7lx4i40GfflOP9TGI9f4ddnv4YUyD2jz7H5tp2XNWAWS9vTzp1b4WwRRNyfKR0z0qboPIhX3SVnlYYPbFFXz_8PvuvZL5KIlpqLqV-bdXHTRe0sPKOj4Tl0/s1600/mgt_logo.png';
  var I_CLOCK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" width="15" height="15"><circle cx="12" cy="12" r="9"></circle><polyline points="12 7 12 12 15 14"></polyline></svg>';
  var MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

  /* ---------- utils ---------- */
  function escHtml(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function escRe(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }

  /* Hi-res thumb chain — IDENTICAL normalization to the established
     mgsHiResThumb()/mgsGetCardImage(): content-first extraction with
     emoji/icon/spacer filtering, media$thumbnail + media$group fallbacks,
     then s72-c style sizes upgraded to /s1600/ with crop flags stripped. */
  function hiRes(url){
    if(!url){ return url; }
    try{
      return String(url)
        .replace(/\/s\d+(-[a-z0-9-]+)?\//gi,'/s1600/')
        .replace(/\/w\d+-h\d+(-[a-z0-9-]+)?\//gi,'/s1600/')
        .replace(/=s\d+(-[a-z0-9-]+)?/gi,'=s1600')
        .replace(/=w\d+-h\d+(-[a-z0-9-]+)?/gi,'=s1600')
        .replace(/-c-rw/gi,'')
        .replace(/-c(?=[/?]|$)/gi,'');
    }catch(e){ return url; }
  }
  function thumbFromEntry(entry){
    var rawUrl='';
    if(entry.content&&entry.content.$t){
      var m=entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
      if(m&&m[1]&&!/emoji|icon|spacer|pixel|1x1/i.test(m[1])){ rawUrl=m[1]; }
    }
    if(!rawUrl&&entry.media$thumbnail&&entry.media$thumbnail.url){ rawUrl=entry.media$thumbnail.url; }
    if(!rawUrl&&entry.media$group&&entry.media$group.media$content){
      var mc=entry.media$group.media$content;
      if(mc&&mc[0]&&mc[0].url){ rawUrl=mc[0].url; }
    }
    if(!rawUrl){ return ''; }
    return hiRes(rawUrl);
  }
  function entryUrl(entry){ if(entry&&entry.link){ for(var i=0;i<entry.link.length;i++){ if(entry.link[i].rel==='alternate'){ return entry.link[i].href; } } } return '#'; }
  function entryTitle(entry){ return (entry&&entry.title&&entry.title.$t)?entry.title.$t:'Untitled Prompt'; }
  function entryFirstLabel(entry){ return (entry&&entry.category&&entry.category[0]&&entry.category[0].term)?entry.category[0].term:''; }
  function entryDate(entry){
    try{
      var d=new Date(entry.published.$t);
      if(isNaN(d.getTime())){ return ''; }
      return d.getDate()+' '+MONTHS[d.getMonth()]+' '+d.getFullYear();
    }catch(e){ return ''; }
  }

  /* ---------- feed transport: cache -> fetch -> JSONP fallback ---------- */
  function cacheGet(key){
    try{
      var raw=sessionStorage.getItem(CACHE_PREFIX+key);
      if(!raw){ return null; }
      var o=JSON.parse(raw);
      if(!o||!o.t||(Date.now()-o.t)>CACHE_TTL){ sessionStorage.removeItem(CACHE_PREFIX+key); return null; }
      return o.d;
    }catch(e){ return null; }
  }
  function cacheHas(key){
    try{
      var raw=sessionStorage.getItem(CACHE_PREFIX+key);
      if(!raw){ return false; }
      var o=JSON.parse(raw);
      return !!(o&&o.t&&(Date.now()-o.t)<=CACHE_TTL);
    }catch(e){ return false; }
  }
  function cacheSet(key,data){
    try{ sessionStorage.setItem(CACHE_PREFIX+key,JSON.stringify({t:Date.now(),d:data})); }catch(e){}
  }
  function jsonp(url){
    return new Promise(function(resolve,reject){
      var cb='mgsSearchCb_'+Math.random().toString(36).substr(2,9);
      var s=document.createElement('script');
      var done=false;
      function clean(){ if(s.parentNode){ s.parentNode.removeChild(s); } try{ delete window[cb]; }catch(e){ window[cb]=undefined; } }
      window[cb]=function(data){ if(done){ return; } done=true; clean(); resolve(data); };
      s.onerror=function(){ if(done){ return; } done=true; clean(); reject(new Error('feed error')); };
      s.src=url+(url.indexOf('?')===-1?'?':'&')+'callback='+cb;
      document.body.appendChild(s);
    });
  }
  function fetchJSON(url){
    return new Promise(function(resolve,reject){
      var cached=cacheGet(url);
      if(cached){ resolve(cached); return; }
      var done=false;
      function ok(data){ if(done){ return; } done=true; cacheSet(url,data); resolve(data); }
      function bad(err){ if(done){ return; } done=true; reject(err); }
      if(window.fetch){
        fetch(url,{headers:{'Accept':'application/json'},credentials:'same-origin'})
          .then(function(r){ if(!r.ok){ throw new Error('http '+r.status); } return r.json(); })
          .then(ok)
          .catch(function(){ jsonp(url).then(ok,bad); });
      }else{ jsonp(url).then(ok,bad); }
    });
  }

  /* ---------- recent searches (localStorage: mgsRecentSearches) ---------- */
  function getRecents(){
    try{
      var a=JSON.parse(localStorage.getItem(RECENT_KEY)||'[]');
      if(!Array.isArray(a)){ return []; }
      return a.filter(function(x){ return typeof x==='string'&&!!x.trim(); }).slice(0,RECENT_STORED);
    }catch(e){ return []; }
  }
  function pushRecent(q){
    q=String(q||'').trim();
    if(!q){ return; }
    try{
      var a=getRecents().filter(function(x){ return x.toLowerCase()!==q.toLowerCase(); });
      a.unshift(q);
      localStorage.setItem(RECENT_KEY,JSON.stringify(a.slice(0,RECENT_STORED)));
    }catch(e){}
  }
  function removeRecent(q){
    try{ localStorage.setItem(RECENT_KEY,JSON.stringify(getRecents().filter(function(x){ return x!==q; }))); }catch(e){}
  }

  /* ---------- keyword highlight (HTML-escaped, regex-escaped) ---------- */
  function highlight(title,q){
    var safe=escHtml(title);
    q=String(q||'').trim();
    if(!q){ return safe; }
    try{
      var re=new RegExp(escRe(escHtml(q)),'gi');
      return safe.replace(re,'<b>$&</b>');
    }catch(e){ return safe; }
  }

  /* ---------- one smart-search instance ---------- */
  function SmartSearch(wrapper){
    var input=wrapper.querySelector('.mgs-search-input');
    var dropdown=wrapper.querySelector('.mgs-smart-search-dropdown');
    var clearBtn=wrapper.querySelector('.mgs-search-clear');
    var backBtn=wrapper.querySelector('.mgs-search-back');
    var form=wrapper.querySelector('.mgs-search-form');
    if(!input||!dropdown||!form){ return; }
    var isOverlay=(wrapper.getAttribute('data-mgs-search-instance')==='overlay');
    var debounceT=null, activeIdx=-1, lastQuery='', reqSeq=0, isOpen=false, fsPlaceholder=null;

    wrapper.classList.toggle('has-text',input.value.length>0);

    function setAria(v){ input.setAttribute('aria-expanded',v?'true':'false'); }
    function open(){ if(!isOpen){ isOpen=true; dropdown.classList.add('open'); setAria(true); } }
    function close(){ if(isOpen){ isOpen=false; dropdown.classList.remove('open'); setAria(false); } activeIdx=-1; clearActive(); }
    function clearActive(){
      var a=dropdown.querySelectorAll('.mgs-search-active');
      for(var i=0;i<a.length;i++){ a[i].classList.remove('mgs-search-active'); }
    }
    function isMobile(){ return !!(window.matchMedia&&window.matchMedia('(max-width:767px)').matches); }

    /* Full-screen takeover for the header instance on phones.
       The wrapper is reparented to <body> because .header applies
       backdrop-filter + will-change:transform, which would trap
       position:fixed descendants inside the header box. */
    function enterFullscreen(){
      if(isOverlay||!isMobile()){ return; }
      if(wrapper.classList.contains('mgs-search-fullscreen')){ return; }
      try{
        fsPlaceholder=document.createComment('mgs-search-anchor');
        wrapper.parentNode.insertBefore(fsPlaceholder,wrapper);
        document.body.appendChild(wrapper);
      }catch(e){ fsPlaceholder=null; }
      wrapper.classList.add('mgs-search-fullscreen');
      document.body.style.overflow='hidden';
      input.focus();
    }
    function exitFullscreen(){
      if(!wrapper.classList.contains('mgs-search-fullscreen')){ return; }
      wrapper.classList.remove('mgs-search-fullscreen');
      try{
        if(fsPlaceholder&&fsPlaceholder.parentNode){
          fsPlaceholder.parentNode.insertBefore(wrapper,fsPlaceholder);
          fsPlaceholder.parentNode.removeChild(fsPlaceholder);
        }
      }catch(e){}
      fsPlaceholder=null;
      var ov=document.getElementById('mobileSearchOverlay');
      if(!(ov&&ov.classList.contains('active'))){ document.body.style.overflow=''; }
    }

    function bindThumbFallbacks(){
      var imgs=dropdown.querySelectorAll('img.mgs-search-thumb');
      for(var i=0;i<imgs.length;i++){
        imgs[i].addEventListener('error',function(){
          if(this.src!==FALLBACK_THUMB){ this.src=FALLBACK_THUMB; }
        });
      }
    }

    function skeletonHtml(){
      var h='';
      for(var i=0;i<3;i++){
        h+='<div class="mgs-search-skel">'
          +'<div class="mgs-search-skel-thumb"></div>'
          +'<div class="mgs-search-skel-lines"><div class="mgs-search-skel-line"></div><div class="mgs-search-skel-line"></div></div>'
          +'</div>';
      }
      return h;
    }

    function resultItemHtml(entry,q){
      var url=entryUrl(entry);
      var title=entryTitle(entry);
      var thumb=thumbFromEntry(entry)||FALLBACK_THUMB;
      var label=entryFirstLabel(entry);
      var date=entryDate(entry);
      return '<a class="mgs-search-result-item" href="'+escHtml(url)+'">'
        +'<img class="mgs-search-thumb" src="'+escHtml(thumb)+'" alt="" loading="lazy" decoding="async">'
        +'<span class="mgs-search-text">'
          +'<span class="mgs-search-title">'+highlight(title,q)+'</span>'
          +'<span class="mgs-search-meta">'
            +(label?'<span class="mgs-search-tag">'+escHtml(label)+'</span>':'')
            +(date?'<span>'+escHtml(date)+'</span>':'')
          +'</span>'
        +'</span></a>';
    }

    /* Default state: recent searches + trending label pills */
    function renderDefault(){
      var h='';
      var recents=getRecents();
      if(recents.length){
        h+='<div class="mgs-search-sec">\uD83D\uDD52 Recent Searches</div>';
        for(var i=0;i<Math.min(recents.length,RECENT_SHOWN);i++){
          var q=recents[i];
          h+='<div class="mgs-search-recent" data-q="'+escHtml(q)+'" role="button" tabindex="0">'
            +'<span class="mgs-search-recent-ico">'+I_CLOCK+'</span>'
            +'<span class="mgs-search-recent-q">'+escHtml(q)+'</span>'
            +'<button class="mgs-search-recent-del" type="button" data-del="'+escHtml(q)+'" aria-label="Remove from history">\u2715</button>'
            +'</div>';
        }
      }
      h+='<div class="mgs-search-sec">\uD83D\uDD25 Trending Labels</div><div class="mgs-search-pills">';
      for(var j=0;j<TRENDING_LABELS.length;j++){
        var l=TRENDING_LABELS[j];
        h+='<a class="mgs-search-pill" href="'+escHtml(window.location.origin+'/search/label/'+encodeURIComponent(l))+'">'+escHtml(l)+'</a>';
      }
      h+='</div>';
      dropdown.innerHTML=h;
      dropdown.scrollTop=0;
      activeIdx=-1;
      open();
    }

    function renderResults(entries,q){
      if(!entries||!entries.length){ renderNoResults(q); return; }
      var h='<div class="mgs-search-sec">\uD83D\uDCC4 Results for "'+escHtml(q)+'"</div>';
      for(var i=0;i<Math.min(entries.length,MAX_RESULTS);i++){ h+=resultItemHtml(entries[i],q); }
      h+='<a class="mgs-search-result-item mgs-search-viewall" href="'+escHtml(window.location.origin+'/search?q='+encodeURIComponent(q))+'">'
        +'<span class="mgs-search-text"><span class="mgs-search-title">View all results for "'+escHtml(q)+'" \u2192</span></span></a>';
      dropdown.innerHTML=h;
      bindThumbFallbacks();
      dropdown.scrollTop=0;
      activeIdx=-1;
      open();
    }

    /* No exact matches -> message + 3 popular prompts */
    function renderNoResults(q){
      dropdown.innerHTML='<div class="mgs-search-nores">\uD83D\uDD0D No exact matches found for <b>"'+escHtml(q)+'"</b></div>';
      dropdown.scrollTop=0;
      activeIdx=-1;
      open();
      var seq=++reqSeq;
      fetchJSON(FEED_BASE+'/summary?alt=json&max-results=3').then(function(data){
        if(seq!==reqSeq){ return; }
        var entries=(data&&data.feed&&data.feed.entry)||[];
        if(!entries.length){ return; }
        var h='<div class="mgs-search-sec">\uD83D\uDD25 Popular Prompts</div>';
        for(var i=0;i<Math.min(entries.length,3);i++){ h+=resultItemHtml(entries[i],''); }
        dropdown.insertAdjacentHTML('beforeend',h);
        bindThumbFallbacks();
      }).catch(function(){});
    }

    /* Live fetch (debounced by caller) */
    function runLive(rawQ){
      var q=String(rawQ||'').trim();
      lastQuery=q;
      if(q.length<MIN_QUERY){ renderDefault(); return; }
      var url=FEED_BASE+'/summary?q='+encodeURIComponent(q)+'&alt=json&max-results='+MAX_RESULTS;
      if(!cacheHas(url)){
        dropdown.innerHTML=skeletonHtml();
        dropdown.scrollTop=0;
        activeIdx=-1;
        open();
      }
      var seq=++reqSeq;
      fetchJSON(url).then(function(data){
        if(seq!==reqSeq||q!==input.value.trim()){ return; }
        renderResults((data&&data.feed&&data.feed.entry)||[],q);
      }).catch(function(){
        if(seq!==reqSeq){ return; }
        dropdown.innerHTML='<div class="mgs-search-nores">\u26A0\uFE0F Could not load live results.<br>Press Enter to run a full search.</div>';
        activeIdx=-1;
        open();
      });
    }

    /* Typing: 300ms debounce (bound to input + keyup per spec) */
    function onTyping(){
      var v=input.value;
      wrapper.classList.toggle('has-text',v.length>0);
      clearTimeout(debounceT);
      debounceT=setTimeout(function(){ runLive(v); },DEBOUNCE_MS);
    }
    input.addEventListener('input',onTyping);
    input.addEventListener('keyup',onTyping);

    /* Focus -> show dropdown (spec) */
    input.addEventListener('focus',function(){
      enterFullscreen();
      var v=input.value.trim();
      if(v.length>=MIN_QUERY){
        if(v===lastQuery&&dropdown.innerHTML!==''){ open(); return; }
        runLive(v);
      }else{
        renderDefault();
      }
    });

    /* Clear X -> empty input, refocus, back to default state (spec) */
    if(clearBtn){
      clearBtn.addEventListener('click',function(e){
        e.preventDefault(); e.stopPropagation();
        input.value='';
        wrapper.classList.remove('has-text');
        clearTimeout(debounceT);
        reqSeq++;
        lastQuery='';
        input.focus();
        renderDefault();
      });
    }

    /* Back button exits full-screen mode (header instance);
       the overlay instance also carries an inline toggleMobileSearch() */
    if(backBtn){
      backBtn.addEventListener('click',function(){
        exitFullscreen();
        close();
        input.blur();
      });
    }

    /* Enter -> normal Blogger search submit; log to recents */
    form.addEventListener('submit',function(){
      var q=input.value.trim();
      if(q){ pushRecent(q); }
      clearTimeout(debounceT);
      close();
    });

    /* Dropdown interactions (event delegation) */
    dropdown.addEventListener('click',function(e){
      var t=e.target;
      if(!t||!t.closest){ return; }
      var del=t.closest('.mgs-search-recent-del');
      if(del){
        e.preventDefault(); e.stopPropagation();
        removeRecent(del.getAttribute('data-del'));
        renderDefault();
        return;
      }
      var rec=t.closest('.mgs-search-recent');
      if(rec){
        e.preventDefault();
        var q=rec.getAttribute('data-q')||'';
        pushRecent(q);
        close();
        window.location.href=window.location.origin+'/search?q='+encodeURIComponent(q);
        return;
      }
      var item=t.closest('.mgs-search-result-item');
      if(item){
        pushRecent(lastQuery);
        close();
        /* anchor href navigation proceeds */
      }
    });

    /* Keyboard navigation: arrows cycle results, Enter activates, Escape closes */
    input.addEventListener('keydown',function(e){
      var items=dropdown.querySelectorAll('.mgs-search-result-item');
      var key=e.key;
      if(key==='ArrowDown'||key==='ArrowUp'){
        if(!isOpen||!items.length){ return; }
        e.preventDefault();
        clearActive();
        if(key==='ArrowDown'){ activeIdx=(activeIdx+1)%items.length; }
        else{ activeIdx=(activeIdx<=0?items.length:activeIdx)-1; }
        items[activeIdx].classList.add('mgs-search-active');
        if(items[activeIdx].scrollIntoView){ items[activeIdx].scrollIntoView({block:'nearest'}); }
      }else if(key==='Enter'){
        if(isOpen&&activeIdx>-1&&items[activeIdx]){
          e.preventDefault();
          pushRecent(lastQuery);
          items[activeIdx].click();
        }
      }else if(key==='Escape'){
        if(isOpen){ close(); }
        else if(isOverlay&&typeof window.toggleMobileSearch==='function'){ window.toggleMobileSearch(); }
        else{ exitFullscreen(); }
      }
    });

    /* Click outside -> hide (spec) */
    document.addEventListener('click',function(e){
      if(isOpen&&!wrapper.contains(e.target)){ close(); }
    });

    /* Rotating/resizing above the mobile breakpoint exits full-screen */
    window.addEventListener('resize',function(){ if(!isMobile()){ exitFullscreen(); } });
  }

  function init(){
    var ids=['mgsSearchWrapper','mgsSearchWrapperM'];
    for(var i=0;i<ids.length;i++){
      var w=document.getElementById(ids[i]);
      if(w){ SmartSearch(w); }
    }
  }
  if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded',init); }
  else{ init(); }
})();
