    'video fx':SVG_VIDEO,'video':SVG_VIDEO,'motion graphics':SVG_VIDEO,'motion':SVG_VIDEO,
    'reels':SVG_VIDEO,'text effect':SVG_TYPE,'marathi':SVG_TYPE,'invitation':SVG_HEART,
    'birthday':SVG_HEART,'acne removal':SVG_SPARK,'ai prompt':SVG_SPARK,'ai':SVG_SPARK,
    'chatgpt':SVG_SPARK,'midjourney':SVG_SPARK,'logo':SVG_TAG,'thumbnail':SVG_CAMERA,
    'background':SVG_CAMERA,'archival':SVG_CAMERA,'tutorial':SVG_TYPE,'3d':SVG_TAG,
    'neon':SVG_SPARK,'gold':SVG_TAG,'fire':SVG_SPARK
  };
  var iconSvg='';
  var map=(window.mgsLabelIcons&&typeof window.mgsLabelIcons==='object')?window.mgsLabelIcons:null;
  if(map){ iconSvg=map[rawLabel]||map[pretty]||''; }
