  if(!iconSvg){ iconSvg=window.mgsLabelIconDefault||SVG_TAG; }
  var iconEl=q('icon');
  if(iconEl){ iconEl.innerHTML=iconSvg; }

  /* ---- Description: curated blurbs for known labels + spec fallback ---- */
  var DESC={
    'acne removal':'Professional prompts for cleaning blemishes, spots and skin texture in studio portraits.',
