    var d=DESC[pretty.toLowerCase()]||DESC[rawLabel.toLowerCase()];
    descEl.textContent=d||('Explore curated AI prompts in the "'+pretty+'" collection.');
  }

  /* ---- Chips: 4-8 sibling labels (current excluded), sourced from the
     Category Explorer map keys; curated static list as fallback ---- */
  var FALLBACK_LIST=['Photo Retouch','Photo Cleaning','Color Grading','HD Enhance','AI Background','Background Change','Wedding Editing','Cinematic Portrait'];
  var chipsEl=q('chips');
  if(chipsEl){
    var src=(map&&Object.keys(map).length>=4)?Object.keys(map):FALLBACK_LIST;
    var low=rawLabel.toLowerCase(), lowP=pretty.toLowerCase(), out=[];
    for(var i=0;i<src.length&&out.length<8;i++){
      var n=src[i];
      if(!n){ continue; }
      var nl=String(n).toLowerCase();
      if(nl===low||nl===lowP){ continue; }
      out.push('<a class="mgs-label-chip" href="'+escHtml(ORIGIN+'/search/label/'+encodeURIComponent(n))+'">'+escHtml(prettyLabel(n))+'</a>');
    }
    chipsEl.innerHTML=out.join('');
  }

  /* ---- Count: /feeds/posts/summary/-/LABEL?alt=json&max-results=1
     -> feed.openSearch$totalResults.$t   (cache -> fetch -> JSONP) ---- */
  var countEl=q('count'), tailEl=q('count-tail');
  function applyCount(total){
    if(!countEl||!tailEl){ return; }
    if(total===0){
      countEl.textContent='';
      tailEl.textContent='No prompts in this collection yet.';
      return;
    }
    countEl.textContent=String(total);
    tailEl.textContent=(total===1?' AI Prompt in this collection':' AI Prompts in this collection');
  }
  function countFail(){
    if(countEl){ countEl.textContent=''; }
    if(tailEl){ tailEl.textContent='AI Prompts in this collection'; }
  }
  function applyFromData(data){
    try{
      var osr=(data&&data.feed)?data.feed['openSearch$totalResults']:null;
      var t=parseInt(osr&&osr.$t,10);
      if(isNaN(t)){ countFail(); return; }
      applyCount(t);
      try{ sessionStorage.setItem(COUNT_CACHE_KEY,JSON.stringify({t:Date.now(),n:t})); }catch(e){}
    }catch(e){ countFail(); }
  }
  function jsonpCount(u){
    var cb='mgsLabelHeroCb_'+Math.random().toString(36).substr(2,9);
    var s=document.createElement('script');
    var done=false;
    function clean(){ if(s.parentNode){ s.parentNode.removeChild(s); } try{ delete window[cb]; }catch(e){ window[cb]=undefined; } }
    window[cb]=function(data){ if(done){ return; } done=true; clean(); applyFromData(data); };
    s.onerror=function(){ if(done){ return; } done=true; clean(); countFail(); };
    s.src=u+'&callback='+cb;
    document.body.appendChild(s);
  }
  (function loadCount(){
    try{
      var raw=sessionStorage.getItem(COUNT_CACHE_KEY);
      if(raw){
        var o=JSON.parse(raw);
        if(o&&typeof o.n==='number'&&(Date.now()-o.t)<=COUNT_TTL){ applyCount(o.n); return; }
      }
    }catch(e){}
    var url=ORIGIN+'/feeds/posts/summary/-/'+encodeURIComponent(rawLabel)+'?alt=json&max-results=1';
    if(window.fetch){
      fetch(url,{headers:{'Accept':'application/json'},credentials:'same-origin'})
        .then(function(r){ if(!r.ok){ throw new Error('http '+r.status); } return r.json(); })
        .then(applyFromData)
        .catch(function(){ jsonpCount(url); });
    }else{ jsonpCount(url); }
  })();

  /* ---- Actions: Copy category link + native share (when available) ---- */
  var actEl=q('actions');
  if(actEl){
    var I_LINK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>';
    var I_SHARE='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>';
    var h='<button class="mgs-label-act" data-hero-act="copy" type="button">'+I_LINK+'<span>Copy link</span></button>';
    if(navigator.share){
      h+='<button class="mgs-label-act" data-hero-act="share" type="button">'+I_SHARE+'<span>Share</span></button>';
    }
    actEl.innerHTML=h;
    function legacyCopy(text){
      try{
        var ta=document.createElement('textarea');
        ta.value=text; ta.setAttribute('readonly','');
        ta.style.position='fixed'; ta.style.top='-9999px';
        document.body.appendChild(ta); ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
      }catch(e){}
    }
    actEl.addEventListener('click',function(e){
      var b=(e.target&&e.target.closest)?e.target.closest('[data-hero-act]'):null;
      if(!b){ return; }
      var act=b.getAttribute('data-hero-act');
      if(act==='copy'){
        function feedback(){
          if(typeof window.showToast==='function'){ window.showToast('Category link copied!'); return; }
          var sp=b.querySelector('span');
          if(sp){ var old=sp.textContent; sp.textContent='\u2713 Copied'; setTimeout(function(){ sp.textContent=old; },1600); }
        }
        if(navigator.clipboard&&navigator.clipboard.writeText){
          navigator.clipboard.writeText(window.location.href).then(feedback,function(){ legacyCopy(window.location.href); feedback(); });
        }else{ legacyCopy(window.location.href); feedback(); }
      }else if(act==='share'&&navigator.share){
        try{
          var p=navigator.share({title:pretty+' \u2014 Prompt Collection',text:'AI prompt collection: '+pretty,url:window.location.href});
          if(p&&p.catch){ p.catch(function(){}); }
        }catch(err){}
      }
    });
  }

  /* ---- Browse prompts: smooth scroll with fixed-header offset ---- */
  var browse=q('browse');
  if(browse){
    browse.addEventListener('click',function(e){
      var target=document.getElementById('mgs-label-posts');
      if(!target){ return; }
      e.preventDefault();
      var hdr=document.querySelector('.header');
      var off=((hdr&&hdr.offsetHeight)?hdr.offsetHeight:60)+14;
      var y=target.getBoundingClientRect().top+(window.pageYOffset||document.documentElement.scrollTop)-off;
      if(y<0){ y=0; }
      var reduce=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
      if(!reduce&&'scrollBehavior' in document.documentElement.style){
        window.scrollTo({top:y,behavior:'smooth'});
      }else{
        window.scrollTo(0,y);
      }
      if(window.history&&history.pushState){ history.pushState(null,'','#mgs-label-posts'); }
    });
  }
})();
