/* ROUND 25 — Universal Card title link repair guard (own IIFE, no globals) */
(function(){
  'use strict';
  function mgsRepairTitleLinks(){
    if(document.body&&document.body.classList.contains('pg-item'))return;
    var cards=document.querySelectorAll('.universal-card[data-url]');
    for(var i=0;i<cards.length;i++){
      (function(card){
        var url=(card.getAttribute('data-url')||'').trim();
        if(!url||url==='#')return;
        var title=card.querySelector('.universal-title');
        if(!title)return;
        var anchor=title.querySelector('a');
        if(anchor){
          var href=(anchor.getAttribute('href')||'').trim();
          if(!href||href==='#'){
            anchor.setAttribute('href',url);
          }
          if(!anchor.getAttribute('title')){
            var text=(anchor.textContent||'').replace(/\s+/g,' ').trim();
            if(text)anchor.setAttribute('title',text);
          }
          return;
        }
        var label=(title.textContent||'').replace(/\s+/g,' ').trim();
        if(!label)return;
        title.textContent='';
        var fresh=document.createElement('a');
        fresh.setAttribute('href',url);
        fresh.setAttribute('title',label);
        fresh.textContent=label;
        title.appendChild(fresh);
      })(cards[i]);
    }
  }
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',mgsRepairTitleLinks);
  }else{
    mgsRepairTitleLinks();
  }
})();
