//
/* ===== CUSTOMIZE PROMPT FEATURE JS ===== */

// Global state
var cpCurrentData = {
  mainPrompt: '',
  negativePrompt: '',
  promptTitle: '',
  variables: [],
  selections: {}
};

// ===== PARSE STEP 4 VARIABLES FROM POST BODY =====
function cpParseStep4(postBodyElement) {
  var variables = [];
  if (!postBodyElement) return variables;

  // Find Step 4 heading
  var allEls = postBodyElement.querySelectorAll('h1,h2,h3,h4,h5,h6,strong,b,p,div');
  var step4El = null;

  for (var i = 0; i < allEls.length; i++) {
    var t = allEls[i].textContent.trim().toLowerCase();
    if (/step\s*4/.test(t) && t.indexOf('customize') !== -1 && t.indexOf('variable') !== -1) {
      step4El = allEls[i];
      break;
    }
  }

  if (!step4El) return variables;

  // Collect text after Step 4 until Step 5 or end
  var collected = [];
  var current = step4El.nextElementSibling;

  while (current) {
    var txt = current.textContent.trim();
    if (/step\s*5/i.test(txt)) break;
    if (/^H[1-6]$/i.test(current.tagName) && txt.indexOf('[') === -1) break;
    collected.push(txt);
    current = current.nextElementSibling;
  }

  // Also check if Step 4 element itself has content after the heading text
  var step4Text = step4El.textContent;
  if (step4Text.indexOf('[') !== -1) {
    collected.unshift(step4Text);
  }

  var fullText = collected.join('\n');

  // Pattern: [VAR_NAME] = options  OR  [VAR_NAME] - options  OR  [VAR_NAME] : options
  var pattern = /\[([^\]]+)\]\s*[=\-:]\s*([^\n\[]+)/g;
  var match;
  var found = {};

  while ((match = pattern.exec(fullText)) !== null) {
    var varName = match[1].trim();
    if (found[varName]) continue;
    found[varName] = true;

    var optStr = match[2].trim();
    var opts = cpParseOptions(optStr);

    variables.push({
      name: varName,
      bracket: '[' + varName + ']',
      options: opts
    });
  }

  return variables;
}

// ===== PARSE OPTIONS STRING =====
function cpParseOptions(str) {
  str = str.trim();
  // Remove trailing punctuation
  str = str.replace(/[.,;]+$/, '');

  var result = [];

  if (str.indexOf(' or ') !== -1) {
    var orIdx = str.lastIndexOf(' or ');
    var before = str.substring(0, orIdx);
    var after = str.substring(orIdx + 4).trim();
    var beforeParts = before.split(',');
    for (var i = 0; i < beforeParts.length; i++) {
      var p = beforeParts[i].trim();
      if (p) result.push(p);
    }
    if (after) result.push(after);
  } else {
    var parts = str.split(',');
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (p) result.push(p);
    }
  }

  return result;
}

// ===== FALLBACK: EXTRACT BRACKETS FROM PROMPT =====
function cpExtractBrackets(promptText) {
  var regex = /\[([^\]]+)\]/g;
  var found = {};
  var variables = [];
  var match;

  while ((match = regex.exec(promptText)) !== null) {
    if (!found[match[1]]) {
      found[match[1]] = true;
      variables.push({
        name: match[1],
        bracket: '[' + match[1] + ']',
        options: []
      });
    }
  }
  return variables;
}

// ===== ESCAPE REGEX =====
function cpEscapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ===== ESCAPE HTML =====
function cpEscapeHtml(s) {
  var div = document.createElement('div');
  div.textContent = s;
  return div.innerHTML;
}

// ===== BUILD POPUP UI =====
function cpBuildPopup() {
  var titleEl = document.getElementById('cpPromptTitle');
  if (titleEl) titleEl.textContent = cpCurrentData.promptTitle || 'Customize Your Prompt';

  var container = document.getElementById('cpVariablesContainer');
  container.innerHTML = '';

  if (cpCurrentData.variables.length === 0) {
    container.innerHTML = '<div style="color: rgba(255,255,255,0.5); text-align:center; padding: 20px;">No customizable variables found in this prompt.</div>';
  }

  for (var i = 0; i < cpCurrentData.variables.length; i++) {
    var v = cpCurrentData.variables[i];
    var group = document.createElement('div');
    group.className = 'cp-var-group';

    var optsHtml = '<option value="">-- Select an option --</option>';
    for (var j = 0; j < v.options.length; j++) {
      optsHtml += '<option value="' + cpEscapeHtml(v.options[j]) + '">' + cpEscapeHtml(v.options[j]) + '</option>';
    }

    group.innerHTML =
      '<div class="cp-var-label">[' + cpEscapeHtml(v.name) + ']</div>' +
      '<select class="cp-var-select" data-var="' + cpEscapeHtml(v.name) + '" onchange="cpOnSelect(this)">' + optsHtml + '</select>' +
      '<div class="cp-custom-wrap">' +
        '<span class="cp-custom-label">\u270f\uFE0F Custom:</span>' +
        '<input type="text" class="cp-custom-input" data-var="' + cpEscapeHtml(v.name) + '" placeholder="Type your own value..." oninput="cpOnCustom(this)" />' +
      '</div>';

    container.appendChild(group);
  }

  cpUpdatePreview();
  cpUpdateCounter();
}

// ===== HANDLERS =====
function cpOnSelect(sel) {
  var name = sel.getAttribute('data-var');
  if (sel.value) {
    cpCurrentData.selections[name] = sel.value;
    var custom = sel.parentElement.querySelector('.cp-custom-input');
    if (custom) custom.value = '';
  } else {
    delete cpCurrentData.selections[name];
  }
  cpUpdatePreview();
  cpUpdateCounter();
}

function cpOnCustom(inp) {
  var name = inp.getAttribute('data-var');
  var val = inp.value.trim();
  if (val) {
    cpCurrentData.selections[name] = val;
    var sel = inp.closest('.cp-var-group').querySelector('.cp-var-select');
    if (sel) sel.value = '';
  } else {
    delete cpCurrentData.selections[name];
  }
  cpUpdatePreview();
  cpUpdateCounter();
}

// ===== LIVE PREVIEW =====
function cpUpdatePreview() {
  var main = cpEscapeHtml(cpCurrentData.mainPrompt);

  for (var i = 0; i < cpCurrentData.variables.length; i++) {
    var v = cpCurrentData.variables[i];
    var escBracket = cpEscapeHtml(v.bracket);
    var regex = new RegExp(cpEscapeRegex(escBracket), 'g');

    if (cpCurrentData.selections[v.name]) {
      main = main.replace(regex, '<span class="cp-bracket-filled">' + cpEscapeHtml(cpCurrentData.selections[v.name]) + '</span>');
    } else {
      main = main.replace(regex, '<span class="cp-bracket-unfilled">' + escBracket + '</span>');
    }
  }

  document.getElementById('cpPreviewMain').innerHTML = main;
  document.getElementById('cpPreviewNegative').textContent = cpCurrentData.negativePrompt || '(No negative prompt)';
}

// ===== COUNTER =====
function cpUpdateCounter() {
  var total = cpCurrentData.variables.length;
  var filled = 0;
  for (var k in cpCurrentData.selections) {
    if (cpCurrentData.selections.hasOwnProperty(k)) filled++;
  }
  var el = document.getElementById('cpVarCounter');
  if (el) {
    el.textContent = filled + '/' + total + ' filled';
    el.style.color = (filled === total && total > 0) ? '#64ffda' : '#ffaa32';
  }
}

// ===== QUICK FILL =====
function quickFillAllVars() {
  for (var i = 0; i < cpCurrentData.variables.length; i++) {
    var v = cpCurrentData.variables[i];
    if (v.options.length > 0 && !cpCurrentData.selections[v.name]) {
      cpCurrentData.selections[v.name] = v.options[0];
    }
  }
  var selects = document.querySelectorAll('.cp-var-select');
  for (var i = 0; i < selects.length; i++) {
    var name = selects[i].getAttribute('data-var');
    if (cpCurrentData.selections[name]) selects[i].value = cpCurrentData.selections[name];
  }
  cpUpdatePreview();
  cpUpdateCounter();
}

// ===== COPY =====
function copyCustomizedPrompt(type) {
  var main = cpCurrentData.mainPrompt;
  for (var i = 0; i < cpCurrentData.variables.length; i++) {
    var v = cpCurrentData.variables[i];
    var regex = new RegExp(cpEscapeRegex(v.bracket), 'g');
    var val = cpCurrentData.selections[v.name] || '';
    main = main.replace(regex, val);
  }
  main = main.replace(/\s{2,}/g, ' ').trim();

  var text = '';
  if (type === 'main') text = main;
  else if (type === 'negative') text = cpCurrentData.negativePrompt;
  else text = 'PROMPT:\n' + main + '\n\nNEGATIVE PROMPT:\n' + cpCurrentData.negativePrompt;

  var unfilled = 0;
  for (var i = 0; i < cpCurrentData.variables.length; i++) {
    if (!cpCurrentData.selections[cpCurrentData.variables[i].name]) unfilled++;
  }

  if (unfilled > 0 && type !== 'negative') {
    if (!confirm('\u26A0\uFE0F ' + unfilled + ' variable(s) are still empty.\n\nCopy anyway?')) return;
  }

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(function() {
      cpShowToast('\u2705 Prompt copied!');
    }).catch(function() {
      cpFallbackCopy(text);
    });
  } else {
    cpFallbackCopy(text);
  }
}

function cpFallbackCopy(text) {
  var ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    cpShowToast('\u2705 Prompt copied!');
  } catch(e) {
    cpShowToast('\u274C Copy failed');
  }
  document.body.removeChild(ta);
}

// ===== RESET =====
function resetCustomizePrompt() {
  cpCurrentData.selections = {};
  var selects = document.querySelectorAll('.cp-var-select');
  for (var i = 0; i < selects.length; i++) selects[i].value = '';
  var inputs = document.querySelectorAll('.cp-custom-input');
  for (var i = 0; i < inputs.length; i++) inputs[i].value = '';
  cpUpdatePreview();
  cpUpdateCounter();
  cpShowToast('\u21BA Reset done');
}

// ===== CLOSE =====
function closeCustomizePopup() {
  document.getElementById('customizeOverlay').classList.remove('active');
  document.body.style.overflow = '';
}

// Backdrop click
document.addEventListener('click', function(e) {
  if (e.target && e.target.id === 'customizeOverlay') closeCustomizePopup();
});

// ESC key
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape' || e.keyCode === 27) {
    var overlay = document.getElementById('customizeOverlay');
    if (overlay && overlay.classList.contains('active')) closeCustomizePopup();
  }
});

// ===== TOAST =====
function cpShowToast(msg) {
  var t = document.querySelector('.cp-toast');
  if (!t) {
    t = document.createElement('div');
    t.className = 'cp-toast';
    document.body.appendChild(t);
  }
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(function() { t.classList.remove('show'); }, 2500);
}

// ===== WIRING FUNCTION: OPEN CUSTOMIZE POPUP (Phase 9 — prompt-matched) =====
function openCustomizePromptPopup(triggerEl) {
  var dd = triggerEl.closest ? triggerEl.closest('.copy-dropdown') : null;
  var card =
    (dd && dd._card) ||
    (triggerEl.closest
      ? triggerEl.closest(
          '.universal-card, .mgs-related-card, [data-cp-variables], .post-card, .blog-post, .post, .item-content, article'
        )
      : null);
  if (!card) {
    console.error('CP: Card container not found.');
    return;
  }

  var mainPrompt = card.getAttribute('data-cp-main') || '';
  var negPrompt = card.getAttribute('data-cp-negative') || '';
  var title = card.getAttribute('data-cp-title') || '';

  if (!mainPrompt) {
    var mainEl = card.querySelector(
      '.main-prompt-text, .prompt-text, [data-prompt-main], .copy-text'
    );
    if (mainEl) mainPrompt = mainEl.textContent.trim();
  }
  if (!negPrompt) {
    var negEl = card.querySelector(
      '.neg-prompt-text, .negative-prompt-text, [data-prompt-neg]'
    );
    if (negEl) negPrompt = negEl.textContent.trim();
  }
  if (!title) {
    var titleEl = card.querySelector('.post-title, .card-title, h2, h3, a[href]');
    if (titleEl) title = titleEl.textContent.trim();
  }

  var postUrl =
    card.getAttribute('data-cp-url') ||
    card.getAttribute('data-post-url') ||
    '';
  if (!postUrl) {
    var link =
      card.querySelector('a.cp-post-link, a.post-link, h2 a, h3 a, .post-title a, a[href*="/20"]') ||
      card.querySelector('a[href]');
    if (link && link.href && link.href.indexOf('blogger.com') === -1) {
      postUrl = link.href;
    }
  }

  function renderPopup(variables) {
    cpCurrentData = {
      mainPrompt: mainPrompt,
      negativePrompt: negPrompt,
      promptTitle: title,
      variables: variables || [],
      selections: {}
    };
    if (typeof cpBuildPopup === 'function') cpBuildPopup();
    var overlay = document.getElementById('customizeOverlay');
    if (overlay) {
      overlay.classList.add('active');
      document.body.style.overflow = 'hidden';
    }
  }

  // Close dropdowns
  if (window.closeAllCopyDropdowns) window.closeAllCopyDropdowns();
  if (window.uc2CloseAllMoreMenus) window.uc2CloseAllMoreMenus();

  // Try parsing Step 4 from current document or card
  var step4Map = {};
  var cardText = cpGetTextFromNode(card);
  step4Map = cpParseStep4MapFromText(cardText);

  // If on post page, check document.body
  var postBody =
    document.querySelector('.post-body') ||
    document.querySelector('.entry-content') ||
    document.querySelector('[itemprop="articleBody"]');
  if (postBody) {
    var pageMap = cpParseStep4MapFromText(cpGetTextFromNode(postBody));
    for (var k in pageMap) { if (pageMap.hasOwnProperty(k)) step4Map[k] = pageMap[k]; }
  }

  var variables = cpCombinePromptAndStep4(mainPrompt, negPrompt, step4Map);

  // Check if we have options for all prompt brackets
  var hasOptions = variables.length > 0 && variables.some(function(v) { return v.options && v.options.length > 0; });

  if (hasOptions || !postUrl) {
    renderPopup(variables);
    return;
  }

  // Fallback: Fetch full post page to get Step 4 options
  renderPopup(cpCombinePromptAndStep4(mainPrompt, negPrompt, {}));
  var loading = document.getElementById('cpVarCounter');
  if (loading) loading.textContent = 'Loading options...';

  cpFetchVariablesFromPostUrl(postUrl, mainPrompt, negPrompt, function(fetchedVars) {
    renderPopup(fetchedVars);
  });
}

// ===== HELPER: EXTRACT BRACKETS PRESENT IN MAIN + NEGATIVE PROMPT =====
function cpExtractPromptBrackets(mainPrompt, negPrompt) {
  var fullText = (mainPrompt || '') + ' ' + (negPrompt || '');
  var regex = /\[([^\]]+)\]/g;
  var found = {};
  var list = [];
  var match;

  while ((match = regex.exec(fullText)) !== null) {
    var name = match[1].trim();
    if (name && !found[name]) {
      found[name] = true;
      list.push(name);
    }
  }
  return list; // Array of bracket names actually used in the prompt
}

// ===== HELPER: SAFE TEXT EXTRACTOR (WORKS ON LIVE DOM AND DOMPARSER) =====
function cpGetTextFromNode(node) {
  if (!node) return '';
  if (node.innerText) return node.innerText;

  // Fallback for DOMParser detached DOMs where innerText is undefined
  var text = '';
  var walk = document.createTreeWalker(node, NodeFilter.SHOW_TEXT, null, false);
  var txtNode;
  while ((txtNode = walk.nextNode())) {
    text += ' ' + txtNode.nodeValue + ' ';
  }
  return text;
}

// ===== PARSE STEP 4 INTO A MAP { "VAR_NAME": ["opt1", "opt2"] } =====
function cpParseStep4MapFromText(text) {
  var map = {};
  if (!text) return map;

  var lower = text.toLowerCase();
  var start = lower.indexOf('customize these variables');
  if (start === -1) start = lower.indexOf('step 4');
  if (start === -1) start = 0;

  var end = lower.indexOf('step 5', start + 1);
  if (end === -1) end = lower.indexOf('expected output', start + 1);
  if (end === -1) end = text.length;

  var searchArea = text.substring(start, end);

  // Normalize arrows and spacing
  searchArea = searchArea
    .replace(/[→⇒⟶➔➜]/g, ' = ')
    .replace(/\]\s*=/g, '] = ')
    .replace(/=\s*/g, '= ');

  var pattern = /\[([^\]]+)\]\s*[=\-:]\s*([^\n\r\[\]]+)/g;
  var match;

  while ((match = pattern.exec(searchArea)) !== null) {
    var varName = match[1].trim();
    var optStr = match[2].trim();

    optStr = optStr.replace(/\s*[→•·].*$/, '').trim().replace(/[.,;]+$/, '').trim();

    var opts = cpParseOptions(optStr);
    if (opts && opts.length > 0) {
      map[varName] = opts;
    }
  }
  return map;
}

function cpParseStep4MapFromDom(root) {
  var map = {};
  if (!root) return map;

  var codes = root.querySelectorAll('code, pre, b, strong');
  for (var i = 0; i < codes.length; i++) {
    var c = codes[i];
    var bracketText = (c.textContent || '').trim();
    var m = bracketText.match(/^\[([^\]]+)\]$/);
    if (!m) continue;

    var varName = m[1].trim();
    var parent = c.parentElement;
    if (!parent) continue;

    var fullText = cpGetTextFromNode(parent);
    var optStr = fullText.replace(bracketText, '').trim();
    optStr = optStr.replace(/^[\s⇒⟶➔➜=\-:→]+/, '').trim();
    optStr = optStr.replace(/[.,;]+$/, '').trim();

    var opts = cpParseOptions(optStr);
    if (opts && opts.length > 0) {
      map[varName] = opts;
    }
  }
  return map;
}

// ===== COMBINE PROMPT BRACKETS WITH STEP 4 OPTIONS =====
function cpCombinePromptAndStep4(mainPrompt, negPrompt, step4Map) {
  var promptBrackets = cpExtractPromptBrackets(mainPrompt, negPrompt);
  var finalVars = [];

  for (var i = 0; i < promptBrackets.length; i++) {
    var varName = promptBrackets[i];
    var options = step4Map[varName] || []; // Match options or empty array

    finalVars.push({
      name: varName,
      bracket: '[' + varName + ']',
      options: options
    });
  }

  return finalVars;
}

// ===== FETCH POST HTML & PARSE STEP 4 =====
function cpFetchVariablesFromPostUrl(url, mainPrompt, negPrompt, callback) {
  if (!url || typeof fetch !== 'function') {
    callback(cpCombinePromptAndStep4(mainPrompt, negPrompt, {}));
    return;
  }

  fetch(url, { credentials: 'same-origin' })
    .then(function (r) { return r.text(); })
    .then(function (html) {
      var doc = new DOMParser().parseFromString(html, 'text/html');
      var body =
        doc.querySelector('.post-body') ||
        doc.querySelector('.entry-content') ||
        doc.querySelector('[itemprop="articleBody"]') ||
        doc.body;

      var text = cpGetTextFromNode(body);
      var step4Map = cpParseStep4MapFromText(text);

      var domMap = cpParseStep4MapFromDom(body);
      for (var k in domMap) {
        if (domMap.hasOwnProperty(k) && !step4Map[k]) {
          step4Map[k] = domMap[k];
        }
      }

      var combined = cpCombinePromptAndStep4(mainPrompt, negPrompt, step4Map);
      callback(combined);
    })
    .catch(function () {
      callback(cpCombinePromptAndStep4(mainPrompt, negPrompt, {}));
    });
}

